window.QUIZ_NATIONAL = (window.QUIZ_NATIONAL||[]).concat([{"q":"일제강점기 산업시설로 당시의 기술수준을 가늠할 수 있는 중요한 자료 및 근거가 되며, 최근까지 정수시설로 사용되어 온 시설로서 보존상태가 비교적 우수하다.","a":"동해 구 상수시설","c":"국가등록문화유산","nc":"","r":"강원특별자치도","s":"동해시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668372.jpg"},{"q":"동·서 쌍탑의 ○○○○○ㆍ○○○○○은 사적 ○○○○○ 안에 있다. 원원사(遠願寺)는 삼국유사에 의하면 밀교(密敎)를 계승한 안혜(安惠)ㆍ낭융(朗融) 등이 김유신ㆍ김의원ㆍ김술종 등과 뜻을 모아 호국의 사찰로 창건하였다고 한다. 동ㆍ○○○○○은 도괴되어 있던 것을 1931년 가을(조선건축사론 중 ○○를 중심으로 한 신라시대 일반형 ○○○○론(건축잡지 1933.11월호. 藤島亥治郞)에 ○○고적보존회에서 복원하였다. 두 탑은 같은 구조와 양식으로 조성된 2중 기단의 ○○○○이며, 하층기단 면석과 갑석 및 상층기단 면석은 각각 8매, 상층기단 갑석은 4매로 구성되어 있다.","a":"경주 원원사지 동·서 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622226.jpg"},{"q":"천주교 신자들을 사형했던 풍남문 밖의 순교터에 지어진 성당이다. 프랑스 신부인 위돌박이 설계·감독을 하였고 1914년에 착공 된 것으로 전해 진다. 회색과 붉은색 벽돌을 이용해 지은 건물은 겉모습이 서울의 명○○○과 비슷하며, 초기 천주교 성당 중에서 매우 아름다운 건물로 손꼽힌다. 비잔틴 양식과 로마네스크 양식을 혼합한 건물로, 국내에서의 아름다운 건축물 중 하나로 꼽힌다.","a":"전주 전동성당","c":"사적","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626854.jpg"},{"q":"○○시의 깊은 산골짜기에 서 있는 규모가 작고 아담한 3층 석탑이다. 이 절터의 유래나 규모는 알 수 없으며, 발견 당시 3층 몸돌이 근처에 새로 지은 제실(帝室)의 주춧돌로 사용되고 있는 등 탑의 각 부분이 흩어져 있었다. 1960년 9월에 전부 수습하여 복원하였다. 탑은 1단의 기단(基壇)만을 두어 특이한 형태이며, 그 위로 3층의 탑신(塔身)을 세우고 있다. 기단은 남북면에만 모서리에 기둥을 새겨두었고, 동서면에는 남북면의 사잇돌을 밀어 넣어 맞추었다. 탑신의 몸돌과 지붕돌은 각각 한 돌로 구성하였으며, 몸돌의 네 모서리마다 기둥의 모양을 본떠 새겨두었다.","a":"문경 내화리 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620027.jpg"},{"q":"화성의 화서문 옆에 위치하고 있으며, 조선 정조 20년(1796)에 건립되었다. ○○○○○은 화성 서북측 성벽에서 돌출시켜 남측면의 일부만 성곽에 접하고 나머지 3면이 돌출된 평면을 이루고 있다. 3층 구조로 하부 치성(雉城)은 방형의 석재를 사용하였고 1층과 2층 외벽과 3층 하부는 전돌로 쌓았다. 1, 2층 각 면에는 6개의 총안(銃眼)이 있으며, 3층에는 여장(女墻)을 쌓고 같은 높이에 4개의 총안을 내었다. 3층 포루(鋪樓)는 정면 2칸, 측면 2칸의 팔작 기와지붕으로 벽면 위쪽의 판문에는 전안(箭眼)이 설치되어 있다.","a":"수원 서북공심돈","c":"보물","nc":"","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616210.jpg"},{"q":"○○○는 덕숭산에 자리잡고 있는 절로, 절에 남겨진 기록에는 백제 후기 숭제법사가 처음 짓고 고려 공민왕 때 나옹이 다시 고친 것으로 기록되어 있고, 또 다른 기록에는 백제 법왕 1년(599)에 지명법사가 짓고 원효가 다시 고쳤다고도 전한다. 석가모니불상을 모셔 놓은 ○○○은 고려 충렬왕 34년(1308)에 지은 건물로, 지은 시기를 정확하게 알 수 있는 우리 나라에서 가장 오래된 목조건물 중의 하나이다. 앞면 3칸·옆면 4칸 크기이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕으로 꾸몄다.","a":"예산 수덕사 대웅전","c":"국보","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612236.jpg"},{"q":"오래 전부터 근처에 있는 창기마을의 이름을 붙인 ‘창기사발’을 만들던 가마터로 알려진 곳이며, 조선 중기인 16∼17세기경 지방에서 사용하던 백자를 만들던 곳이기도 하다. 마을 뒷산의 기슭에서 산 윗부분까지 가마터가 여러 곳이 남아있는데, 사적으로 지정된 이 곳은 사람들이 생활하는 집과 무덤들이 들어서면서 많이 훼손된 상태이다. 발견되는 그릇 조각들을 보면 마을 근처에 있는 가마터는 대체적으로 17세기의 것이고, 산 쪽에 있는 가마터는 대부분 16세기경의 것이다. 아마도 산 윗쪽에 가마를 먼저 만들기 시작하고, 이후에 점차 아래로 내려온 것으로 추측할 수 있다.","a":"양산 법기리 요지","c":"사적","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628207.jpg"},{"q":"영주정사 1903년, ○○○ 1909년 건립 이곳은 조선 후기 ○○ 출신 유학자 박만환이 강당 ○○○○○ 사당 ○○○를 건립하여, 후진을 양성하고 중국 오성육현(五聖六賢)의 영정을 봉안한 곳이다. 강당을 앞에 두고 뒤쪽 높은 곳에 사당을 건축하여, 전체적으로 ‘二자형’을 이루고 있다. 강당에 주거형 평면을 도입하여 난방의 효율성과 공간 이용의 합리성을 추구한 근대기 건축의 특징을 잘 보여주고 있다.","a":"정읍 영주정사와 영양사","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668767.jpg"},{"q":"석가가 설법하는 장면인 ○○○상도를 그린 괘불이다. 괘불이란 절에서 큰 법회나 의식을 행하기 위해 법당 앞뜰에 걸어놓고 예배를 드리는 대형 불교그림을 말한다. 전체 1,022.3×635㎝ , 화면 943×619㎝ 크기의 이 괘불은 본존불인 석가를 중심으로 양옆에 문수보살과 보현보살이 배치되어 있다. 화면 중심에 꽉 차게 배치되어 있는 석가는 얼굴이 둥글고 원만하며, 예배자의 시선을 의식한 듯 당당하게 표현하였다. 두 어깨를 걸친 옷은 중후하게 묘사하였고, 가슴 중앙에 ‘卍’ 자를 크게 그려 넣어 눈에 띈다.","a":"청곡사 영산회 괘불탱","c":"국보","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1613111.jpg"},{"q":"이 집은 ○○도 개척당시(1883년)에 있던 ○○도 재래의 집 형태를 간직하고 있는 ○○집으로 1940년대에 건축한 것이다. 이집은 5칸 일자집으로 지붕은 ○○로 이었다. 큰방, 중간방, 갓방은 전부 귀틀구조로 되어있는데 큰방과 중간방은 정지에서 내굴로 되었고 갓방은 집 외부에 돌린 우데기를 돌출시켜 별도의 아궁이를 설치하였다. 집 주위에는 전부 우데기를 돌리고 앞부분에는 폭을 넓게 잡은 죽담이 있다. 또한, ○○○은 1945년대에 건립한 것으로서 본래 3칸 집이었으나, 한칸을 달아내어 현재는 4칸으로 되어있다.","a":"울릉 나리 너와 투막집과 억새 투막집","c":"국가민속문화유산","nc":"","r":"경상북도","s":"울릉군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635661.jpg"},{"q":"조선시대 경상북도 상류주택의 생활상을 잘 보존하고 있는데, 특히 종택의 건축용도에 따른 가옥배치법은 경북 내륙북부지역과 다른 북동부지역 상류주택의 특성을 지니고 있다. 유형적 요소인 건축뿐만 아니라 무형적 요소인 제례, 민속품, 동제 등 민속신앙 및 행위들이 잘 보존 전승되고 있으며 문서 등 기록물도 잘 남아있으며, 400년간의 영양남씨 가문의 역사성을 유지·전승하고 있다.","a":"영덕 난고종택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635733.jpg"},{"q":"○○○은 1919년 3·1운동 때에는 손병희(孫秉熙)의 사위로서 3·1운동 준비에 협력하였으며, 1923년에 고한승(高漢承) 등과 「색동회」를 조직하여 5월 1일을 첫 ‘어린이날’로 제정 선포하였다. 1931년 “어린이를 두고 가니 잘 부탁하오”라는 유언을 남기며 운명하신 날까지 어린이를 위한 찬연한 역사의 발자취를 남기신 분이다.","a":"망우 독립유공자 묘역 - 방정환 묘소","c":"국가등록문화유산","nc":"","r":"경기도","s":"구리시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2017103013235200.JPG"},{"q":"○○○는 봉미산 기슭에 있는 조선시대의 절로, 원래는 신라시대에 지었다고 하나 정확한 기록은 남아 있지 않다. ○○○은 절에서 덕이 높은 승려의 초상화를 모셔놓은 건물로, ○○○○○에는 불단 뒷벽 중앙에 지공을, 그 좌우에는 무학과 나옹대사의 영정을 모시고 있다. 조선 전기 예종 때 지은 것으로 보이며, 낮은 기단 위에 앞면 1칸·옆면 2칸으로 세웠다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양의 팔작지붕이다. 지붕 처마를 받치는 장식구조는 기둥 위뿐만 아니라 기둥 사이에도 있는데, 이러한 구조를 다포 양식이라 한다.","a":"여주 신륵사 조사당","c":"보물","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615682.jpg"},{"q":"○○○○○의 전신인 보성전문학교의 경영을 맡았던 김성수가 1933년 공사를 시작하여 1934년에 완성한 ○○건물로 박동진이 설계하였다. 3층(중앙탑은 6층)이며 화강석을 주재료로 한 좌우대칭의 고딕양식으로 되어 있다. 평면 H자형이며, 중앙에는 넓은 홀이 있다. 건물 현관의 두 돌기둥에는 학교의 기상을 상징하는 호랑이 상이 조각되어 있고, 중앙 후문의 돌기둥에는 무궁화가 조각되어 있다. 건축 당시에는 내·외부가 호화스럽고 웅장하여, 국내의 학교 건축물로서는 유례가 없는 훌륭한 것이었다.","a":"서울 고려대학교 본관","c":"사적","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624942.jpg"},{"q":"○○○는 신라 진흥왕 13년(552) 때 의신(義信)이 세운 사찰이다. 이 석탑은 일반적인 가람배치와 달리 대웅전의 앞이 아니라 사방이 한 눈에 조망되는 북쪽 낮은 봉우리에 있다. 석탑이 사방의 조망권이 확보된 위치에 건립된 것으로 보아 고려시대에 이르러 성행했던 산천비보(山川裨補)사상에 의해 건립된 것으로 추정된다. 산천비보사상이란, 탑이나 건물을 건립해 산천의 쇠퇴한 기운을 북돋아준다는 것이다. 같은 모양의 석탑 2기는 이층 기단 위에 3층의 탑신을 올렸다.","a":"옥천 용암사 동·서 삼층석탑","c":"보물","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617259.jpg"},{"q":"○○○○○ 삼막골 ○○○은 6세기 후반 신라가 한강유역 진출후 9세기까지 조성된 유적으로 충청 이북지역에서 확인된 신라○○○ 중 가장 장기간에 걸친 유적으로서 학술적 가치가 매우 크다. 충청·경기지역 소재 신라○○○ 중 충주 누암리○○○, 여주 매룡리○○○에 필적하는 것으로서 지금까지 발굴결과 유구가 잘 남아있고 유물도 다수 출토되는 등 역사적, 학술적 가치가 뛰어나다. <br/><b>※(○○○○○ → ○○○○○)으로 명칭변경 되었습니다.(2011.07.28 고시)</b>","a":"용인 보정동 고분군","c":"사적","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626062.jpg"},{"q":"선산은 신라에 불교가 처음 전파되었을 때와 인연이 있는 곳으로 거대한 석탑이 많이 남아 있다. 이 일대의 경작지에서 연꽃무늬가 새겨진 막새기와를 비롯하여 많은 기와조각과 토기조각 등이 발견되어 이 부근이 절터였음을 알 수 있다. 현재 이 탑은 약간의 손상이 있으나 비교적 완전한 형태로 남아 있으며, 통일신라시대의 전형적인 석탑양식인 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 기단부는 아래층 기단 가운데돌에 모서리기둥 2개와 가운데기둥 3개, 즉 한 면에 5개의 기둥이 새겨져 있다.","a":"구미 낙산리 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621031.jpg"},{"q":"광배(光背)와 대좌(臺座)를 따로 가지고 있는 독립된 불상이 삼존불(三尊佛)을 이루고 있다. 본존불은 당당한 체구의 불상으로 머리에는 큼직한 상투 모양의 머리묶음이 있고, 직사각형에 가까운 얼굴에서는 강인한 인상을 풍기고 있다. 어깨는 넓고 당당하며 군데군데 옷 사이로 드러난 신체 역시 당당하고 강인한 느낌을 준다. 양 어깨에 걸쳐 입은 옷은 가슴에서 발목 부분까지 U자형의 주름을 이루면서 내려오고 있으며, 다리 사이에는 바지 자락이 표현되어 있다.","a":"청양 읍내리 석조여래삼존입상","c":"보물","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617602.jpg"},{"q":"○○○○○은 ○○ 황남동에 있는 미추왕릉 지구에서 발견된 길이 36㎝의 칼이다. 1973년 ○○○ 공사 때 노출된 유물의 하나로, 철제 칼집과 칼은 썩어 없어져 버리고 금으로 된 장식만이 남아 있다. 시신의 허리 부분에서 발견되었는데, 자루의 끝부분이 골무형으로 되어 있고 가운데 붉은 마노를 박았다. 칼집에 해당되는 부분 위쪽에 납작한 판에는 태극무늬 같은 둥근무늬를 넣었다.","a":"경주 계림로 보검","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621316.jpg"},{"q":"○○○의 대웅전 앞에 서 있는 탑으로, 2단 기단(基壇)위에 3층의 탑신(塔身)을 쌓아 올린 모습이다. 기단과 탑신의 몸돌에서 기둥 모양을 본떠 새긴 것이 뚜렷하게 보이지만, 불에 타서 심하게 손상된 상태이다. 얇고 평평한 지붕돌은 밑면의 받침을 4단씩 두었으며, 수평을 이루던 처마는 네 귀퉁이에서 크게 치켜 올려져 있다. 지붕돌의 모습으로 보아 통일신라 후기에 세워진 작품임을 알 수 있으며, 당시의 석탑 양식을 살피는 데에 좋은 자료가 되고 있다.","a":"산청 덕산사 삼층석탑","c":"보물","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622884.jpg"},{"q":"○○○○○은 풍산 유씨의 동족마을로 빼어난 자연 경관과 민속·유교전통을 잘 유지하고 있는 조선시대 양반촌이다. 이 집은 서애 유성룡(1542∼1607) 선생의 손자 유만하 공이 충효당(보물)에서 분가할 때 지은 것이다. 뒤에 유만하 공의 아들 주일재 유후장 공이 늘려 지었다고 하는데, 집 이름도 선생의 호에서 따 온 것이다. ○○○○ 남촌 충효당 뒷편 골목에 있으며 문간채, 사랑채, 안채, 광채, 사당채로 구성되어 있다. 골목으로 이어진 담장 중간 끊어진 곳으로 들어서면 사랑채와 문간채가 있고 안마당을 들어서 왼쪽에 광채, 앞쪽에 안채가 자리잡고 있다.","a":"안동 하회마을 양오당 고택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635093.jpg"},{"q":"○○○는 전라남도 ○○의 월출산 동남쪽에 있는 사찰이다. 신라의 명승 원효(元曉)가 창건하여 ‘관음사’라 하였고, 명종 5년(1550) 태감(太甘)이 4번째로 세우면서 ○○○라 하였다. 이 탑비는 선각대사 형미(逈微)를 기리기 위해 세운 것으로, 고려 정종 원년(946)에 건립되었다. 선각대사는 신라 말의 명승으로, 당나라에 건너가서 14년만에 돌아와 ○○○에 8년간 머물렀다. 고려 태조 원년(918)에 54세의 나이로 입적하자 고려 태조가 ‘선각’이라는 시호를 내리고, 탑이름을 ‘편광영탑’이라 하였다. 이 비는 대사가 입적한 지 28년만에 세워진 것이다.","a":"강진 무위사 선각대사탑비","c":"보물","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619240.jpg"},{"q":"○○○은 경주 황남동고분 제155호 무덤으로 1973년 발굴하여 금관, 팔찌 등 많은 귀중한 유품들과 함께 천마 그림이 발견되어 ○○○이라 부르게 되었다. ○○○○○는 칼 중에서 손잡이 끝부분에 둥그런 고리가 붙어있고 그 고리안에 용이나 봉황, 나뭇잎들을 조각하여 그 소장자의 신분이나 지위를 나타내 주는 칼이다. ○○○에서 고리자루큰칼은 칼자루에 손상이 있을 뿐 양호한 상태를 유지하고 있으며, 유골의 왼쪽부분에서 발견되었다. 칼집과 칼자루는 나무로 만들어 그 위에 얇은 금동을 입혔다. 칼자루 끝 둥근 모양 안에 봉황으로 보이는 새의 머리가 붙어있다.","a":"천마총 환두대도","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621297.jpg"},{"q":"낙안성 남문의 가운데로 뻗어 있는 큰 길에 접해있는 첫번째 초가집이다. 담장을 쌓지 않고 비워둠으로써 대문의 역할을 하고 있는 대문간을 들어서면 바로 왼쪽에 '田'자 모양의 집이 자리잡고 있다. 낙안성 안의 유일한 '田'자형 집인데, 땅이 좁아서 택한 평면이라 여겨진다. 방 2개, 점포, 부엌으로 구성이 된 이 집은 대문간의 첫칸이 방이고 다음칸이 부엌이다. 방의 뒷쪽으로는 점포로 사용되던 마루방이 있고 그 옆에 안방이 있다. 방의 앞쪽으로는 각각 툇마루를 달아 개방하였다. 벽은 흙벽인데 부엌의 옆 벽면은 돌로 쌓았다.","a":"순천 낙안읍성 주막집","c":"국가민속문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634599.jpg"},{"q":"○○○는 신라 진흥왕 14년(553)에 ○○ 월성의 동쪽에 궁궐을 짓다가, 그곳에서 황룡(黃龍)이 나타났다는 말을 듣고 절로 고쳐 짓기 시작하여 17년 만에 완성되었다. 그 후 574년, 인도의 아소카왕이 철 57,000근·금 3만분으로 석가삼존불상을 만들려다 뜻을 이루지 못하고 금과 철, 그리고 삼존불상의 모형을 배에 실어 보낸 것이 신라 땅에 닿게 되자, 이것을 재료로 삼존불상을 만들게 되었는데, 5m가 넘는 이 불상을 모시기 위해 진평왕 6년(584)에 금당을 짓게 되었다.","a":"경주 황룡사지","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627503.jpg"},{"q":"속리산 기슭에 있는 ○○○는 신라 진흥왕 14년(553)에 처음 지었고, 혜공왕 12년(776)에 다시 지었다. 임진왜란으로 모두 불탄 것을 인조 2년(1624)에 벽암이 다시 지었으며 그 뒤 여러 차례 수리를 거쳐 오늘에 이르고 있다. ○○○○은 앞면 3칸·옆면 3칸 규모의 정사각형 1층 건물로, 지붕은 중앙에서 4면으로 똑같이 경사가 진 사모지붕이다. 지붕 처마를 받치기 위해 장식하여 짜은 구조가 기둥 위에만 있는 주심포 양식으로 꾸몄다. 건물 안에는 앉은키 2.8m의 금색 목조 관세음보살상을 모시고 있다.","a":"보은 법주사 원통보전","c":"보물","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617138.jpg"},{"q":"오동사터에 서있는 탑으로, 2단의 기단(基壇) 위에 5층의 탑신(塔身)을 쌓아 올렸다. 기단은 아래층 기단이 너무 낮아 마치 바닥돌처럼 보인다. 위층 기단의 남쪽 면에는 승려의 모습이 돋을새김되어 있어 흥미롭다. 탑신은 각 층의 몸돌과 지붕돌을 각각 하나의 돌로 새겨 쌓았는데, 1층 몸돌만은 4장의 판판한 돌을 사방으로 세워 구성하였다. 각 층의 몸돌마다 네 모서리에 기둥을 본 뜬 조각이 보이며, 1층 몸돌의 크기에 비해 2층은 눈에 띄게 작아져 있다.","a":"보성 봉천리 오층석탑","c":"보물","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619513.jpg"},{"q":"양감이 좋은 15세기의 전형적인 ○○○○ 형태에 특징적인 상감문양이 장식된 병이다. 어깨와 아랫도리에는 흰 선상감으로 연판문대를 돌리고, 그 사이 동체 중심에는 모란과 버드나무를 엇갈려 4곳에 배치하였다. 앞·뒷면에는 각기 모양이 다르게 모란을 큼직하게 장식하고 그 사이에는 늘어진 버드나무를 흰 선상감으로 도안화시켜 베풀었다. 특히 강하게 추상화된 매우 율동적인 모란문을 면상감으로 처리하고 검은 윤곽선을 돌려 대담하게 표현한 부분이 눈길을 끈다. 약은 회록색을 띄고 광택이 좋으며 굽바닥에 모래를 받쳐 구웠다.","a":"분청사기 상감모란양류문 병","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614913.jpg"},{"q":"향로란 절에서 의식을 행하거나 불단 위에 올려놓고 향을 피우는데 사용하는 공양구이다. 특히 완형(盌形)의 몸체 아래 나팔형으로 벌어져 원반형의 받침을 지닌 것을 ○○이라 하였다. ○○○○○은 높이 37㎝, 지름 51㎝로 고려시대 ○○ 가운데 큰 작품에 속한다. 몸통 표면 전체에 가는 은실로 무늬가 입사되었다. 입에 있는 넓은 테인 전의 표면에는 연꽃 덩굴무늬가 있고, 가장자리 면에는 번개무늬가 있다. 몸통 중앙에 서로 마주보는 4곳에 이중의 원을 돌리고, 안에는 굵게 한자씩 범자를 새기고, 그 주위를 돌아가며 여의두문을 새겼다.","a":"봉은사 청동 은입사 향완","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613250.jpg"},{"q":"1943년 건립 이 건물은 ○○○○으로 지어져 쓰이다가 1995년 충무시와 통영군이 통합되면서 2002년까지 통영시청 별관으로 사용되었다. 2002년부터 ‘통영국제음악제 페스티벌하우스’라는 이름으로 세계적인 음악가를 기리는 장소로 사용되다가 2013년부터 ‘통영시립박물관’으로 사용되고 있다. 주 출입구가 있는 가운데 부분이 약 1m정도 돌출되어 전체적으로 좌우 대칭을 이루며, 2층 위쪽에 국기봉을 꽂을 수 있는 게양대를 반원형 기둥 모양으로 구성하였다.","a":"구 통영군청","c":"국가등록문화유산","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669303.jpg"},{"q":"공주시 ○○○○에서 발견된 백제 때 만들어진 ○○이다. ○○란 좁게는 궁전이나 무덤 앞에 세워두거나 무덤 안에 놓아두는 돌로 된 동물상을 말한다. ○○○○○는 높이 30.8㎝, 길이 49㎝, 너비 22㎝로 통로 중앙에서 밖을 향하여 놓여 있었다. 입은 뭉뚝하며 입술에 붉게 칠한 흔적이 있고, 콧구멍 없는 큰 코에 눈과 귀가 있다. 머리 위에는 나뭇가지 형태의 철제 뿔이 붙어있다. 몸통 좌우, 앞·뒤 다리에는 불꽃무늬가 조각되어 있는데 이는 날개를 나타낸 것으로 보인다. 꼬리가 조각되어 있으며 배설 구멍이 달려 있을 정도로 사실적이다.","a":"무령왕릉 석수","c":"국보","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612294.jpg"},{"q":"이 책은 검푸른 색의 종이에 은가루를 사용해서 직접 불경의 내용을 옮겨 적은 것으로, 두루마리처럼 말아서 보관할 수 있도록 되어 있다. 전체 30권 중 ○○○에 해당하는 것으로 크기는 세로 30.4㎝, 가로 905㎝이며, 일본으로 유출되었던 것을 되찾아온 것이다. 책 앞의 제목 끝에는 천자문의 한 글자인 ‘모(慕)’자가 표시되어 있어 천자함(千字函:천자문의 순서에 따라 책의 번호를 매기는 방법)을 사용했음을 알 수 있으며, 더불어 이 책이 대장경 중의 하나임을 알 수 있다.","a":"감지은니 불공견삭신변진언경 권13","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611666.jpg"},{"q":"통일신라 후기의 유명한 승려인 진감선사의 탑비이다. 진감선사(774∼850)는 불교 음악인 범패를 도입하여 널리 대중화시킨 인물로, 애장왕 5년(804)에 당나라에 유학하여 승려가 되었으며, 흥덕왕 5년(830)에 귀국하여 높은 도덕과 법력으로 당시 왕들의 우러름을 받다가 77세의 나이로 ○○○에서 입적하였다. 비는 몸돌에 손상을 입긴 하였으나, 아래로는 거북받침돌을, 위로는 머릿돌을 고루 갖추고 있는 모습이다. 통일신라 후기의 탑비양식에 따라 거북받침돌은 머리가 용머리로 꾸며져 있으며, 등에는 6각의 무늬가 가득 채워져 있다.","a":"하동 쌍계사 진감선사탑비","c":"국보","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1613019.jpg"},{"q":"○○○○○는 석가가 설법하는 장면을 묘사한 그림으로, 대개 불상의 뒷벽에 위치한다. 이 ○○○○○의 석가여래는 오른쪽 어깨가 드러나는 우견편단의 옷을 걸쳤으며, 손가락을 땅으로 향하게 하여 마귀를 물리치는 의미를 지닌 항마촉지인의 손모양을 하고 앉아 있다. 석가여래 주변으로 10대 보살, 사천왕상, 상단의 10대 제자 등이 배열되어 있다. 주로 ○○○○○에서는 8대보살이 그려지는데, 이 그림에서는 10대보살을 표현한 점과 석가불 아래의 그 보살이 유난히 큰 점이 특징이다.","a":"불영사 영산회상도","c":"보물","nc":"","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622160.jpg"},{"q":"○○○는『 ○○○사적』에 따르면 백제 법왕(600)때 세운 절이라고 한다. 이 건물은 원래 미륵전 뜰 가운데 세운 목조탑으로 불경을 보관하던 곳이었는데, 지금은 예전의 기능은 없어지고 안에 불상을 모시고 있다. 조선 인조 13년(1635)에 다시 짓고, 1922년에 지금 있는 위치로 옮겼다. 지붕 위에 남아 있는 조각들은 목조탑이었을 때 흔적이며 건물 안에는 석가모니와 가섭, 아난의 제자상을 모시고 있다. 규모는 앞면 3칸·옆면 3칸 크기이며 지붕은 옆면이 여덟 팔(八)자 모양을 한 팔작지붕이다.","a":"김제 금산사 대장전","c":"보물","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618552.jpg"},{"q":"○○○○ <○○○○○>은 조선 후기의 화가 단원 ○○○가 그린 산수화와 풍속화 등을 모은 ○○이다. ○○○는 산수화와 인물화, 신선화와 풍속화 등을 모두 잘 그려서 풍속화에서는 새로운 경지를 개척하였고, 산수화와 화조화 등에서는 자기만의 뚜렷한 화풍을 이룩했다. 총 20면으로 된 이 ○○에 있는 각 그림의 크기는 가로 36.6㎝, 세로 26.7㎝ 정도이고, 그림은 종이에 먹으로 그린 후 엷게 색칠하였다. 한지에 그린 그림을 두껍고 빳빳한 양지에 붙여 10면을 1첩으로 하여 2첩을 한 갑에 넣어 1면씩 열어 볼 수 있도록 만들었다.","a":"김홍도 필 병진년 화첩","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613911.jpg"},{"q":"선조의 5번째 아들이자 인조의 아버지인 원종(1580∼1619)과 부인 인헌왕후(1578∼1626)의 무덤이다. 인조반정(1623)으로 아들 능양군인 인조가 왕위에 오르자 대원군에 봉해졌고, 인조 10년(1633) 원종의 칭호와 함께 그의 무덤을 ○○으로 불렀다. 왕릉과 왕비릉이 나란히 있는 쌍릉으로, 병풍석이나 난간석은 설치하지 않고 보호석만 둘렀다. 무덤 아래에는 영조 29년(1753)에 세운 '조선국원종대왕○○ 인헌왕후부좌(朝鮮國元宗大王章陵 仁獻王后祔左)’라고 새긴 비각이 있다. <br/><b>※(○○ → ○○○○)으로 명칭변경 되었습니다.","a":"김포 장릉","c":"사적","nc":"","r":"경기도","s":"김포시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625609.jpg"},{"q":"조계산에 있는 ○○○는 우리나라 3대 사찰 중 하나로 매우 유서 깊은 절이다. ‘송광’이라는 절 이름은 조계산의 옛 이름인 송광산에서 따 왔다고 하는데 절을 언제 세웠는지는 정확한 자료가 없어 알 수 없다. 절의 기록에 이 건물은 조선 인조 17년(1639)에 세웠고 영조 12년(1736)에 수리하였다고 한다. 지금 있는 건물은 1973년에 보수한 것이다. ○○○에는 석가모니불상을 모시고 석가의 생애를 8단계로 나누어 그린 팔상도가 있으며, 이외에도 석가가 설법하는 장면을 담은 영산대회 그림도 볼 수 있다.","a":"순천 송광사 영산전","c":"보물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619038.jpg"},{"q":"○○ 주산(主山)근처 구릉 끝에 있는 10여 기의 무덤 중 하나로 ○○의 흔적이 남아있는 무덤이다. 동서길이 약 25m, 남북길이 약 20m의 봉분으로 된 활천장(궁륭식천장)을 가진 굴식돌방무덤(횡혈식석실분)이다. 유물은 도굴되어 없고, 널방(현실)에는 동쪽에 부인의 관, 서쪽에는 남편의 관이 놓여있고, 바닥에 도랑을 설치하였다. 널방에는 ○○의 흔적이 약간 남아 있으나 알 수 없고, 천장돌에 분홍색·백색·녹색·갈색 물감을 이용하여 연꽃장식을 그렸다.","a":"고령 고아리 벽화 고분","c":"사적","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627756.jpg"},{"q":"ㅇ영등포 ○○○○○은 한국의 근대산업에서 빼 놓을 수 없는 산업시설로 역사적, 사회적 의미가 매우 크다. 이 건물은 (주)○○○○의 ○○○으로 1936년 건립이래 건물 원형을 대부분 간직하고 있는 점에서 역사적, 건축사적으로 가치가 있다. 일제강점기에 한국인자본에 의해 설립된 산업관련건축물로 근대 공업사적 자료로서 가치가 있는 건물이다. 단지내 재개발공사로 인하여 2009년에 이전, 복원공사를 실시하였다.","a":"서울 구 경성방직 사무동","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"영등포구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1666991.jpg"},{"q":"○○○○은 기단에서 상륜부까지 완전한 모습을 갖추고 있는 모전석탑으로, 석회암 지대라는 지역 특성을 반영하여 고회암(苦灰巖)으로 제작되었고, 쇠퇴한 산천의 기운을 북돋운다는 ‘산천비보(山川裨補) 사상’과 사리신앙을 배경으로 높은 암벽 위에 조성된 특수한 석탑임. 특히, 탑지석을 비롯한 자료에서 수리기록과 연혁을 알 수 있고, 모전석탑으로 조성된 진신사리 봉안탑으로는 우리나라에서 유일하다는 점에서 국가지정 문화유산(국보)으로 역사·예술·학술 가치가 충분함.","a":"정선 정암사 수마노탑","c":"국보","nc":"","r":"강원특별자치도","s":"정선군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/2020062509423800.jpg"},{"q":"ㅇ 충청북도 ○○군 소재 ○○○○○은 지방에 존재하는 가장 큰 규모의 한성백제 시기 토축 산성으로, 내성과 외성의 이중 구조로 된 남성·북성의 독특한 배치를 이루고 있으며 초기단계의 판축기법과 성토다짐이 사용되었고 한성백제 단계의 성문과 수문의 발전 양상을 보여주는 점, 다양한 출토 유물을 통해 당시의 국제정세를 파악할 수 있을 뿐만 아니라 성벽의 잔존상태가 양호하여 한성백제 산성의 특성, 축성기법 등에 관한 연구에 있어서 중요한 학술적 가치를 지님","a":"증평 추성산성","c":"사적","nc":"","r":"충청북도","s":"증평군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626404.jpg"},{"q":"조선 중기 이름난 문신이었던 서애 류성룡(1542∼1607) 선생의 집이다. 류성룡 선생은 여러 벼슬을 두루 거치고 임진왜란 때에는 영의정으로 전쟁의 어려운 상황을 이겨내는데 많은 공헌을 한 분이다. 선생이 쓴『징비록』과『서애집』은 임진왜란사 연구에 빼놓을 수 없는 귀중한 자료로도 평가 받고 있다. ○○○은 행랑채, 사랑채, 안채로 구성되어 있다. 사랑채와 안채는 손자인 졸재 류원지(1598∼1674)가 짓고, 증손자인 눌재 류의하(1616∼1698)가 확장 수리한 것이다.","a":"안동 하회 충효당","c":"보물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620846.jpg"},{"q":"○○○은 고대부터 전해져 내려 온 궁궐건축의 제도인 전조후침 및 삼문삼조의 기본배치 원리에 따라 외조, 치조, 연조의 구역으로 크게 나뉘어지며 각기 제 기능에 따른 전각이 배치되었다. 치조 구역에는 ○○○의 정전인 근정전이 있고, 그 뒤로 ○○○, 만춘전, 천추전이 자리 잡고 있다. ○○○은 왕이 평상시 거처하며 정사를 보살피던 곳으로 근정전에서 뒤편으로 사정문을 지나면 정면에 위치하며, ○○○의 동측으로 만춘전과 서측으로 천추전이 있다.","a":"경복궁 사정전","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615013.jpg"},{"q":"○○○○○은 조선시대 전패와 궐패를 모시고 망궐례를 행하던 객사 건물로서, 창건 시기는 정확히 알 수 없으나 각종 기록과 구조양식으로 보아 전체적인 건축물의 규모와 골격은 1617년 중수시의 것을 유지하고 있다고 추정되며, 목조 가구와 세부 공포형식은 1775년과 1885년 중수시의 기법을 보여주고 있다. ○○○은 주심포계 양식의 요소를 채용한 익공계 공포 구성이 돋보이며, 1출목 3익공식의 공포형식은 제한된 공력으로 충분한 위계를 드러내고자는 의도에서 만들어진 변형 기법으로 볼 수 있다.","a":"나주 금성관","c":"보물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2019102508051000.jpg"},{"q":"○○○○○는 선조 때의 문신인 ○○○이 1583년에서 1587년 사이에 관원으로서 참여했던 계 모임을 그린 6폭의 그림이다. ‘괴원장방○○○’(槐院長房契會圖,1583년경), ‘봉산○○○’(蓬山契會圖,1583년), ‘태상○○○, ‘예조낭관○○○’(禮曹郎官契會圖,1586년), ‘형조낭관○○○’(刑曹郎官契會圖,1586년), ‘미원○○○’(薇垣契會圖,1587년)로 구성되어 있는데, 봉산○○○, 태상○○○, 형조낭관○○○는 16세기 전반 안견파의 편파구도 산수의 전통을 토대로 경물들의 분리가 확대된 변화를 보여준다.","a":"정사신 참석 계회도 일괄","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614833.jpg"},{"q":"○○○ 기슭에 위치한 ○○○은 무속신앙에서 섬기는 여러 신을 모신 당집으로 요란한 굿판을 벌이기 쉽도록 인가에서 멀리 떨어진 산 속에 세운 ‘굿당’에 속한다. 원래 남산 꼭대기에 있었던 것을 일본인들이 남산에 조선신궁(朝鮮神宮)을 지으면서 이전을 강요하자 건물을 해제하여 현재의 ○○○ 기슭에 옮겨 원형대로 복원한 것이다. ○○○을 택한 이유는 이곳이 풍수지리설에서 명당에 속하고 현재 무속신으로 모셔지는 조선 태조와 무학대사가 기도하던 자리이기 때문이다. 앞면 3칸·옆면 2칸이고 양끝의 2칸은 이곳으로 이전한 후 새로 지은 것이다.","a":"인왕산 국사당","c":"국가민속문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633071.jpg"},{"q":"○○○은 1동, 1층 규모로 건축면적 56.99㎡이다. ○○○은 중앙선로의 역사로 1939년 건립된 것으로 판단되며, 1939년 4월 1일 보통역으로 영업을 개시하였다. 가구는 목조양식으로 일자형의 장방형 평면 구성은 대합실, 사무실, 숙직실이 배치되었다. 간이역은 폐역되었으나, 내부에 전시물을 설치하여 개방할 예정이다.","a":"남양주 구 팔당역","c":"국가등록문화유산","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668086.jpg"},{"q":"『○○○○○』은 인도의 미륵보살이 지은 글을 당나라의 현장(602∼664)이 번역하여 천자문의 순서대로 100권을 수록한 것으로, 11세기에 간행한 초조대장경 가운데 하나이다. 이 가운데 ○○○은 습(習)자의 함에 들어있는 것으로, 종이질은 닥나무종이이며, 가로 45㎝, 세로 28.5㎝이다. 처음 새긴 본으로 『현양성교론』 권11(국보)과 같이 11세기에 새겨 인출한 것으로 보인다. 후에 다시 새긴 본과는 판식과 간행기록이 서로 다르며, 처음에 새긴 이 본은 경(敬)자, 경(竟)자가 각각 횟수가 빠져있으나, 다시 새긴 본은 모두 완전하게 고쳐 새겨지고 있다.","a":"초조본 유가사지론 권17","c":"국보","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612046.jpg"},{"q":"조선 후기 화가인 ○○이 그린 홍매화그림의 8첩 병풍이다. ○○은 그림을 담당하던 국가기관인 도화서 화원으로 인물화, 풍속화, 산수화에 뛰어났다. 매화를 그린 것은 이것이 유일한 작품이다. 가로 378㎝, 세로 112㎝의 커다란 화면 전체에 가지를 펼친 매화나무를 능숙한 필치로 처리하였다. ○○이 그린 유일한 매화그림인 이 그림의 왼쪽 아래쪽에 자필로 쓴 찬문이 있다.","a":"유숙 필 매화도","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614679.jpg"},{"q":"○○○○○은 의원동, 주택동, 병동이 동일 구조 및 일체화된 지붕으로 건축되었고, 주택동은 별도의 출입구와 마당을 두어 의원동과 분리되게 구성하였으며, 의원동에 접한 병동은 ‘ㄷ’자 형태의 툇마루로 별동의 단층병동과 연결되어 있다. 해방이후 건립된 지방의료시설로 의원, 주택, 병동 건축물 모두가 잘 남아있어 의료사적, 건축사적 보존가치가 높다.","a":"거창 구 자생의원","c":"국가등록문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669537.jpg"},{"q":"제당은 마을의 신앙의식을 행하는 곳으로 인간의 일상생활과는 엄격하게 구분되는 성지의 하나이다. 장군봉과 마을 입구에 넓게 분포하는 ○○○○○은 신을 모셔놓고 위하는 집(당집)과 여러 개의 신이 있다고 믿고 섬기는 대상물(당산)로 구성된다. 장군당 안의 장군신도(將軍神圖)와 2개의 목마 중 큰 목마, 원항마을 입구의 돌장승이 국가민속문화유산으로 지정되어 있다. 그밖에도 천제당과 당산나무 10여 그루, 나머지 돌장승 2쌍이 이곳의 동제당이다. 장군봉 정상에 위치한 장군당과 천제당은 각각 장군신과 천신을 모신 곳으로서 규모가 작고 조촐한 건물이다.","a":"삼덕리 마을제당","c":"국가민속문화유산","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635776.jpg"},{"q":"1912년 건립된 이 건물은 일제 강점기 당시 잔악한 일본의 대명사였던 헌병대가 민중을 억압하고 독립투사들에게 가혹 행위를 자행했던 곳으로 일제 강점기의 뼈아픈 역사를 간직하고 있다. 벽면 전체에 돌림띠를 둘러 장식하고 수직의 긴 창을 반복적으로 배치하는 등 관공서 건축물로서의 권위적인 형태를 나타내고 있다.","a":"구 마산헌병 분견대","c":"국가등록문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669416.jpg"},{"q":"<개요> 1919년 3.1운동 당시 제암리 학살사건을 전 세계로 타전한 AP통신사 특파원이었던 ○○○○○와 그의 아내(Mary Linley Taylor)가 거주를 위해 1923년부터 건립한 ○○으로, 역사적 인물의 삶을 조명하고 당시 시대상을 보여주는 역사적 공간으로서의 건축적 가치가 있다. ○○○○○는 1910년부터 ○○에 거주하였으며, 1919년 3.1독립선언과 제암리학살사건을 외부에 알려 일제의 만행을 전 세계에 전파하였다.","a":"서울 앨버트 테일러 가옥(딜쿠샤)","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2017081414312900.jpg"},{"q":"지혜로 중생의 어리석음을 없애준다는 ○○○○○로 연꽃대좌 위에 앉아 있는 작은 금동상이다. 머리에는 꽃무늬와 갖가지 보배로 화려하게 장식된 보관(寶冠)을 쓰고 있으며 정수리에는 상투 모양의 머리(육계)가 큼직하게 표현되었다. 보관 정면에 보병이 새겨져 있는데 이는 오른손에 들려있는 경전과 함께 이 보살상이 ○○○○○임을 알려준다. 신체에 비해 작은 얼굴에는 은은한 미소를 띠고 있으며 세련된 모습으로 탄탄한 인상을 준다. 신체 또한 매우 탄력적인데 가슴은 양감있게 표현됐으나, 허리와 배는 거의 구별되지 않게 하여 날씬한 모습이다.","a":"금동대세지보살좌상","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614411.jpg"},{"q":"○○○○○은 1614년 중건 이래 18세기와 19세기에 중수를 거쳐 현재에 이르고 있는 오래된 건축물로서, 정면 5칸, 측면 3칸의 2고주 5량가의 맞배집으로 우리나라 현존하는 향교 ○○○ 가운데 객사형(성균관, 나○○○○○)을 제외한 단일 건물로는 가장 규모가 큰 사례이다. 중수기 등의 문헌 기록이 풍부하게 남아 있어 건축 연혁을 자세히 알 수 있고, 기단과 초석에 사용된 석재의 가공, 익공의 초각, 지붕가구의 구성에서 17세기 건축의 면모를 볼 수 있으며, 같은 시설 내 보물 ○○○○ 대성전과 호응하는 규모와 품격을 가지고 있다.","a":"경주향교 명륜당","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2020122910400500.JPG"},{"q":"○○○○○은 ○○ 남산의 서쪽 기슭에 동서로 3개의 왕릉이 나란히 있어 붙여진 이름으로, 밑으로부터 신라 8대 아달라왕, 53대 신덕왕, 54대 경명왕 등 박씨 3왕의 무덤이라 전하고 있다. 무덤은 모두 원형으로 흙을 쌓아올린 형태를 하고 있다. 신덕왕릉이라 전해오는 가운데의 무덤은 1953년과 1963년에 도굴 당하여, 내부를 조사한 결과 굴식돌방무덤(횡혈식석실묘)임을 확인하였다.","a":"경주 배동 삼릉","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627827.jpg"},{"q":"한국의 대표적 서양화가로 우리나라 전통미를 현대화시키는데 주력한 수화 ○○○ 화백이 자랐던 곳으로 현재 안채와 화실 등으로 구성되어 있다. ○○○는 우리나라 모더니즘의 제1세대 화가로 한국의 고전적 소재를 추상적 조형언어로 양식화하여 한국미술의 새로운 전기를 마련한 인물로, 이 곳은 그의 유년기와 청년기 작품활동이 이루어졌던 공간이라는 역사적, 예술적 가치와 함께 20세기 초반 전통가옥이 근대로 들어서면서 사회의 변화에 따라 실용적으로 변용되어 가는 모습을 잘 보여주는 귀중한 자료이다.","a":"신안 김환기 고택","c":"국가민속문화유산","nc":"","r":"전남광주통합특별시","s":"신안군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634734.jpg"},{"q":"당나라 장수 ○○○의 공적을 기리기 위해 세운 비(碑)이다. 부소산에 세 조각으로 깨진 채 흩어져 있던 것을, 그 자리에 비각을 세워 복원해두었다가 해방 후 국립○○박물관으로 옮겨 놓았다. 비는 비몸돌의 앞면이 조금 깨어져 나갔고, 머릿돌도 부분적으로 깨어져 있으며, 비문은 몸돌 앞·뒷면에 새겨져 있으나 심하게 닳아 있어서 알아보기가 힘들다. 비몸돌과 머릿돌은 하나의 돌로 이루어져 있는데, 머리부분은 각이 없이 둥글다.","a":"부여 당 유인원 기공비","c":"보물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617434.jpg"},{"q":"○○○은 1동, 1층 규모로 건축면적 95.2㎡, 철로길이 좌·우 각각 150m이다. ○○○은 중앙선로의 역사로 1940년대에 건립된 것으로 판단되며, 1940년 4월 1일 보통역으로 영업을 개시하였다. 구조는 목조양식으로 벽체는 목조에 시멘트 몰탈로 마감되었다. ‘一’자형 평면으로 지붕은 대합실 상부에 박공지붕을 올려 슁글로 변형되어 있다. 벽체는 목조에 시멘트 몰탈로 마감되었다. 평면 구성은 오른쪽부터 대합실, 사무실, 숙직실 순서로 배치되었다. 소유자는 한국철도공사로 노선 복선화로 간이역은 폐역되었다","a":"양평 구 구둔역","c":"국가등록문화유산","nc":"","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668093.jpg"},{"q":"○○○○○의 전신인 보성전문학교가 개교 30주년을 기념하여 세운 도서관 건물이다. 1935년에 공사를 시작하여 1937년에 완성한 5층 건물로 설계는 본관을 설계한 박동진이 하였다. 현재 이 건물은 대학원동과 교수연구실로 이용하고 있다. 건축의 양식과 구조는 미국 듀크대학의 도서관을 참고 하였다고 한다. 모서리 부분의 서양 중세풍의 5층 탑 꼭대기 부분은 정교한 고딕식 창장식으로 하여 가장 돋보인다. 형태는 웅장하며 세부적으로는 섬세한 화강암으로 지은 고딕식 건축이다.","a":"서울 고려대학교 중앙도서관","c":"사적","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624944.jpg"},{"q":"○○ 창건의 가장 오래된 연원은 6세기 신라 진흥왕대에 창건했다는 설이 있으며, ○○가 화엄십찰의 하나로 「삼국유사」의 내용에서도 확인되어 적어도 9세기 이전에 창건되었음을 알 수 있다. ○○○○○은 임진왜란 직후에 중건되어 여러 차례 중수를 거치면서 현재까지 이어져 온 불전이다. 17세기 기록에 의하면 금당자리라고 불리는 곳이 따로 있었기 때문에 삼국시대에 절이 창건될 때의 법당의 위치는 아니지만, ○○○은 정유재란 이후 ○○에서 가장 먼저 재건된 건축물 중 하나로서 이후 그 형식을 대체로 유지해 온 것으로 추정된다.","a":"공주 갑사 대웅전","c":"보물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2021032509442800.JPG"},{"q":"직육면체의 돌에 천체의 형상을 새겨 놓은 것으로, 조선을 건국한 태조 이성계가 왕조의 권위를 드러내고자 권근, 유방택 등 11명의 천문학자들에게 명을 내려 만들도록 한 것이다. 고구려의 천문도를 표본으로 삼아 그 오차를 고쳐 완성하였는데, 두 부분으로 나누어 내용을 배치하고 있다. 윗부분에는 짧은 설명과 함께 별자리그림이 새겨져 있고, 아래부분에는 천문도의 이름, 작성 배경과 과정, 만든 사람의 이름 및 만든 때가 적혀 있다. 별자리 그림에는 중심에 북극을 두고 태양이 지나는 길인 황도(黃道)와 남북극 가운데로 적도(赤道)를 나타내었다.","a":"천상열차분야지도 각석","c":"국보","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611775.jpg"},{"q":"이 유적은 청동기시대의 대규모 집단 마을터로서 낮은 구릉의 비탈면에 위치한다. 마을 둘레에 못(환호)을 파 놓았는데, 이것은 당시 마을의 방위개념을 보여주는 자료로 우리나라에서 처음으로 확인된 것이다. ‘V’형태로 판 이 못은 현재 길이가 약 300m, 너비 50∼200㎝, 깊이 20∼150㎝ 정도이며, 이전에는 더 깊고 넓었을 것으로 보인다. 집자리와 움집터가 확인되었고 다양한 토기류와 석기류, 가락바퀴(방추차), 그물추 등 약 400여 점의 유물이 출토되었다.","a":"울주 검단리 유적","c":"사적","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625381.jpg"},{"q":"1939년 건립된 이 건물은 광주사범학교 강의실로 사용하기 위해 지은 것이다. 지금은 ○○○○○으로 사용되고 있으며, 대학 안에서 가장 오래된 건물이다. 붉은 벽돌의 2층 건물로 현관이 돌출되어 있고 전면 중앙 부분에 박공지붕이 솟아 있으며, 전체적으로 좌우 대칭의 균형미를 보여준다. 특히 중앙 현관 위쪽의 둥근 아치 모양의 채광창과 이를 받치고 있는 반원형 구는 이 건물의 중심 요소이다.","a":"광주교육대학교 본관","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667882.jpg"},{"q":"1944년 제작 이 기관차는 일본에서 제작되고 조선총독부 철도국 경성 공장에서 조립한 탄수차가 뒤에 달린 텐더식 ○○○○○로 부산에서 신의주를 비롯한 전국 철도의 주요 간선에서 운행되었다. 1978년 어린이날에 박정희 대통령의 지시로 기차를 볼 수 없는 섬 지역 어린이들을 위해 제주 삼무공원에 보내어져 전시되고 있다. 국내에 유일하게 남아 있는 석탄용 ○○○○○로 석탄과 물을 싣는 탄수차와 함께 원형 그대로 잘 남아 있다","a":"미카형 증기기관차 304호","c":"국가등록문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669623.jpg"},{"q":"거돈사터에 세워져 있는 탑비로, 고려시대의 스님인 원공국사의 행적을 기록하고 있다. 원공국사(930∼1018)의 법명은 지종(智宗)이고, 세속에서 쓰던 성은 이씨인데, 비문에는 그의 생애와 행적, 그의 덕을 기리는 송덕문이 담겨있다. 비는 거북받침돌 위로 비몸을 세우고 머릿돌을 얹은 모습으로, 비몸이 작고 머릿돌이 큰 것이 특징적이다. 거북의 머리는 괴수 모양의 험한 인상을 한 용의 머리모양이다. 등에 새긴 무늬는 정육각형에 가까우며, 육각형안에는 卍모양과 연꽃무늬를 돋을새김하였다.","a":"원주 거돈사지 원공국사탑비","c":"보물","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616262.jpg"},{"q":"○○ 화성은 조선 정조 18년(1794)에 정조의 아버지 사도세자의 능을 양주에서 ○○으로 옮기면서 짓기 시작하여 정조 20년(1796)에 완성한 성곽이다. 중국성의 모습을 본뜨기는 했지만 과학적인 방법으로 성을 쌓아 훨씬 발달한 모습을 하며 한국 성곽을 대표하는 뛰어난 유적이다. 이 문은 ○○ 화성의 남쪽문으로 이름은 서쪽에 있는 팔달산에서 따 왔다. 문루는 앞면 5칸·옆면 2칸의 2층 건물이며, 지붕은 앞면에서 볼 때 사다리꼴을 한 우진각지붕이다. 지붕 처마를 받치기 위해 기둥 윗부분에 짠 구조가 기둥 위뿐만 아니라 기둥 사이에도 있는 다포 양식으로 꾸몄다.","a":"수원 팔달문","c":"보물","nc":"","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615763.jpg"},{"q":"<○○○○○>은 조선 중기 문신인 ○○○을 그린 ○○화이다. 선생은 선조 18년(1585) 문과에 급제한 뒤 평안감사, 공조판서 등을 역임하였다. 이 ○○화는 가로 93㎝, 세로 185㎝의 크기이고 의자에 앉은 모습을 그렸다. 머리에는 낮은 사모를 쓰고 붉은색의 관복을 입었으며, 두 손은 소매 안으로 마주 잡아 보이지 않는다. 옷의 옆트임 안쪽으로 보이는 속옷과 양쪽 어깨의 기울기를 달리해 안정되어 보이는데, 이러한 자세는 조선 중기 ○○화에 나타나는 특징이다.","a":"이상길 초상","c":"보물","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618514.jpg"},{"q":"봉황산 중턱에 있는 ○○○는 신라 문무왕 16년(676)에 의상대사가 왕명을 받들어 화엄의 큰 가르침을 펴던 곳이다. ○○○○ 뒤에는 ‘부석(浮石)’이라고 새겨져 있는 바위가 있는데, 『송고승전』에 있는 설화를 보면, 의상대사가 당나라에서 유학을 마치고 귀국할 때 그를 흠모한 여인 선묘가 용으로 변해 이곳까지 따라와서 줄곧 의상대사를 보호하면서 절을 지을 수 있게 도왔다고 한다. 이곳에 숨어 있던 도적떼를 선묘가 바위로 변해 날려 물리친 후 ○○○○ 뒤에 내려 앉았다고 전한다. ○○○○은 ○○○의 중심건물로 극락정토를 상징하는 아미타여래불상을 모시고 있다.","a":"영주 부석사 무량수전","c":"국보","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612647.jpg"},{"q":"임진왜란(1592∼1598) 당시 ○○○○을 승리로 이끈 이순신의 공을 기념하기 위하여 세운 비이다. 일제강점기때 경복궁에 옮겨졌던 것을 1947년에 ○○의 해안지역(문내면 학동리 1186-7번지)으로 옮겨 세웠다가 2011년 3월 원 설립지인 현재의 위치로 이전하게 되었다. 이 석비는 직사각형의 비 받침 위에 비 몸돌을 꽂고, 그 위로 구름과 용을 장식한 머릿돌을 얹은 형태이다.","a":"해남 명량대첩비","c":"보물","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619198.jpg"},{"q":"이 책은 조선 중종 33년(1538)에 김정국(1485∼1541)이 방대한 『○○○○』의 내용 가운데 필요한 부분만을 간추려 4권으로 편집한 것이다. 원래『○○○○』은 중국 명나라의 호광 등 42명의 학자들이 송나라 때의 성리학설에 원나라때 성리학자의 학설까지 편집해서 만든 것으로, 세종 초에 수입된 이후 우리나라 학자들 사이에 반드시 읽어야 할 책이었다. 중종 33년(1538)에 호남관찰사에 부임한 김정국은 도사 김회백과 의논하여 나주목에 있던 목활자에 부족한 글자와 빠진 글자를 새겨 작업을 실시하였다.","a":"성리대전서절요(1993)","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614634.jpg"},{"q":"사화가 일어난 기묘년을 전후하여 친구, 동료들로부터 안처순(1492∼1534)에게 보내진 편지글을 묶어 만든 것으로, 거의가 기묘사화에 연루된 인물들의 글이다. 안처순은 고려시대 성리학을 처음으로 소개한 안향의 9대손으로, 예문관검열, 홍문관박사와 구례현감 등의 벼슬을 거쳤다. 편지글을 모아놓은 이 글씨첩은 안처순이 살아있을 당시 중종 12년(1517)에서 중종 26년(1531)에 이르는 15년간 그의 동료 12명으로부터 받은 편지 39통을 모아 하나의 첩으로 만든 것으로, 3면부터 72면에 걸쳐 수록되어 있다.","a":"기묘제현수첩","c":"보물","nc":"","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618639.jpg"},{"q":"조선 전기에 제작된 우리나라 지도이다. 크기는 가로 61㎝, 세로 132㎝이다. 3단 형식으로 되어 있는데, 맨 윗부분에는 ‘○○○○○’라는 제목이 적혀있고 중간 부분에는 지도가 그려져 있으며 맨 아래부분에는 지도 제작에 관련된 사람들의 관직·성명 등이 기록되어 있다. 지도에는 조선 팔도의 주현(州縣)과 수영(水營) 및 병영(兵營)이 표시되었는데 특히 각 군과 현마다 색을 다르게 하여 알아보기 쉽게 하였을 뿐만 아니라 산과 강의 경계도 자세하고 정확하게 묘사하고 있다. 지도의 형태는 지금의 전국지도 모습과 매우 유사하다.","a":"조선방역지도","c":"국보","nc":"","r":"경기도","s":"과천시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612049.jpg"},{"q":"○○○에 있는 보조선사 지선의 탑비로, 거북받침돌 위에 비몸을 세우고 머릿돌을 얹은 모습이다. 보조선사(804∼880)는 통일신라시대의 승려로, 어려서 출가하여 불경을 공부하였으며, 흥덕왕 2년(827)에 승려가 지켜야 할 계율을 받았다. 희강왕 2년(837) 중국으로 건너갔으나, 멀리서 구할 필요가 없음을 느끼고, 문성왕 2년(840)에 귀국하여 많은 승려들에게 선(禪)을 가르쳤다. 헌안왕 3년(859) 왕의 청으로 ○○○의 주지가 되었으며, 77세의 나이로 입적하였다. 왕은 그의 시호를 ‘보조선사’라 하고, 탑이름을 ‘창성’이라 내리었다.","a":"장흥 보림사 보조선사탑비","c":"보물","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618906.jpg"},{"q":"1963년 당시 이리(現 ○○) 지역을 대표하는 농업전문 교육기관인 이리농림학교의 제2○○으로 건립된 건물로 학교의 역사와 흔적을 온전히 간직하고 있다. 전체적으로 붉은 벽돌의 조적조 건물이면서 주출입구 상부의 계단실과 정면에 설치한 현관부(포치)를 화강석으로 쌓아 입면을 강조한 건축적 기법 등이 특징이다. 건물의 보존상태도 대부분 원형을 유지하고 있어 국가등록문화유산으로서의 가치를 지니는 것으로 평가된다.","a":"익산 구 이리농림고등학교 본관","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2019070514581900.jpg"},{"q":"서봉사의 창건에 대한 기록은 없고 절터의 크기로 보아 아주 큰 규모의 절로 추정된다. 전하는 말에 의하면, 임진왜란 때 절에서 떠내려오는 쌀뜨물이 10리나 흘러내려와 왜적이 물을 따라 올라가서 절을 불태웠다고 한다. 이곳은 탑비의 비각을 세우는 공사를 하던 도중에 기록이 남아있는 기와조각이 발견되어 서봉사의 옛터임이 밝혀졌다. 명종 15년(1185)에 세워진 이 탑비는 현오국사(玄悟國師)의 행적을 후대에 알리고자 만들어졌다. 보통 부도와 함께 건립되는데 절터에 부도의 흔적은 없고 이 비석만 남아 있다.","a":"용인 서봉사지 현오국사탑비","c":"보물","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615616.jpg"},{"q":"면을 여러 겹 넣어 만든 갑옷으로 탄성이 큰 섬유조직을 이용해 총탄을 방어하는 원리의 면제(綿製)갑옷이다. 1866년 병인양요 이후 흥선대원군은 서양의 총탄을 막아낼 갑옷 제조를 명하고 무기제조자 김기두와 강윤은 조정의 명에 따라 거듭된 실험으로 면 12겹에는 총탄이 뚫리지 않음을 확인하고 면 13겹으로 면갑을 만들었다는 기록이 있다. 1871년 신미양요에 첫 실전 투입하여 총탄 방어에는 효과가 있었으나 더위나 화기, 습기에는 취약하였다. 이 ○○○○은 무명을 30장 겹쳐 만든 것으로 안쪽에 소유자의 성명으로 추정되는 먹글씨‘孔君玉’이 쓰여 있다.","a":"면제갑옷","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667335.jpg"},{"q":"이 시설물은 일본의 고레가와제철(是川製鐵)이 강원특별자치도 삼척에 공장을 건립한 뒤 설치한 소형 용광로 8개 가운데 하나이다. 고레가와제철은 광복 후 ○○○○○로 이름이 바뀌었다. 1993년 포스코가 인수해 원형을 복원한 뒤 2003년부터 포스코역사관 야외 전시장에 전시하고 있다. 남한에 건립한 용광로 중 가장 오래되었으며, 지금까지 유일하게 남아 있는 용광로이다. ○○제철이 건립되기 전까지 하루 20t의 선철을 생산하며 국내에서는 유일한 용광로 역할을 담당했다. 우리나라 제철 기술과 제철공업 발달사에서 중요한 자료가 되는 산업시설물로 역사적·산업적 가치가 높다.","a":"포항 구 삼화제철소 고로","c":"국가등록문화유산","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669076.jpg"},{"q":"불상을 모시기 위해 나무나 돌, 쇠 등을 깎아 일반적인 건축물보다 작은 규모로 만든 것을 불감(佛龕)이라 한다. 불감은 그 안에 모신 불상의 양식뿐만 아니라, 당시의 건축 양식을 함께 살필 수 있는 중요한 자료가 된다. 이 ○○○○○은 보조국사 지눌이 중국에서 돌아오는 길에 가져온 것으로 알려져 있으나 정확한 기록은 남아 있지 않다. 불감은 모두 3부분으로 이루어져 있는데, 가운데의 방을 중심으로 양쪽에 작은 방이 문짝처럼 달려 있다. 문을 닫으면 윗부분이 둥근 팔각기둥 모양이 되는데, 전체 높이는 13㎝이고, 문을 열었을 때 너비 17㎝가 되는 작은 크기이다.","a":"순천 송광사 목조삼존불감","c":"국보","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612444.jpg"},{"q":"3세기에서 7세기 중반기의 가야와 신라의 무덤들로 총 205기에 달하며, 낙동강 동쪽에 인접한 해발 약 70m 내외의 광범위한 구릉지대에 분포한다. 무덤을 덮은 봉분은 원형과 표주박형으로 되어있고, 내부는 널무덤(토광묘), 독무덤(옹관묘), 돌덧널무덤(석관묘)으로 되어있다. 유물은 굽다리접시(고배)를 비롯한 토기류와 치레거리(장신구), 고리자루 큰칼(환두대도) 등의 철기류가 발견되었다. 이 무덤들은 당시 이지역에 존재한 세력의 크기와 문화를 알 수 있는 중요한 자료이다.","a":"구미 낙산리 고분군","c":"사적","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627910.jpg"},{"q":"○○군 하빈면 묘동은 사육신 중 하나인 충정공 박팽년(1417∼1456) 후손이 모여 사는 순천 박씨 집성촌이다. ○○○은 박씨 집성촌과는 낮은 산을 경계로 하고 있다. ○○○은 박팽년의 11대 손인 성수聖洙가 1769년에 이곳에 초가를 짓고 자기의 호를 따라 ○○○이라 한 것에서 시작한다. 그 뒤 그의 아들 광석光錫이 1783년 이웃 묘골에서 현재 위치로 분가한 다음 1826년 초가를 헐고 안채와 사랑채를 지었다.","a":"달성 삼가헌 고택","c":"국가민속문화유산","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633493.jpg"},{"q":"용화수 가지를 들고 있는 ○○○을 그린 괘불이다. 괘불이란 야외에서 큰 법회나 의식을 진행할 때 법당 앞뜰에 걸어놓고 예배를 드리던 대형 불교그림을 말한다. ○○○에 있는 이 그림은 전체 897.6×585.7cm, 화면 805.5×556cm로 ○○○을 화면 중심에 두고 6대 여래, 6대 보살 등 여러 인물들로 화면을 가득 채우고 있다. 인간세계에 내려와 중생을 구제한다는 부처인 ○○○은 사각형의 얼굴에 머리에 4구의 작은 불상이 있는 화려한 보관을 쓰고, 풍만하고 살찐 모습으로 유난히 긴 팔과 커다란 상체를 가지고 있다.","a":"장곡사 미륵불 괘불탱","c":"국보","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612320.jpg"},{"q":"과대는 직물로 된 띠의 표면에 사각형의 금속판을 붙여 만든 ○○○를 말하며, 요패는 ○○○에 늘어뜨린 장식품을 말한다. 옛날 사람들은 ○○○에 옥(玉)같은 장식품과 작은칼, 약상자, 숫돌, 부싯돌, 족집게 등 일상도구를 매달았는데, 이를 관복에 적용한 것으로 보인다. 백제나 신라에서는 관직이나 신분에 따라 재료, 색, 수를 달리하여 그 등급을 상징하였다. 경북 경주시 노서동 소재 ○○○에서 출토된 신라시대 ○○ 과대 및 요패는 과대길이 109㎝, 요패길이 54.4㎝이다.","a":"금관총 금제 허리띠","c":"국보","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612814.jpg"},{"q":"해방 이후 귀환 동포와 한국전쟁 중 ○○으로 밀려드는 피란민들의 거주 공간 확보를 위해 ‘소(牛) 막사(幕舍)’를 주거시설로 변용(變容)한 것으로 당시 피난민의 삶을 잘 보여주고 있다. 또한, 산업화 시기 인근 지역에 조성된 공장, 항만 등으로 인해 이곳으로 유입된 노동자들의 생활공간으로서 오늘날까지도 그 기능을 유지해 오고 있다는 점에서 근대문화유산으로서의 의미를 부여할 수 있다. 일제강점기 일본인들은 오늘날 ○○시 ○○○ 일대의 바다를 매립하여 산업시설과 함께 우리나라의 소를 일본으로 반출하기 위한 위생검역소 및 소막사 등의 시설을 조성.","a":"부산 우암동 소막마을 주택","c":"국가등록문화유산","nc":"","r":"부산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2018062816394800.JPG"},{"q":"­미국 GM사가 1918년에 제작한 캐딜락 리무진으로 순종황제(純宗 1874~1926/재위기간 1907~1910)가 주로 탔던 것으로 알려진 자동차이다","a":"순종어차","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667109.jpg"},{"q":"고려시대 만들어진 ○○○○○로 높이 24.4㎝, 아가리 지름 11.5㎝, 밑지름 11.5㎝의 크기이다. 구형에 가까운 모양의 ○○○○○로 아래 위로 커다란 연꽃을 3송이씩 배치하고, 그 사이에 화려한 덩굴무늬를 가득 채워 넣었다. 아가리 부분은 가장자리가 밖으로 살짝 말려 있으며, 목이 짧고 볼록한 몸통에 굽이 없는 평평한 바닥면으로 되어있다. 문양의 윤곽 부분은 반양각(半陽刻)으로 시원스럽게 처리하고, 세부는 가는 음각선으로 정교하게 표현하였다.","a":"청자 음각연화당초문 항아리","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614384.jpg"},{"q":"1908년 무렵 건립된 이 건물은 개항 이후 ○○항을 통해 들어온 중국인이 지은 중국 요릿집이다. 중국 산동 지방의 장인이 참여하여 지은 중정형(中庭型)의 중국식 건물로, 현재 정면은 다양한 색깔의 타일로 마감하였고, 내부는 다양한 문양과 붉은 색을 사용하여 화려하게 장식하였다. 처음에는 무역상들에게 숙식을 제공하던 곳으로 이용되었다. 그러다가 중화요리가 대중적인 인기를 얻으면서 음식점의 공간이 확대되어, 대형 연회장을 갖춘 유명한 중국 요릿집으로 1980년대까지 그 명성을 날렸다.","a":"인천 선린동 공화춘","c":"국가등록문화유산","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667811.jpg"},{"q":"○○○은 ○○○에 속한 암자로 신라말에 지은 것으로 전한다. 조선 명종 1년(1546) 인종의 태실(胎室)을 팔공산에 모시게 되자 ○○○을 수호사찰로 정하고 크게 고쳤다고 한다. 극락세계를 상징하는 아미타삼존불을 모시고 있는 ○○○은 인조 21년(1643)에 지은 것으로 지금 있는 건물은 그 뒤로 여러 차례 수리한 것이다. 규모는 앞면 3칸·옆면 3칸이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 지붕 처마를 받치기 위해 기둥 위부분에 장식하여 짜은 구조가 기둥 위뿐만 아니라 기둥 사이에도 있다.","a":"영천 은해사 백흥암 극락전","c":"보물","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621521.jpg"},{"q":"1923년 10월에 준공한 2층 붉은 벽돌집으로, 1934년에 불에 탄 옛 본관의 왼쪽에 지어 서관과 쌍을 이루고 있다. 건물구조는 T자형으로 서관과 동일하며 1920년대의 순수 민간인이 세운 사립학교 건물로서 현재까지 전해오는 건물이다.","a":"서울 중앙고등학교 동관","c":"사적","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624928.jpg"},{"q":"1948년에 명문(銘文)이 있는 신라 범종이 발견되어 주목되었던 선림원터에는 석탑을 비롯하여 석등·홍각선사탑비·석조부도 등이 전해지고 있으며, 이들 석조유물들은 대부분 쓰러져 있었으나 모두 복원되었다. 이 탑은 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 전형적인 신라석탑으로, 법당터 남쪽의 원래 위치에 복원되었다. 여러 장의 돌로 탑의 토대를 만들고, 아래층 기단을 올려 각 면 모서리와 중앙에 기둥을 새겼다. 위층 기단 역시 각 면 모서리와 중앙에 기둥을 새겼는데, 한 면을 둘로 나눈 뒤 8부중상을 도드라지게 새겼다.","a":"양양 선림원지 삼층석탑","c":"보물","nc":"","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616550.jpg"},{"q":"○○○○○에서 볼 때 북쪽 산꼭대기 가까운 곳에 위치하고 있는 탑이다.『○○○사적』에 의하면, ○○○는 600년대 창건되었는데, 백제 법왕이 그의 즉위년(599)에 칙령으로 살생을 금하고 그 이듬해에 이 절을 창건하여 38인의 승려를 득도시킨 것으로 기록되어 있다. 탑은 2층의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습으로, 탑신의 몸돌에는 네 면마다 모서리에 기둥모양을 새겼다. 각 몸돌을 덮고 있는 3개의 지붕돌은 넓적하며, 낙수면의 경사를 급하게 처리하였고, 처마의 양끝에서의 들림이 부드러운 곡선을 그리고 있어 고려시대의 특징이 잘 담겨져 있다.","a":"김제 금산사 심원암 삼층석탑","c":"보물","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618146.jpg"},{"q":"전북 백산에 있는 산성터인데, 산성은 적의 공격을 막기 위하여 산에 쌓은 성을 말한다. ○○○이 만들어진 시기는 대략 660∼663년 사이로 생각된다. ○○○은 백산 정상을 둘러 쌓아 만든 성으로 바깥성을 포함한 4개의 단이 있으며, 토단 바깥으로는 말뚝을 박아 울타리를 둘렀을 것으로 추정한다. 일부 훼손된 곳이 있으나 건물터, 옛 우물터, 삼국시대 토기조각들과 높이 3∼4m 정도의 토단이 잘 남아있다. 이 산성은 동학농민운동 때 동학군이 근거지로 사용하기도 하였고, 성곽연구에 좋은 자료가 되는 유적이다.","a":"부안 백산성","c":"사적","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626978.jpg"},{"q":"○○○○ 서쪽 기슭의 바위면에 삼존불(三尊佛)이 조각되어 있는데, 표면이 거칠고 균열이 심한 상태이다. 가운데에는 머리광배와 몸광배를 갖춘 본존불이 있고, 양 옆으로 협시불이 있다. 본존불의 둥글고 양감있는 얼굴은 광대뼈가 튀어 나오고 살짝 미소를 띤 매우 독특한 모습이다. 본존은 머리에 두건을 쓰고 있고 양 어깨를 감싸고 입은 옷은 고려 불화에서 보이는 지장 보살의 모습과 비슷하여 흥미롭다. 양 협시는 본존과 거리를 두고 있는데 몸에 갑옷을 입고 있다.","a":"경주 낭산 마애보살삼존좌상","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621363.jpg"},{"q":"적의란 원래 중국에서 황후가 관복으로 착용하던 예복으로 우리나라에서 법복으로 왕비가 적의를 입기 시작한 것은 고려말 부터이다. 폐슬은 조복이나 제복을 입을때 앞부분을 수직으로 내려 무릎을 가린 장식물이다. 이 유물은 조선시대 ○○○과 적의를 만들기 위하여 여러장의 창호지를 연접하여 실물의 크기와 형태, 문양까지 똑같이 그린 것이다. ○○○은 엷은 청색바탕에 꿩이 두 마리씩 서로 마주보게 그려져 있고, 마주보는 꿩사이에는 네가지색의 꽃무늬를 그려 넣었으며, 두꺼운 붉은색 창호지를 이용하여 옷자락의 가장자리를 만들고 용과 구름을 그려 넣었다.","a":"적의본 및 폐슬본","c":"국가민속문화유산","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633247.jpg"},{"q":"<○○○○○>은 정조가 혜경궁 홍씨의 회갑을 맞이하여, 정조 19년(1795) 윤 2월 9일부터 8일간에 걸쳐 모친인 혜경궁 홍씨를 모시고 사도세자의 묘소가 있는 화성의 현륭원(顯隆園)을 행행했을 때 거행한 주요 행사를 그린 8첩 ○○이다. 각 폭의 내용은 ‘화성성묘전배도(華城聖廟展拜圖)’, ‘낙남헌방방도(洛南軒放榜圖)’, ‘봉수당진찬도(奉壽堂進饌圖)’, ‘낙남헌양로도(洛南軒養老圖)’, ‘서장대야조도(西將臺夜操圖)’, ‘득중정어사도(得中亭御射圖)’, ‘환어행렬도(還御行列圖)’, ‘한강주교환어도(漢江舟橋還御圖)’ 등으로 구성되어 있다.","a":"화성행행도 병풍","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614824.jpg"},{"q":"이 책은 『춘추좌씨전』을 중국 송나라 임요수가 읽기 어려운 글자에 주를 달고 글 전체에 걸쳐 해설을 한 것으로 원래의 판본을 바탕으로 다시 새긴 것이다. 세종 13년(1431)에 전라도 관찰사 서선(徐選,1367∼1433)이 간행하였다. 이것의 간행작업은 세종 12년(1430)에 전라도관찰사 신개(1373∼1446)가 집안에서 소장하고 있던 본을 간행하여 널리 펴내고자 도사 김치명과 의논하여 그 해에 금산에서 판을 새길 것을 알리고, 다른 군에서는 구재모공의 협조를 지시하여 실시되었다.","a":"음주전문춘추괄례시말좌전구독직해 권62~70","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614642.jpg"},{"q":"○○○○○는 신라말 고려초의 고승인 낭공대사(朗空大師) 행적(行寂)〔832(흥덕왕7)～ 916(신덕왕5)〕의 탑비이다. 비문의 찬자는 당대 문장으로 평가받았던 최인연과 대사의 문하법손(門下法孫)인 석순백(釋純白)이다. 또한 문하승인 승려 단목(端目)이 명필 김생의 행서 글씨를 집자하여 승려 숭태, 수규, 청직, 혜초 등이 새겨 954년(광종 5)에 세운 비이다.","a":"봉화 태자사 낭공대사탑비","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2460243.jpg"},{"q":"○○○이란 상상의 산인 수미산 형태의 단을 만들고 그 위에 불상을 모시는 불단를 말한다. ○○○○○은 극락전에 있는 높이 125㎝, 너비 413㎝의 조선 후기에 만든 불단이다. 앞쪽 면은 5단으로 되어 있으며, 각 단도 5등분 되어 각각 직사각형 모양이다. 가장 위에 있는 단은 안상문을 도드라지게 조각하였다. 제2단은 봉황·공작·학·꿩 등을, 제3단은 용·어린아이·물고기·개구리 등을 매우 섬세하게 조각하였다. 제4단은 꽃잎 속에 있는 코끼리·사자·사슴 등을 조각하였고, 가장 아래단의 양쪽 끝에는 도깨비 얼굴을, 가운데 부분에는 용을 조각하였다.","a":"영천 은해사 백흥암 수미단","c":"보물","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621056.jpg"},{"q":"경천사는 경기도 개풍군 광덕면 부소산에 있던 절로 고려시대 전기에 창건된 것으로 추정된다. 절터에 세워져 있었던 이 탑은 일제강점기에 일본으로 무단으로 반출되었던 것을 되돌려 받아 1960년에 경복궁으로 옮겨 세워 놓았다가 현재는 국립중앙박물관에서 전시중이다. 석탑의 3단으로 된 기단(基壇)은 위에서 보면 아(亞)자 모양이고, 그 위로 올려진 10층의 높은 탑신(塔身) 역시 3층까지는 기단과 같은 아(亞)자 모양이었다가, 4층에 이르러 정사각형의 평면을 이루고 있다.","a":"개성 경천사지 십층석탑","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611495.jpg"},{"q":"일제시대 고적으로 관리하여 오던 것을 1963년 사적으로 일괄 지정하였으며, 2011년 진지왕릉과 분리하여 재지정하였다. ○○○은 신무왕의 아들로 신라의 쇠퇴기에 재위하였으나 청해진대사 장보고의 난을 평정하고 혈구진을 설치하여 지방 세력에 대한 통제를 강화하는 한편 임해전을 크게 보수하였다. 봉분에는 호석이나 상석 등이 존재하지 않으며, 남측에 1기의 표석이 설치되어 있고, 그 아래로 문화유산안내판이 설치되어 있다. 봉분 주변은 소나무로 둘러싸여 있다.","a":"경주 문성왕릉","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628114.jpg"},{"q":"이 돌다리는 ○○○의 정문인 홍화문에 들어서면, 북에서 남으로 흐르는 옥류천을 가로 질러 있는 것으로 산천의 정기를 옮겨다 주는 명당수가 흐르는 곳이다. 전체적인 형태는 반원아치형태의 홍예(紅霓) 2개를 이어붙여 안정감이 느껴지며, 궁궐의 다리에 맞는 격식을 갖추고 있다. 홍예가 이어지는 공간에는 억센 표정을 하고 있는 도깨비얼굴을 새겨놓아 주의를 끄는데, 공간에 맞추려는 듯 이마가 넓고 턱이 좁아 삼각형을 이루고 있다. 다리의 양옆에 두어 이 곳을 오가는 이들을 보호하려는 의도로 보여진다.","a":"창경궁 옥천교","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613354.jpg"},{"q":"김성일(1538∼1593)의 재사로 건축 연대는 알 수 없으나, 재사에서 조금 떨어진 곳에 세워진 김성일의 비석에 적힌 연도가 인조 12년(1634)으로 기록되어 있다. 이것으로 보아 이보다 늦은 1700년대의 건축으로 추정된다. 김성일의 묘가 있는 산아래에 자리잡은 'ㅁ'자형 집으로 앞면은 2층으로 되어 있다. 앞면 아래에는 광, 대문간, 외양간이 있으며, 위에는 누마루를 만들었다. 누는 제사 후 음식이나 술을 마시는 자리로 사용하였고, 몸채는 제사에 쓰이는 음식이나 재료를 장만하는데 쓰였다.","a":"안동 의성김씨 서지재사","c":"국가민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635446.jpg"},{"q":"조선 중기 유학자이자 경세가인 ○○는 퇴계 이황의 학문을 더욱 발전시켜 중국의 성리학과 차별되는 조선 성리학의 토대를 닦은 인물로서 우리나라 정신사에 지대한 업적을 남긴 인물이다. 율곡 ○○를 배향한 자운서원, 율곡 ○○와 신사임당의 묘소를 포함한 가족묘역이 한 공간에 모여 있는 ‘○○○○○’은 율곡 ○○ 관련 유적을 대표하는 곳으로, 한 인물에서 근원한 문화유산이 모여 있는 장소성의 가치가 큰 곳이다.","a":"파주 이이 유적","c":"사적","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626063.jpg"},{"q":"ㅇ1921년에 민형기 재무관의 자택으로 지어졌으며 ‘ㄱ’자형 안채와 ‘ㄱ’자형 사랑채 및 행랑채로 구성되어 있다. 2002년 ○○시 도시개발공사에서 북촌 가꾸기의 일환으로 철거하여 복원한 도시형 주택으로 ○○○○의 건축술이 잘 담겨 있다.","a":"서울 계동 근대 한옥","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667008.jpg"},{"q":"○○○은 백제의 수도가 ○○였을 때 ○○를 지키던 백제의 산성이다. 금강변 야산의 계곡을 둘러싼 산성으로, 원래는 흙으로 쌓은 토성이었으나 조선시대에 석성으로 고쳤다. 쌓은 연대는 정확하지 않으며, 백제 때에는 웅진성으로, 고려시대에는 ○○산성·○○○으로, 조선 인조 이후에는 쌍수산성으로 불렀다. 동서로 약800m, 남북으로 400m 정도의 장방형을 이루고 있다. 4방에 문터가 확인되는데, 남문인 진남루와 북문인 공북루가 남아있고 동문과 서문은 터만 남아있었는데, 1993년에 동문터에는 영동루 서문터에는 금서루를 복원하였다.","a":"공주 공산성","c":"사적","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626430.jpg"},{"q":"『○○○사적』에 의하면, ○○○는 600년대 창건되어 신라 혜공왕 2년(776)에 진표율사가 다시 고쳐 세우면서 큰 사찰로서의 모습을 갖추게 되었다. 또한 고려 전기인 935년에 후백제의 신검이 아버지인 견훤을 유폐시켰던 장소로도 유명하다. 이 ○○는 ○○○ 대적광전에서 서남쪽에 위치한 대장각으로 가는 길의 중간에 있는데, 그 이름을 ○○라고는 하였으나 실제로 무엇으로 사용한 것인지 그 용도를 알 수 없는 보기 드문 유물이다. 꼭대기에 놓인 꽃봉오리모양의 조각만 없으면 불상을 얹는 사각형의 대좌(臺座)처럼 보인다.","a":"김제 금산사 노주","c":"보물","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618105.jpg"},{"q":"­1908년 ○○○○○ 개교와 함께 교정에 게양되었던 ○○○이다. 옷감재료나 바느질법 등에서 시대성을 볼 수 있고 100년 동안 학교의 정신적 지주로서의 역할을 한 상징성이 크다","a":"동덕여자의숙 태극기","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667180.jpg"},{"q":"고려 원종(재위 1259∼1274)의 왕비 순경태후의 무덤이다. 순경태후는 장익공 김약선의 딸로서 고종 22년(1235) 원종이 태자가 되자 태자비인 경목현비가 되었으며, 다음해에 충렬왕을 낳았다. 지금의 자리에는 고종 31년(1244)경 사망한 뒤 모신 것으로 짐작한다. 고려 원종 3년(1262) 정순왕후로 추대되고 충렬왕이 즉위(1274)하여 순경태후로 높여졌다. 무덤 주변의 석물은 부서져 없어졌고, 봉분도 무너진 것을 1974년에 지금의 모습으로 손질하여 고쳤다. <br/><b>※(○○ → ○○○○)으로 명칭변경 되었습니다. (2011.07.28 고시)</b>","a":"강화 가릉","c":"사적","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625304.jpg"},{"q":"삼국시대 최초 축조된 이후 구간별로 개보수되어 통일신라 시대를 거쳐 고려, 조선시대까지 사용되었던 석산성으로 삼국시대의 축성기술 뿐만 아니라 후대에 개보수하면서 사용한 흔적을 잘 보여주고 있다는 점에서 시기별 성곽 시설물을 비교해 볼 수 있기에 역사적·학술적 가치가 뛰어남","a":"인천 계양산성","c":"사적","nc":"","r":"인천광역시","s":"계양구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2020051813094700.jpg"},{"q":"「○○○○○」는 선조(宣祖)의 계비(繼妃)인 ○○○○가 큰 글자로 쓴 칠언절구의 시이다. 종이바탕에 4행으로(각행 7자) 썼으며 근대에 족자로 장황되었다. ○○ 아래에는 서예가 배길기(裵吉基)의 1966년 발문이 있다. 바탕은 보존이 양호한 편이며 다만 줄[行] 사이가 좀 더 밝다. 한편 ○○○○○ 28자의 점획 안에는 제월당(濟月堂)이란 스님의 발원문 29자가 작은 글자로 진하게 쓰여 있다.","a":"인목왕후 어필 칠언시","c":"보물","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616163.jpg"},{"q":"18세기 말에 제작된 한양 지도이다. 도봉산과 북한산을 배경으로 하면서 백악산(白岳山)·인왕산(仁王山)·목멱산(木覓山, 남산)·타락산(駝駱山, 낙산)의 내사산(內四山)을 중심으로 한양의 빼어난 자연 환경을 산수화처럼 그렸다. 정확한 제작 시기는 미상이지만, 1785년에 설치되었다가 1802년에 폐지된 장용영(壯勇營)이 종묘의 오른쪽에 그려져 있는 것을 통해 이 지도가 18세기 말에 제작되었음을 추정할 수 있다. 지도는 남쪽을 바라보며 정사(政事)를 살피는 국왕의 시각에 맞추어 남쪽이 지도 상단으로, 북쪽이 지도 하단으로 배치되어 있다.","a":"도성도","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614915.jpg"},{"q":"○○○는 고려 광종 5년(954)에 광종이 어머니인 신명순성왕후의 명복을 빌기 위하여 세운 절이다. 절터 부근에서 발견된 '○○○'라고 씌여진 기와를 토대로 이곳이 '○○○'였음을 알 수 있다. 충청대학교 박물관의 3차(2000∼2002)에 걸친 발굴조사 결과, 금당 외 탑지, 회랑지 등의 유구가 확인되었다. 초창 이후 3차례에 걸쳐 중수된 것으로 추정된다.","a":"충주 숭선사지","c":"사적","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626365.jpg"},{"q":"○○○의 정상부근을 에워싼 말안장 모양의 내성과 그 서북쪽 경사면을 둘러싼 외성의 2중구조로 되어있는 산성이다. 성을 쌓은 시기는 백제 말에서 통일신라 전기로 보고 있다. 비교적 큰 규모의 산성으로, 내성은 흙으로 쌓았고 외성은 돌과 흙을 함께 사용하여 쌓았다. 이러한 2중구조의 산성은 특히 백제 말에 나타난 새로운 산성의 형식으로 알려져있다. 또한 산성의 남서쪽 낮은 봉우리에는 2개의 소규모 산성이 있는데, 이는 ○○○○에 딸린 부속성으로 방어를 위한 보루로 볼 수 있다. 이 구조 역시 백제식 산성의 특징이라 할 수 있다.","a":"서천 건지산성","c":"사적","nc":"","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626491.jpg"},{"q":"○○○ 입구 오른쪽의 암벽을 다듬어서 조각한 불상이다. 지상에서 높이 위치한 이 불상은 구름을 타고 하늘에서 내려오는 듯한 개성있는 모습이다. 얼굴은 부피감을 느낄 수 있는 비교적 풍만한 모습인데, 세부표현은 평면적이며, 짧은 목에는 3개의 주름이 있고, 어깨는 반듯하다. 손모양은 오른손을 무릎에 대어 손끝이 아래를 가리키고, 왼손은 손바닥을 위로 향하게 하여 배꼽 앞에 놓았다. 옷은 양 어깨를 감싸고 있는데, 규칙적으로 얇게 빚은 평행의 옷주름선이 나타나있다. 몸에서 나오는 빛을 형상화한 광배(光背)는 끝이 날카로운 배(舟) 모양이다.","a":"대구 동화사 마애여래좌상","c":"보물","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615136.jpg"},{"q":"이 건물은 일제강점기에 금융기관으로 건축한 후 부안농협을 거쳐 현재 부안군청 해양수산과 사무실로 사용하는 근대 사무소 건축물이다. 평면은 ‘ㄷ’자 모양으로 정면 중앙 현관을 통해 사무 공간으로 출입하고, 좌우측의 복도를 통해 증축부의 각 실과 연결되도록 공간을 구성하였다. 일본인들의 경제 수탈 정책을 지원하려고 설립한 소규모 ○○○○ 건물로, 곡창지대인 부안 지역에서 생산된 쌀을 수탈해 가는 데 선봉 노릇을 한 시설이다.","a":"구 부안금융조합","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668722.jpg"},{"q":"『○○○○○』은 18세기 전반을 대표하는 명필 백하 ○○이 58세 되는 1737년(영조 13) 3월에 태화산에서 쓴 것이다. 다양한 크기의 해행초로 쓰여 있는데, 소해는 왕희지풍, 중자 해서는 동기창풍, 행서와 초서는 미불 서풍을 바탕으로 동기창 서풍이 가미되어 있다. 또 ○○의 글씨 앞뒤에는 당대와 후대의 명사 네 사람의 제발(題跋)이 딸려 있으며, ○○ 서예의 장처와 한계를 지적하고 있어 조선후기 서예비평의 본격적인 예로 주목된다. 보존상태도 매우 양호하다. ○○의 노년시절 서풍을 가장 대표하는 ○○이다.","a":"윤순 필적 고시서축","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614987.jpg"},{"q":"1910년에 지어진 한옥성당으로 1928년 현 위치로 이축하면서 상량 목부재를 포함하여 당시 사용하였던 기초 부재를 대부분 재활용하였고, 1949년 증축하면서 기록한 상량 묵서도 남아있어 변천과정 기록유지가 잘 되어 있으며, 건물 뼈대를 구성하는 목조가구의 경우 최초 건립 부분과 증축 부분이 잘 남아 있는 등 역사성을 잘 간직하고있다.","a":"고양 행주성당","c":"국가등록문화유산","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668184.jpg"},{"q":"○○○은 ○○○의 정전이다 ‘인정(仁政)’은 ‘어진정치’라는 뜻이며, ○○○은 ○○○의 법전(法殿)이 된다. 법전은 왕의 즉위식을 비롯하여 결혼식, 세자책봉식 그리고 문무백관의 하례식 등 공식적인 국가 행사 때의 중요한 건물이다. 광해군 때 중건된 이후 순조 3년(1803)에 일어난 화재로 인한 재건, 그리고 철종 8년(1857년)에 보수공사이후 지금에 이르고 있다. ○○○의 넓은 마당은 조회가 있었던 뜰이란 뜻으로 조정(朝廷)이라고 부른다. 삼도 좌우에 늘어선 품계석은 문무백관의 위치를 나타내는 표시로 문무관으로 각각 18품계를 새겼다.","a":"창덕궁 인정전","c":"국보","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611746.jpg"},{"q":"서원이란 훌륭한 사람들에게 제사지내고 유학을 공부하던 조선시대 지방의 사립교육기관을 말한다. ○○○○은 문경공 김굉필 선생의 학문과 덕행을 기리기 위해 조선 선조 원년(1568) 처음 세워 쌍계서원이라 불렀다. 그러나 임진왜란 때 불에 타 없어져 선조 37년(1604) 지금 있는 자리에 ○○을 다시 지었고 선조 40년(1607)에 임금님이 직접 ○○○○이라고 쓴 현판을 하사받아 사액서원이 되었다. 고종 8년(1871)의 서원철폐령의 대상에서 제외된 47개 서원가운데 하나이다.","a":"달성 도동서원 중정당·사당·담장","c":"보물","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615196.jpg"},{"q":"회암사는 고려 충숙왕 때인 1328년에 승려 지공(指空)이 창건한 사찰로, 그 제자인 나옹(懶翁)이 불사를 일으켜 큰 규모의 사찰이 되었다. 조선 태조 이성계가 각별히 관심을 가졌으며, 왕위를 물린 후에도 이 곳에서 머무르며 수도생활을 한 것으로 유명하다. 절터의 동쪽 능선 위에 지공과 나옹 그리고 무학의 사리탑이 남과 북으로 나란히 서있고, 그 남쪽 끝에 이 ○○이 자리하고 있다. 바닥돌과 아래받침돌은 하나로 붙여서 만들었으며, 그 위의 중간받침돌은 ○○○를 두어 신라이래의 형식을 따르고 있다.","a":"양주 회암사지 무학대사탑 앞 쌍사자 석등","c":"보물","nc":"","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615751.jpg"},{"q":"○○○○○은 경북대학교 박물관에 있는 석조여래좌상으로 통일신라 후기에 유행하던 ○○○○○의 전형적인 양식을 보여주는 작품이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며 얼굴은 몸에 비해 크고 둥글다. 당시 ○○○○○의 얼굴이 단정하면서도 엄숙한 인상인데 비해서, 이 불상의 얼굴은 풍만하고 눈과 입가에 미소를 짓고 있는 것이 특징이다. 옷은 양 어깨를 두껍게 감싸고 있으며 옷주름은 형식적으로 처리된 모습이다. 어깨가 좁아서 체구가 현저히 왜소해진 모습이며, 양 발을 무릎에 올리고 발바닥이 하늘을 향한 자세로 앉아 있다.","a":"석조비로자나불좌상","c":"보물","nc":"","r":"대구광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615195.jpg"},{"q":"○○○는 신라 선덕여왕 9년(640) 자장율사가 세웠다는 설과 신라의 승려 무선이 당나라에서 돌아와 세웠다는 두 가지 설이 전한다. 신라말부터 고려 전기까지 폐사되었던 절로 고려 명종 2년(1172) 보조국사가 절을 다시 세웠으나 임진왜란 뒤 60년 동안 다시 폐사되었다. 훗날 조선 효종 2년(1651)에 각순대사가 대웅전·영산전·대적광전 등을 고쳐 지었다고 한다. 이 건물은 ○○○의 중심 법당으로 해탈문·천왕문과 일직선으로 놓여 있다.","a":"공주 마곡사 대광보전","c":"보물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617973.jpg"},{"q":"○○는 도자기나 기와·그릇을 만들어 굽던 가마터를 말한다. ○○○의 봉우리 중 평평한 고원지대에 위치하는 백자 가마터로 5∼6기가 있다. 높이1,100m가 넘는 험준한 산의 꼭대기부분에 있어, 우리나라에 존재하는 가마터 중 가장 높은 곳에 있는 것으로 여겨진다. 발견되는 백자조각들은 대접·사발·바래기·접시·술잔조각 등이 대부분이며, 접시 중에는 아가리가 안으로 말리거나 밖으로 말려있는 것도 있다. 품질이 좋은 편이 아닌 중·하품의 백자를 굽던 곳으로, 순백자 뿐 아니라 검은 빛깔로 그림이 그려진 철화무늬 백자조각들도 발견된다.","a":"울주 천황산 요지","c":"사적","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625370.jpg"},{"q":"「○○○○○」은 한국전쟁 직후, ○○○○○ 캠퍼스를 조성하는 과정에서 1956년 대학 본부로 건립되었다. 외관을 석재로 마감하고 정면 중앙부에 열주량을 세우는 등 당시 대학 ○○ 건물에서 보여지는 신고전주의 양식의 디자인적인 요소들이 잘 보존되어 있다. 또한, 우리나라에서 유일하게 공학을 모태로 성장한 대학으로 경제개발기에 중추적인 역할을 한 기술인력을 배출한 ○○○○○의 역사를 상징한다는 점에서 의미가 크다.","a":"서울 한양대학교 구 본관","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"성동구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2019051310185900.jpg"},{"q":"조선 중기의 문신인 ○○○을 그린 ○○화 1점과 1등 공신으로 책록하는 교서 1부 그리고 그것들을 담았던 나무로 만든 상자 1점 등 3점의 유물이다. ○○○은 숙종 31년(1705) 문과에 급제하고 그 뒤 이조좌랑, 병조판서, 우의정까지 올랐던 인물로 영조 3년(1727) 이인좌의 난을 평정한 공로로 1등 공신으로 봉해졌다. ○○화는 가로 1.03m, 세로 1.74m로 비단에 채색하여 그린 전신상이다. 오른쪽을 바라보고 있으며, 머리에는 검은색 사모를 쓰고 짙은 청록색의 관복을 입었다.","a":"오명항 초상 및 양무공신교서","c":"보물","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616035.jpg"},{"q":"○○○는 신라 진덕여왕 5년(651) 의상이 세웠다고 전하는데, 당시 이곳 연못 위에 다섯 부처님의 영상이 떠오르는 모습을 보고 거기 살던 용을 쫓아낸 뒤 절을 지었다는 전설이 전한다. 조선 태조 5년(1396) 나한전만 남긴 채 화재로 모두 불에 타 버렸고 임진왜란 때에도 영산전만 남기고 모두 불 타 버렸던 것을 훗날 다시 짓고 많은 수리를 거쳐 오늘에 이르고 있다. ○○○은 석가모니를 중심으로 좌우에 아난·가섭과 16나한상을 모시고 있다.","a":"울진 불영사 응진전","c":"보물","nc":"","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621499.jpg"},{"q":"경상북도 ○○군 장육사에 있는 높이 86㎝의 조선 초기 건칠보살좌상이다. 건칠불이란 진흙으로 속을 만들어 삼베를 감고 그 위에 진흙가루를 발라 묻힌 다음 속을 빼어버린 것이다. 불상 안에서 발견된 원문(願文)과 개금묵서명(改金墨書銘)을 통해 홍무 28년(태조 4년, 1395)에 영해부의 관리들과 마을 사람들의 시주로 만들었고, 영락 5년(태종 7년, 1407)에 다시 금칠하였음이 밝혀졌다. 얼굴은 사각형인데 눈이 치켜 올라갔고 코도 날카로우며 표정이 완고하다.","a":"영덕 장륙사 건칠관음보살좌상","c":"보물","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621924.jpg"},{"q":"○○○○○는 지리산 남서쪽 자락에 위치한 사찰로 사적기에 따르면 신라 흥덕왕 3년(828년) 덕운선사(德雲禪師)에 의해 창건되어 감로사(甘露寺)라고 불리다가 숙종 5년(1679년) 조유선사(祖裕禪師)에 의해 중창되면서 ○○○로 바꾸었다. ○○○의 주불전인 ○○○○은 영조 50년(1774년)에 혜암선사(惠庵禪師)가 중창불사를 일으키면서 세워졌다. 아미타불을 주불로 하며, 정면 3칸 측면 3칸 규모의 다포계 팔작지붕 건물이다.","a":"구례 천은사 극락보전","c":"보물","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2019052310073900.JPG"},{"q":"1940년대 건립 이 건물은 전북특별자치도 지역에 만들어진 ○○○○○에 소속된 일식 목조 주택이다. 1층은 정방형에 가까운 평면으로 ‘ㄱ’자형의 복도를 따라 방들을 배열하였고, 2층에는 외부의 전경을 감상할 수 있는 발코니가 돌출되어 있어 독특한 외관을 이루고 있다. 대○○에 소속된 건물로 일제의 농업 수탈 현장을 증언하고 있다.","a":"익산 춘포리 구 일본인 농장 가옥","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668765.jpg"},{"q":"기린산을 북쪽에 두고 남쪽으로 넓은 평야를 둔 야산에 위치한 ○○○터는 고려 문종(재위 1046∼1083) 때 지어진 것으로 전한다. 5층과 2층으로 된 불상을 모시는 법당이 있었고, 그 안에는 높이 35척(약 10m)의 불상이 있었다는 기록이 있다. 당시에는 대웅전을 비롯한 많은 건물들과 수백 명의 승려들이 머무는 큰 절이었으나 정유재란(1597)때 ○○성이 함락되면서 불타 버렸다고 한다. 발굴조사시 많은 건물의 흔적을 찾았으며 청자와 백자, 많은 기와가 출토되어 고려시대 미술사 연구에 귀중한 자료를 제공한다.","a":"남원 만복사지","c":"사적","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626933.jpg"},{"q":"<○○○○○>은 조선시대 헌종의 어머니인 ○○○의 40세 생신을 축하하는 잔치모습을 그린 ○○이다. ○○○는 순조 19년(1819) 세자빈으로 책봉되었으나 세자가 왕위에 오르지 못하고 일찍 죽어 왕비는 되지 못하고, 후에 그의 아들인 헌종이 왕위에 오르자 후에 왕대비가 되었다. 가로 458㎝, 세로 169㎝의 8폭으로 된 ○○으로 7폭은 전각, 나무, 산수를 채색하여 그렸고 마지막 1폭은 도총관 조기영 등 9명의 관등과 이름이 기록되어 있다.","a":"조대비 사순칭경진하도 병풍","c":"보물","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615096.jpg"},{"q":"백제의 옛 땅이었던 충청·전라도에는 ○○ 정림사지 오층석탑(국보)의 양식을 모방한 백제계 석탑이 몇 개 전하고 있는데 이 탑 역시 그런 계열에 속하는 탑이다. 땅 위에 자연석에 가까운 바닥돌을 깔고 그 위에 같은 돌로 너비를 좁히면서 3단의 기단(基壇)을 만들었다. 탑신(塔身)은 네 귀퉁이에 위로 오를수록 좁아지는 형태의 기둥 모양을 새겼고, 그 사이에 긴 판돌을 세워 면을 이루게 하였다. 동서남북 사면에 감실모양이 있는데, 우주와 면석의 약화된 모습으로 보는 경우도 있다. 감실은 목탑에 많이 나타나던 것으로 불상을 모시는 방을 의미한다.","a":"부여 장하리 삼층석탑","c":"보물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617583.jpg"},{"q":"○○○은 경주 황남동고분 제155호 무덤으로 1973년 발굴하여 금관, 팔찌 등 많은 귀중한 유품들과 함께 천마 그림이 발견되어 ○○○이라 부르게 되었다. ○○○○○는 ○○○ 안의 널<관(棺)>에서 발견된 것으로, 가슴 윗 부분에서 있던 것으로 보아 ○○○로 쓰였던 장신구이다. 금, 은, 비취, 유리 등의 재료를 사용했는데, 원래의 줄 외에 가슴 부근에서 좌우로 늘어지는 짧은 가닥이 달려있다. 청색 유리옥과 금·은 제품이 여섯줄로 이어져 일정한 간격으로 연결되어 있는데, 좌우에는 큰 굽은 옥이 매달려 있다. 이 경식은 목에 걸었을 때 전체가 V자형이 된다.","a":"천마총 목걸이","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621295.jpg"},{"q":"○○○○은 경(經)과 율(律)에서 요점을 각 주제별로 뽑아 출전을 표시하여 학습하는데 편리하게 엮은 일종의 백과사전이다. 남해의 분사대장도감에서 목판을 새기고 제본한 것으로 짐작하여 고려 후기에서 조선 전기에 간행된 것으로 보인다. 이것은 전체 50권중 제1권에 해당된다. 또한 새긴 사람의 이름이 표시되어 있는데, 새긴 사람의 솜씨에 따라 정교하고 조밀함의 차이를 보인다. 이 책은 고려시대 대장경을 연구하는데 상호 보완적인 성격을 지니고 있다.","a":"재조본 경률이상 권1","c":"보물","nc":"","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615407.jpg"},{"q":"○○○○○은 ○○○에 있는『화엄경』정원본 40권, 진본 60권, 주본 80권 등 3종의 대방광불화엄경을 나무판에 새긴 것이다. 대방광불화엄경은 줄여서 ‘화엄경’이라 부르기도 하는데 화엄종의 근본경전으로 법화경과 함께 한국 불교사상 확립에 가장 크게 영향을 끼친 경전이다. 정원본(貞元本)은 반야가 번역한 화엄경 40권을 가리키고, 진본(晋本)은 불타발타라가 번역한 화엄경 60권을, 주본(周本)은 실차난타가 번역한 화엄경 80권을 가리킨다. 이 판은 모두 합쳐 634판이며 한 줄에 34자씩 글자를 배열한 특이한 형식이다.","a":"영주 부석사 고려목판","c":"보물","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621507.jpg"},{"q":"○○ 시가지 중심에 자리잡고 있는 탑이다. 조선 인조 때 이곳의 현감이었던 유정립이 인조반정으로 파직당하고 낙향하여 이 탑 부근에 집을 세우려고 터를 닦다가 ‘충원사(忠圓寺)’라는 글이 새겨진 그릇을 발견하여, 충원사 내에 속하였던 것이 아닐까 추측된다. 한국전쟁 때 심한 손상을 입어 보존 상태가 좋지 않은 데다 기단의 일부가 지하에 파묻혀 있었는데, 지난 2000년에 시행된 전면적인 보수공사로 기단부의 제 모습을 찾게 되었다. 이 석탑은 아랫부분을 발굴 조사한 결과 2층기단 위에 7층의 탑신이 놓여진 것으로 확인되었다.","a":"춘천 칠층석탑","c":"보물","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616253.jpg"},{"q":"대방○○○○○료의경은 줄여서 ‘원각경’이라고 부르기도 하며, 우리나라 승려들의 교과과목으로 채택되어 불교 수행의 길잡이 구실을 하는 경전이다. 우리나라에서는 고려의 지눌이 깊이 신봉하여 ‘○○○’이라고 한 뒤 크게 유행하였다. 상○○○○○료의경(橡紙金泥大方廣圓覺修多羅了義經)은 갈색 종이에 금색 글씨로 불경을 정성스럽게 옮겨 쓰고, 불경의 내용을 요약하여 묘사한 변상도(變相圖)를 그려 화려하고 장엄하게 꾸민 것이다. 병풍처럼 펼쳐서 볼 수 있는 형태로 되어있는데, 권 상·하를 합쳐 한 권의 책으로 엮었으며, 접었을 때의 크기는 세로 26.5㎝, 가로 11.5㎝이다.","a":"상지금니 대방광원각수다라요의경","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613807.jpg"},{"q":"○○○에 있는 비(碑)로, 고려 전기의 승려 현각선사를 기리기 위해 세운 것이다. 임진왜란 당시 비몸돌이 없어져 현재는 받침돌과 머릿돌만 남아 있다. 비를 받치고 있는 돌거북은 부리부리한 두 눈과 큼직한 입이 웅장하며, 수염을 가진 용머리를 하고 있다. 등 중앙에 마련된 비를 꽂아두는 부분에는 안상(眼象)과 꽃조각이 새겨져 있다. 받침돌 위에 놓여 있는 비의 머릿돌에는 여러 마리의 용이 서로 얽힌 모습이 조각되어 있는데, 긴밀하고 사실성이 두드러진다. 앞면의 가운데에는 탑이름이 새겨져 있어, 현각선사의 탑비임을 알수 있다.","a":"구례 연곡사 현각선사탑비","c":"보물","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618812.jpg"},{"q":"음식물로 병을 예방하는 내용을 담은 전문의학서적으로, 중종 21년(1526)에 중국 명나라 요문청(姚文淸) 등의 서문을 붙여 간행한 것을 중종∼명종년간(1526∼1556)에 다시 갑진자로 간행한 것이다. 이 책은 수(水)·곡(穀)·채(菜)·과(果)·금(禽)·수(獸)·어(魚)·미(味) 등 8류(類)로 나누어 상권과 하권에 수록하였다. 상권에는 수·곡·채·과 등 4류 212조가, 하권에는 금·수·어·미 등 4류 175조가 수록되었다. 각류(各類)에서는 조목마다 해당식물의 맛, 본성, 이익, 해독 등을 적어 설명하고 말미에는 각류의 식물에 대한 총론을 적고 있다.","a":"식물본초","c":"보물","nc":"","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615447.jpg"},{"q":"공신녹권은 나라에 공이 있는 인물에게 공신으로 임명하는 증서를 말한다. 이 녹권은 태종이 잠저(潛邸, 동궁)에 있을 때 밤낮으로 보좌한 신하들의 공로를 가상히 여겨 포상하고 수여한 원종공신록권으로, 태종 11년(1411) 11월에 당시 통훈대부판사재감사였던 ○○에게 발급한 3등공신록권이다. 크기는 가로 243㎝, 세로 34.7㎝이며, 종이질은 닥나무종이이다. 태조 이성계가 봉한 원종공신 이후 두 번째로 발급된 녹권으로, 조선 전기 공신에 대한 대우와 공신록 양식을 연구하는 귀중한 역사적 자료로 평가된다.","a":"이형 좌명원종공신녹권 및 함","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614977.jpg"},{"q":"이 화차(貨車)는 철도 화물을 수송하기 위하여 미국에서 제작한 협궤선용 화물열차로 덮개가 없다. 표준보다 좁은 협궤 노선인 수인선(수원~인천 송도), 수여선(수원~여주)에서 석탄, 광물 등을 주로 운반하는 데 사용하였으며, 소래 지방에서 생산된 소금 운송에도 사용하였다. 1995년 수인선이 폐지되면서 협궤 운행이 중단되어 지금은 사용하지 않는다.","a":"협궤무개화차","c":"국가등록문화유산","nc":"","r":"경기도","s":"의왕시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668161.jpg"},{"q":"○○○에 세워졌던 신라 ○○○비의 옛 자리이다. ○○○비는 비석을 세운 이래 1,200여 년 동안 잊혀져 오다가 19세기 전반에 추사 김정희에 의해서 발견되었다. ○○○비에는 ○○○이 ○○○을 둘러보고 돌아오는 길에 지나온 여러 고을에 세금을 면제해 주고, 죄수들을 석방하도록 했다는 내용이 들어 있다. 지금까지 학계에서는 ○○○비의 ‘남천’이란 글자를 통해 4개의 ○○○비 가운데 가장 늦은 재위 29년(568) 이후에 건립된 것으로 보았으나, 연구가 진전됨에 따라 오히려 ○○○비를 가장 이른 시기의 것으로 보는 견해가 옳은것 같다.","a":"북한산 진흥왕 순수비지","c":"사적","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624735.jpg"},{"q":"○○○는 통일신라 후기에 창건된 것으로 추정되며 고려 명종 때인 12세기에 원각국사에 의해 중창이 있었던 것으로 추정된다. 고려 고종 때 안종필이 왕의 명을 받아 탑, 부도, 금당을 새로 짓고 절이름을 국청사(國淸寺)라 하였다. 뒤에 다시 공민왕에 의해 ○○○로 불리게 되었다. 이 탑은 ○○○에서 동쪽으로 500m 되는 곳의 ○○○이라는 작은 봉우리 정상에 위치하고 있다. 커다란 화강암을 기단(基壇)으로 삼고 위로 3층의 탑신(塔身)을 올린 형태이다. 기단은 암석 윗면을 평평하게 다듬고 그 중앙에 돌출된 자연석을 그대로 이용하였다.","a":"영동 영국사 망탑봉 삼층석탑","c":"보물","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617085.jpg"},{"q":"○○○은 대한민국 임시정부의 주석이었던 백범 김구선생이 1945년 중국에서 돌아온 이후 1949년 6월 26일 암살당할 때까지 집무실과 숙소로 사용했던 건물이다. 1938년에 건립된 이 건물의 명칭은 당초 죽첨장(竹添莊)이었으나 김구선생의 거처로 사용되면서 근처의 개울이름을 따서 ○○○으로 이름을 변경하였다고 전한다. 이후 자유중국대사관 관저, 국군의료진 주둔지, 월남대사관 관저 등으로 사용되었으며 1968년 고려병원(현 강북삼성병원)이 인수하여 현재에 이르고 있다.","a":"서울 경교장","c":"사적","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625100.jpg"},{"q":"조선시대 바람의 세기와 방향을 재는데 사용했던 것으로 풍기와 ○○○에 대해 『증보문헌비고』를 보면 다음과 같은 사실을 알 수 있다. 화강암을 다듬어 아래에 상을 조각한 대를 놓고, 그 위에 구름무늬를 새긴 8각기둥을 세운 모습이다. 8각형 기둥의 맨 위의 중앙에는 깃대를 꽂는 구멍이 있고, 그 아래 기둥옆으로 물이 고이지 않게 배수구멍을 뚫었다. 깃대 길이는 확실치 않고 깃대 끝에는 좁고 긴 깃발을 매어 그것이 날리는 방향으로 풍향을 재고 나부끼는 정도로 바람의 세기를 알 수 있었다.","a":"경복궁 풍기대","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614087.jpg"},{"q":"약 200m의 거리를 사이에 두고 마주 서 있는 2구의 석상으로, 사다리꼴 모양의 돌기둥에 얼굴, 손, 대좌 등이 표현되어 있다. 이 불상에 얽힌 전설에 의하면 음력 12월에 두 불상이 만나 1년 동안의 회포를 풀고 새벽닭 우는 소리를 듣고 제자리로 돌아가는 남녀상이라고 한다. 머리에는 4각형의 높은 관(冠) 위에 다시 4각형의 갓을 쓰고 있다. 4각형의 얼굴에는 가는 눈, 짧은 코, 작은 입이 간신히 표현되어 있는데, 토속적인 수호신의 표정이다. 목은 무척 짧게 표현되어서 어깨와 얼굴이 거의 붙어 있는 셈이다.","a":"익산 고도리 석조여래입상","c":"보물","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618232.jpg"},{"q":"극락보전 후불벽화인 아미타후불벽화(보물)의 뒷면 그림으로, 떠가는 듯 일렁이는 파도 위에 연잎을 타고 서 있는 백의관음보살이 그려진 벽화이다. 하얀 옷을 입고 있는 백의관음보살은 당당한 체구에 흰 옷자락을 휘날리며, 오른쪽으로 몸을 약간 돌린 채 두손을 앞에 모아 서로 교차하여 오른손으로는 버들가지를 들고 왼손으로는 정병을 들고 서 있다. 간략화된 옷주름과 더불어 팔찌와 가슴장식 역시 간소화되어 있긴 하나, 힘있고 빠른 필치로 바람에 심하게 흩날리는 듯한 옷자락과 넘실대는 듯한 파도를 표현함으로써 강한 인상을 보여주고 있다.","a":"무위사 극락전 백의관음도","c":"보물","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619667.jpg"},{"q":"○○ 낭산(狼山)의 기슭에 자리하고 있는 절터로 사천왕사와 마주하고 있다. 처음 지어진 때는 정확하지 않으나 신라 문무왕 또는 신문왕 때로 전한다. 『삼국유사』에 의하면 문무왕 19년(679)에 중국 당나라가 침입하자 부처의 힘으로 물리치고자 사천왕사를 짓게 되었다고 한다. 그 소문이 당나라에 전해지자 당에서는 사신을 파견하여 이를 확인하려 하였는데, 신라에서는 사천왕사 건너편에 이 절을 지어 보여 주었고, 당나라의 덕을 우러른다는 의미에서 ○○○라 하였다고 한다.","a":"경주 망덕사지","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627513.jpg"},{"q":"조선 전기의 문신 정여창(1450∼1504) 선생의 지리산의 별장을 그린 그림이다. 정여창 선생은 성종 14년(1483)에 과거에 급제하여 여러 벼슬을 지냈다. 이 그림은 정여창 선생이 한동안 성리학과 오경을 연구하면서 머물렀던 별장이 훼손되는 것이 아쉬워 정씨 문중에서 이징(李澄)을 불러 그리도록 한 것이다. 가로 56㎝, 세로 89㎝의 크기로 명주 바탕에 그렸는데, 화면의 맨 위에는 “○○○○○”란 제목이 전서체로 적혀 있고, 중간에는 별장의 주변 산수를 엷게 채색하여 그렸다.","a":"화개현구장도","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614408.jpg"},{"q":"왕실이 후원한 미술교육기관인 서화미술원에서 교육받은 대표적 신진 화가인 김은호에 의해 1920년경 제작되어 ○○○에 부착된 벽화로, 채색 화조화의 전통을 계승하고 있으며, 형상의 표현과 기술묘사에 충실하여 화려한 구성을 담고 있다. 궁중 벽화로는 다른 5점과 더불어 유일하게 현존하고 있으며, 단순한 장식이 아닌 전각의 기능과 연계되어 추락한 왕실의 안녕 및 권위의 회복, 왕실의 역량을 재확인하는 길상적, 상징적 의미를 갖고 있어 역사적, 예술적 가치가 있다.","a":"창덕궁 대조전 백학도","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667055.jpg"},{"q":"○○○에서 동북쪽으로 약 150m지점 언덕에 서 있는 탑이다. 2층을 이루는 기단(基壇)은 원형과 8각이 조화를 이루고 있어 특이한 모습이며 그 위로 4각의 탑신(塔身)을 3층으로 쌓아 올렸다. 기단의 모습은 매우 독특한 예인데 그 유래에 대해서는 밝혀지지 않고 있다. 전체적으로 원과 4각, 8각의 조화가 아름답고, 세부 수법의 경쾌함이 돋보이는 석탑으로, 8세기 말 통일신라시대에 만들어진 것으로 짐작된다.","a":"경주 석굴암 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621796.jpg"},{"q":"추사 ○○○ 고택의 전래 ○○로 추정되는 월성위 김한신 관련○○과 『신해년책력』(표제1점, 유묵15점)의 ○○○○○은 서예사 연구 자료로 가치가 있다. ㅇ 월성위 김한신 관련 ○○ - 『매헌난고(梅軒亂稿)』 김한신의 시집(詩集)으로 13~34세까지의 시작(詩作)을 모은 것이다(총 20면). 다음의 『교사시말』과 함께 김한신의 자필(自筆)로 추정된다. 아직까지 김한신의 문집이 간행되지 않았고 다른 필사본도 보기 어려우므로 아래의 『월성위행장』과 더불어 김한신 관련자료로 가치가 높다.","a":"김정희 종가 유물 일괄","c":"보물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1623075.jpg"},{"q":"사적 ○○○ 안에 있는 ○○○은 1909년에 건축된 주철골구조와 목조가 혼합된 구조체에 외피를 유리로 둘러싼 우리나라 최초의 양식 온실로써 19세기 근대건축의 새로운 유형인 철과 유리가 20세기 초 우리나라에 유입되어 건축된 모습을 보여주고 있다.","a":"창경궁 대온실","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1666918.jpg"},{"q":"○○○○○은 숙종 1년(1675년), 조선 중기의 문신인 팔송 윤황(八松 尹煌, 1571~1639)의 학문과 덕행을 추모하고 지방민의 유학 교육을 위하여 세운 서원이다. 숙종 8년(1682년)에 사액(賜額)을 받았고, 윤황을 비롯한 윤문거(尹文擧, 1606~1672), 윤선거(尹宣擧, 1610~1669), 윤증(尹拯. 1629~1711) 등 충청도 지역 소론계의 대표적인 인물들을 배향(配享, 신주를 모심)하고 있다.","a":"논산 노강서원","c":"사적","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2017091508263200.bmp"},{"q":"절에서는 불교의식이 있을 때 사찰 입구에 당(幢)이라는 깃발을 달아 두는데, 이 깃발을 다는 장대를 당간(幢竿)이라 하며, 당간을 양쪽에서 지탱해 주는 두 돌기둥을 ○○○○라 한다. 이 ○○○○는 ○○읍내의 경작지 한가운데에 78㎝ 간격을 두고 마주 서있다. 이 일대는 고려시대의 광경사(廣慶寺)터로 알려져 있고 석탑 및 석불좌상 등이 함께 전하고 있다. 전체적인 형태는 위로 오를수록 가늘어지고 윗쪽에 당간을 고정시키기 위한 홈이 파여있으며 가운데 깃대는 남아있지 않다. 기둥의 바깥면에는 세로줄 문양이 새겨져 있고 기둥 머리부분은 둥글게 처리되었다.","a":"홍성 오관리 당간지주","c":"보물","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617801.jpg"},{"q":"고려시대부터 이곳에 해월사(海月寺)라는 절이 있었다고 하는데, 그 절에 속했던 석탑으로, 지금 자리한 곳이 원래의 위치로 짐작된다. 1단으로 이루어진 기단(基壇)은 4장의 돌로 구성되었으며, 각 모서리와 면의 가운데에 기둥 모양을 새겨두었다. 기단의 맨윗돌에는 특별한 장식을 하지 않아 두껍고 밋밋하다는 느낌을 주는데, 이러한 양식은 정읍 은선리 삼층석탑과 비슷하다. 탑신부의 1층 몸돌은 기단에 비해 좁고 기형적으로 길고 높은 매우 특이한 양식을 보이고 있다. 지붕돌은 몸돌에 비해 상당히 넓고 두꺼워 불안정한 느낌을 주며, 각 층 지붕돌의 모습에도 차이가 있다.","a":"진도 금골산 오층석탑","c":"보물","nc":"","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619267.jpg"},{"q":"이 탑이 위치하고 있는 ○○○○는 통일신라시대 왕경 내에 형성된 도시가람으로 지리적 입지 상 중요한 역할을 수행한 사찰일 가능성이 높다. 이는 왕경의 중심적 위치에 자리하고 있고 문헌자료와 발굴된 유물로 확인이 되고 있는데 발굴조사과정을 통해 「味呑」명 기와가 수습됨으로써 『삼국유사』에 기록된 미탄사가 이곳임이 밝혀졌고, 추정 금당지 및 강당지를 비롯해 남문지 등 사역의 일단이 확인된 바 있다. ○○○○○은 6.12m의 규모로, 총 35매의 부재로 구성되어 있다.","a":"경주 미탄사지 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2017011209530400.JPG"},{"q":"영암사터는 황매산(黃梅山) 남쪽 기슭에 있는 신라시대의 절터이다. 절의 창건연대는 알려지지 않았으나 1014년에 적연선사(寂然禪師)가 이 곳에서 입적했다는 기록이 있어 그 이전에 세워진 것으로 짐작된다. 절터에는 석탑을 비롯하여 쌍사자석등, 귀부 등 각종 석조유물이 남아 있다. 이 탑은 탑신부가 무너져 있던 것을 1969년에 복원하였으며, 현재 금당 앞에 새로 세운 두 채의 건물사이에 서 있다. 2단의 기단(基壇) 위에 세워진 3층석탑으로 통일신라석탑의 전형양식을 따르고 있다. 기단은 모서리와 가운데에 기둥 모양을 본떠 새겼다.","a":"합천 영암사지 삼층석탑","c":"보물","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622703.jpg"},{"q":"괘불이란 절에서 큰 법회나 의식을 행하기 위해 법당 앞 뜰에 걸어놓고 예배를 드리는 대형 불교그림이다.이 그림은 괘불에서 많이 그려지는 ○○○상도로 석가가 설법하는 장면을 나타낸 것이다. 숙종 14년(1688) 승려 화가인 학능 등이 그린 이 괘불은 전체 1,330×811.6cm, 화면 1,240×784.6cm이다. 전해오는 전설에 의하면 어느날 당나라 승려가 찾아와 괘불을 그리겠다고 하면서 3일 동안 출입을 금하라고 했다. 한 승려가 궁금해서 엿보니 파랑새가 입에 붓을 물고 그림을 그리는 것이었다.","a":"북장사 영산회 괘불탱","c":"보물","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622163.jpg"},{"q":"단속사 터의 금당터 앞에는 동서로 두 탑이 서 있는데 그 중 서쪽에 세워진 것이 이 탑이다. 2단의 기단(基壇)에 3층의 탑신(塔身)을 올린 통일신라시대의 전형적인 모습이나, 동탑에 비하여 많이 부서지고 안에 봉안된 사리함이 도난당하는 등 많은 수난을 겪었다. 기단에는 각 면의 모서리에 기둥 모양의 조각을 두었는데, 아랫단은 가운데에 2개씩을 두고 윗단은 1개씩 두었다. 탑신의 지붕돌은 처마를 직선으로 처리하였으며, 밋밋한 경사가 흐르는 윗면은 네 귀퉁이에서 하늘을 향해 살짝 들어 올렸다.","a":"산청 단속사지 서 삼층석탑","c":"보물","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622339.jpg"},{"q":"최초 ○○○○○의 건물로서 톱날형 지붕 구조는 북쪽에 창을 높게 설치하여 내부에 균일한 빛을 받기위한 것이며, 이는 초기 산업유산으로서 제사○○ 건축을 이해할 수 있다는 측면에서 의미가 있다. 또한 한국전쟁 당시 조치원여자고등학교 임시교사로 사용되었던 장소로 지역적, 역사적 의미를 지닌 건물로 보존가치가 크다. * 제사○○ : 누에고치에서 실을 만드는 ○○","a":"세종 구 산일제사 공장","c":"국가등록문화유산","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/register/thumb/2019060414283300.JPG"},{"q":"배중손이 이끌던 삼별초가 몽골의 침략에 대항하여 항쟁을 벌였던 장소이다. 고려 고종 18년(1231)부터 침략해 오던 몽골과의 전쟁을 벌이기 위해 고려는 수도를 개경에서 강화로 옮겼다. 그리고 40여 년 동안 삼별초가 중심이 되어 몽골과의 전쟁을 벌였으나, 원종 11년(1270) 고려가 몽골에 항복을 하였다. 몽골에 대한 항복을 받아들일 수 없던 배중손을 비롯한 삼별초는 왕족인 승화후 온(承化候溫)을 왕으로 삼아 남쪽으로 내려와 이곳에 궁궐과 성을 쌓고 몽골과의 전쟁을 계속하였다. 이때 쌓은 성이 바로 ○○○이다.","a":"진도 용장성","c":"사적","nc":"","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627060.jpg"},{"q":"연산의 황산성, 노성의 노○○○ 및 금강 건너의 성흥산성, 뒤쪽의 금○○○과 연결되는 백제의 수도 사비 남쪽 외곽을 방어하기 위해 쌓은 산성이다. 이 산성은 안쪽에 성을 세운 후, 다시 성 밖에 2개의 골짜기를 따라 성을 쌓았다. 현재는 성문터와 성문 밑으로 개울물이 흐르게 하던 수구문, 그리고 우물터와 건물터들이 남아있다. 6세기 전반에 세워진 것으로 둘레 약 1,5㎞, 폭 약 5m, 높이 4m 정도로, 바깥쪽은 돌을 쌓아 올리고 안쪽은 흙을 파서 도랑(호)처럼 만들어 놓았던 것으로 보인다.","a":"부여 석성산성","c":"사적","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626500.jpg"},{"q":"이 건물은 ○○○의 전형을 알 수 있는 단층의 합각 함석지붕 목조건축물로, 지붕 목조트러스 가운데 목부재에 쓰여진 기록을 통해 1930년에 목수 성조운(成造運)이 건립하였음을 알 수 있다. ○○○의 환기를 위해 높은 창을 두고 보온을 위해 벽체와 천장에 왕겨를 채웠으며, 외부 마감은 목재 널판을 사용하는 등 목조 건축물로서 독특한 형식을 갖추고 있다.","a":"진천 덕산양조장","c":"국가등록문화유산","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668499.jpg"},{"q":"○○○○은 남한산성이 있는 청량산에서 북쪽방향으로 내려오는 줄기와 만나 길게 맥을 형성하는 금암산의 줄기에 접해 있으며, 남쪽은 평야를 둘러싸고 있는 높은 산들이 있으나 북쪽은 작은 구릉만 있어 한강 주변지역을 한 눈에 조망할 수 있다. 따라서 ○○○○은 배후의 평야지역을 방어하고 강북의 적으로부터 한강유역을 방어하기에 매우 유리한 입지조건을 갖춘 지점에 위치하고 있다.","a":"하남 이성산성","c":"사적","nc":"","r":"경기도","s":"하남시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625936.jpg"},{"q":"○○○는 원래 고려 원종 6년(1265) 명본국사가 세워 대장암(大藏庵)이라 불렀던 곳이다. 공민왕 13년(1364) 나옹화상이 크게 넓히면서 ○○○라 이름을 고쳤는데 청룡이 구름을 타고 내려오는 광경을 보고 지었다는 전설이 전한다. 절의 중심 법당인 ○○○은 조선 후기에 다시 지은 건물로 추측한다. 규모는 앞면 3칸·옆면 4칸이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 짜은 구조가 기둥 위와 기둥 사이에도 있다.","a":"안성 청룡사 대웅전","c":"보물","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615864.jpg"},{"q":"○○○ 계곡을 둘러 돌로 쌓아 만든 산성으로 백제 때 부터 이미 이곳에 토성이 있었던 것으로 짐작되는 곳이다. 『삼국사기』에는 통일신라 초기에 김유신의 셋째 아들이 서원술성을 쌓았다는 기록이 있는데 이때 쌓여진 것이 아닌가 추측되기도 한다. 상당이란 이름은 백제 때 ○○목을 상당현이라 부르던 것에서 유래한 것이다. 지금의 성은 임진왜란 때에 일부 고쳤으며 숙종 42년(1716)에 돌성으로 다시 쌓은 것이다. 성벽은 네모나게 다듬은 화강암으로 쌓았으며, 비교적 잘 남아있으나 성벽 위에 낮게 쌓은 담(여장)은 전혀 남아있지 않다.","a":"청주 상당산성","c":"사적","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626243.jpg"},{"q":"한국전쟁 이후인 1957년에 건립된 관공서 건물로서 외벽에 석재를 이용하여 마감한 건축방법 등은 당시의 건축적 상황을 보여주고 있다. 또한 정면 현관 상부를 동물문양과 무궁화 문양으로 장식 처리한 것이 특징적이다","a":"파주 구 교하면사무소","c":"국가등록문화유산","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2018081418301900.jpg"},{"q":"『○○○○○』은 17세기 후반의 문신ㆍ명필 ○○○의 ○○으로 다양한 크기에 여러 서체로 쓰여 있다. 해서ㆍ행초ㆍ광초ㆍ예서ㆍ행서가 실려 있으며 그중 해서는 소해(小楷)ㆍ중해(中楷)ㆍ대자서(大字書)로 다양하다. 특히 칠언배율의 시를 중자 해서로 쓴 글씨는 그가 안진경 해서풍을 적극 가미시켰음을 보여준다. 또 행초를 섞어 쓴 칠언절구는 아버지 박세당의 서풍을 따랐는데 그 바탕은 안진경의 행초 ○○에 가깝다. 또 한 면에 두 글자씩 대자 초서로 쓴 “사지격절(辭旨激切)”ㆍ“이식현오(理識玄奧)”는 광초(狂草)의 대가 당나라 회소(懷素, 8세기 활동)의 서풍을 연상하게 한다.","a":"박태유 필적 백석유묵첩","c":"보물","nc":"","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616196.jpg"},{"q":"고려시대에 만들어진 뚜껑이 있는 그릇(합)으로 높이 9.9㎝, 아가리 지름 18.3㎝의 크기이다. 고려시대에 크게 유행한 문양을 파내고 은실을 박아 장식하는 ○○○ 기법을 사용하여 제작한 그릇으로, 아래 몸통과 뚜껑의 크기가 같아 안정감 있게 보인다. 뚜껑과 몸통 위·아래 가장자리는 모를 깎아 둥글게 처리하였는데, 이러한 형식은 고려시대 철기, 자기, 상자, 합들에서 많이 보이는 양식이다. 뚜껑 윗면 중앙에 봉황이 있고, 그 주위에 꽃무늬와 덩굴무늬로 장식하였다. 바깥 가장자리의 경사면에는 ○○○ 기법으로 덩굴무늬를 장식했다.","a":"청동 은입사 봉황문 합","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611622.jpg"},{"q":"○○○○○은 조익형○○ 1점, 접형○○ 2점으로서 총 3점이 출토 되었다. 조익형○○은 부장품수장부 북쪽에서 1개가 출토되었다. 새가 날개를 활짝 펴고 나는 모습을 도안화한 ○○으로 관모(冠帽) 앞에 꽂기 위한 것이다. 양쪽 날개와 가운데 꽂이 부분이 각기 다른 은판을 오려서 붙인 것으로 날개는 좌우가 같은 모양이나 부식되어 떨어졌다. 날개와 꽂이 상단부분은 ○○ 잔못으로 박아 결합시켰고 꼬리부분 즉 부채꼴 가운데 꽂이를 제외하고 가장자리에는 두줄의 타출점렬문(打出點列文)을 돌렸다.","a":"황남대총 북분 은제 관식","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621302.jpg"},{"q":"○○ 손씨 큰 종가로 이 마을에서 시조가 된 양민공 손소(1433∼1484)가 조선 세조 5년(1459)에 지은 집이다. 양민공의 아들 손중돈 선생(1463~1529)과 외손인 이언적(1491∼1553) 선생이 태어난 곳이기도 하다. 一자형 대문채 안에 ㅁ자형 안채가 있고, 사랑채 뒷쪽 높은 곳에 신문(神門)과 사당이 있다. 안채는 지붕 옆면이 여덟 팔'(八)'자 모양인 팔작지붕이고, 사랑채는 지붕 옆면이 사람 인'(人)'자 모양인 맞배지붕이다. 사랑방과 침방이 대청을 사이에 두고 'ㄱ'자형으로 놓여 있는 사랑채 뒷편 정원에는 수백년 묵은 향나무가 있다.","a":"경주 양동마을 송첨종택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634770.jpg"},{"q":"○○○ 대웅전의 주존으로 모셔진 이 불상은 고려 말 조선 초에 특히 많이 조성된 건칠불상이다. 양식적으로 이 불상은 다소 길어진 신체의 비례와 형태, 작아진 얼굴, 착의형식, 옷 주름의 표현 등에서 고려후기 불상 양식을 계승한 조선 초기에 제작된 상으로 추정된다. 특히 주먹 쥔 왼손을 오른손으로 감싸 쥔 형태의 지권인(智拳印)의 수인(手印)은 고려후기의 화엄경 변상도에 등장하는 비로자나불의 수인인데, ○○○ 상은 현존하는 조각에서 이 수인이 표현된 이른 예일 뿐만 아니라 조각적으로도 우수한 불상이다.","a":"나주 불회사 건칠비로자나불좌상","c":"보물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619966.jpg"},{"q":"우리나라 최초로 일본 동경미술학교(현, 동경예대)의 공예분야에서 유학한 강창규(姜昌奎, 1906-1977)의 건칠 작품이다. 활짝 핀 나팔꽃 모양의 팔각 고족반(高足盤)에 짙은밤색과 붉은색 칠(漆)을 교대로 사용하여 색채 대비가 강렬하고 표면 광택이 화려하게 살아있으며 세부 표현을 위해 금가루로 무늬를 놓은 시회기법(蒔繪技法)은 근대기 공예품의 일면을 보여준다. 전통적인 형식을 답습하지 않고 과감히 창의적인 조형을 시도한 시대성이 반영된 작품으로 기법의 난이도가 매우 높다고 평가되며 근대기 공예사적으로 예술적 가치가 크다.","a":"건칠반","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667324.jpg"},{"q":"원래 ○○ 북문 밖에 있던 것을 1915년 옛 ○○ 군청 내로 옮겼다가 2006년 심향사 경내 미륵전 앞으로 다시 옮겨 놓은 탑으로, 상 ·하 2기단(基壇) 위에 3층의 탑신(塔身)을 세운 일반적인 모습이다. 기단에는 면마다 기둥 모양의 조각을 두었는데, 아래기단에는 모서리에만 두고, 윗기단에는 모서리와 가운데에 각각 조각을 하였다. 탑신은 몸돌과 지붕돌을 각각 한 돌로 구성하였는데, 위층으로 갈수록 몸돌의 비율이 줄어들어 전체적으로 날렵한 느낌을 준다. 몸돌에는 모서리마다 기둥 모양을 본떠 새겼다.","a":"나주 북망문 밖 삼층석탑","c":"보물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618726.jpg"},{"q":"지증대사의 사리를 모신 탑으로 ○○○ 대웅전 왼쪽에 서 있다. 지증대사(824∼882)는 이 절을 창건한 승려로, 17세에 승려가 되어 헌강왕 7년(881)에 왕사로 임명되었으나 이를 사양하고 ○○○로 돌아와 이듬해인 882년에 입적하였다. 왕은 ‘지증’이라는 시호를 내리고, 탑 이름을‘적조’라 하도록 하였다. 이 탑은 사리를 넣어두는 탑신(塔身)을 중심으로 하여 아래에는 이를 받쳐주는 기단부(基壇部)를 두고, 위로는 머리장식을 얹었다. 기단은 2단으로 이루어졌으며 평면 모양은 8각이다.","a":"문경 봉암사 지증대사탑","c":"보물","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620334.jpg"},{"q":"이 『○○○○○, 4 (妙法蓮華經(諺解) 卷一, 四)』는 대승불교의 대표적인 경전으로 구마라집의 한역본에 계환(戒環)이 주해(註解)하고 일여(一如)가 집주(集註)한 것을 저본으로 세조가 직접 경문에 구결을 달고 윤사로 등이 간경도감에서 번역하여 1463년(세조 9)에 목판으로 간행한 국역불경이다. 한글로 번역하여 正音의 명맥을 이어 발전을 보게 한 귀중한 국역자료인 점과 간경도감에서 간행된 판본의 형태적 특징을 잘 갖추고 있는 것으로 평가되었다.","a":"묘법연화경(언해) 권1, 4","c":"보물","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615931.jpg"},{"q":"조선 후기 제작된 목판본 조선전도이다. 당시 우리나라의 각 지역에 대한 역사적인 기록을 수록하여 고금(古今)을 함께 볼 수 있도록 한 지도이다. 지도의 제작자인 김수홍(金壽弘, 1602-1681)은 병자호란 때 강화성에서 순절한 김상용의 손자이며 호조참판을 지냈고, 현종 7년(1666)에는 「천하고금대총편람도」를 목판으로 간행하였다. 지도 좌측에 쓰여 있는 발문의 말미에 ‘계축맹하(癸丑孟夏)’라는 기록으로 보아 제작연대는 1673년(현종 14)임을 보여준다.","a":"조선팔도고금총람도","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614938.jpg"},{"q":"당나라의 반자밀제(般刺密帝)가 번역하고 송나라의 계환(戒環)이 풀이를 붙인 『○○○○요해(首楞嚴經要解)』를 언해(諺解)한 책이다. 세조(世祖)가 한글로 구결을 달고 혜각존자(慧覺尊者) 신미(信眉)가 구두(句讀)를 달았으며, 한계희(韓繼禧)·김수온(金守溫) 등이 번역하였다. 본서는 1462년(세조 8)에 간경도감[刊經都監: 불경 간행을 위해 1461년(세조 7)에 설치한 기구]에서 을해자본(1461년 간행)의 오류를 교정하여 제작한 목판으로 인쇄한 판본이다.","a":"대불정여래밀인수증요의제보살만행수능엄경(언해)","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613848.jpg"},{"q":"모전석탑이란 돌을 벽돌모양으로 깎아 쌓은 탑으로, 흙벽돌을 쌓아 올린 전탑을 모방하였다 하여 모전탑(模塼塔)이라고도 한다. 탑이 서있던 절터가 논밭으로 변하여 절의 규모는 알 수 없고, 7층에 이르는 거대한 이 탑이 주위를 압도하듯 버티고 서 있다. 회흑색의 점판암을 사용한 탑으로, 탑을 받치는 기단(基壇)만은 점판암이 아닌 자연석으로 1단을 마련하였으며, 그 위로 벽돌로 이루어진 7층의 탑신(塔身)을 올렸다. 탑신은 부처의 사리나 불경 등을 모셔두는 곳으로, 1층의 네 모서리에는 점판암 대신 화강암을 다듬은 기둥을 세워 그 모습이 특이하다.","a":"제천 장락동 칠층모전석탑","c":"보물","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617040.jpg"},{"q":"○○○ 도솔암으로 오르는 길 옆 절벽에 새겨진 ○○○○○으로, 머리 주위를 깊이 파고 머리 부분에서 아래로 내려가면서 점차 두껍게 새기고 있다. 평판적이고 네모진 얼굴은 다소 딱딱하지만 눈꼬리가 치켜 올라간 가느다란 눈과 우뚝 솟은 코, 일자로 도드라지게 나타낸 입술 등으로 얼굴 전체에 파격적인 미소를 띠고 있다. 목에는 3개의 가느다란 주름이 있기는 하지만 상체와 머리가 거의 맞붙어서, 상체 위에 머리를 올려 놓은 것처럼 보인다. 상체는 사각형인데 가슴이 넓고 평판적이어서 양감없는 형태를 보여주고 있다.","a":"고창 선운사 동불암지 마애여래좌상","c":"보물","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618642.jpg"},{"q":"높이가 12m나 되는 큰 암석을 우묵하게 파고, 두 불상을 나란히 배치한 마애불로서 우리나라에서는 드문 예이다. 둥근 얼굴에 가늘고 긴 눈, 넓적한 입 등 얼굴 전반에 미소가 번지고 있어 완강하면서도 한결 자비로운 느낌을 준다. 반듯한 어깨, 평평한 가슴 등 신체의 표현은 몸의 굴곡이 거의 드러나지 않고 형식화되었다. 옷은 양 어깨를 감싸고 있으며 옷주름은 무딘 선으로 형식적으로 표현하였다. 몸에서 나오는 빛을 상징하는 광배(光背)에는 작은 부처가 새겨져 있으나, 세부수법은 닳아서 잘 알 수 없다.","a":"괴산 원풍리 마애이불병좌상","c":"보물","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616994.jpg"},{"q":"성종 15년(1484) ○○○을 세울 때에 지은 것이지만 임진왜란으로 불에 타 광해군 시절 다시 지었다. 회랑 중 남쪽과 북쪽 일부분은 일제시대 때 철거되었던 것을 1986년 복원한 것인데, 2칸 규모로 기둥 윗부분에 새부리 모양으로 뻗어 나온 장식을 하였다. ○○○의 규모는 앞면 3칸·옆면 2칸이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 짜은 구조가 기둥 위뿐만 아니라 기둥 사이에도 있는데 이를 다포 양식이라 한다.","a":"창경궁 명정문 및 행각","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613347.jpg"},{"q":"○○○○○ 전래 초기 ○○를 위해 1918년 건축된 주택으로, ○○○○○의 발상지이자 서구식 ○○, 교육, 생활, 건축 등 근대문명의 유입 통로였던 일산동 언덕 일대에 세워졌던 많은 서구식 건축물 중 유일하게 현존하는 근대문화유산이라는 역사적 의미를 지니고 있다. 적벽돌 외벽에서 반육각형 평면 형태로 돌출된 거실 및 응접실 외벽, 매우 장식적 쌓기에 의해 단형으로 돌출된 층간 코니스, 주출입구 측벽의 원형창을 위한 원형 쌓기, 창호 상부의 평아치 쌓기 등의 건축적 특징을 나타내고 있다.","a":"원주 기독교 의료 선교 사택","c":"국가등록문화유산","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2017121111052401.JPG"},{"q":"이 가옥은 一’자 모양 안채와 ‘ㄱ’자 모양 사랑채, ‘一’자 모양 아래채로 구성된 ○○기 튼 口자형 ○○이다. 안마당을 중심으로 건물이 집약 배치된 배치 형식과 기능적인 평면 구성, 규격화된 재목을 사용한 합리적인 구조 수법, 머름이 없는 키 큰 창호, 서양 창호에 영향을 받은 판문, 수장 공간의 발달 등 ○○기 ○○의 특징을 잘 보여 준다.","a":"포항 오덕리 근대 한옥","c":"국가등록문화유산","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669151.jpg"},{"q":"고려시대에 제작된 높이 31.6㎝의 철회○○병으로 긴 통모양의 병 앞뒤에 한 그루씩의 버드나무를 붉은 흙으로 그려 넣은 소박한 병이다. 전체적으로 선의 변화가 거의 없는 직선이고 단순한 형태를 하고 있는데, 어깨 부분을 적당하게 모깎기를 하고 아가리가 밖으로 벌어진 모양을 하고 있어 단조로움을 덜어주고 있다. 몸통의 양면에 있는 버드나무를 제외하고 특별한 장식이 없으며, 대담하게 단순화시킨 버드나무의 간결한 표현에서 운치있고 세련된 감각이 엿보인다.","a":"청자 철화양류문 통형 병","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611558.jpg"},{"q":"○○○○○는 1931년 육영사업가 최송설당(崔松雪堂, 1855년〜1939년)이 민족정신 함양을 목적으로 설립한 김천지역을 대표하는 사학으로, 개교 초기 건축된 ‘○○’ 건물은 ○○○○○의 상징이며 또한, 한국 근대건축의 선구자인 박길룡(1898〜1943년)의 작품으로 건축사적 측면에서 가치가 높다","a":"김천고등학교 본관","c":"국가등록문화유산","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2020051113165200.jpg"},{"q":"○○ 대릉원의 남쪽 입구에서부터 동쪽으로 황오동 고분군을 둘러싸면서 다시 북쪽으로 북천에 이르는 방어용 시설물인 토루(土壘)이다. ○○시의 개발로 대부분 파손되고 지금은 일부에 흔적만 남아있다. 1936년 조사당시 밑넓이 9.5m, 외벽높이 3.5m, 내벽높이 2m로 확인되었으며, 신라의 고분군 또는 반월성(半月城)과 연관성이 없는 점, <고려사>의 1012년 ○○에 축성했다는 기록과 <동경잡기(東京雜記)>의 고려 현종 때 전라·충청·경상 3도의 군졸을 동원하여 북천의 석축 제방을 쌓았다는 기록, 그리고 현재의 위치·두께 등으로 미루어보아 고려 때 읍성의 수재를 막기…","a":"경주 남고루","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627535.jpg"},{"q":"고달사는 신라 경덕왕 23년(764)에 창건되었으나, 누구에 의해 창건되었는지 확실히 알 수 없다. 이 석불대좌는 불상(佛像)은 없어진 채 대좌만 제 자리를 지키고 있는데, 보존상태가 거의 완벽하다. 받침돌은 위·중간·아래의 3단으로, 각기 다른 돌을 다듬어 구성하였는데, 윗면은 불상이 놓여져 있던 곳으로 잘 다듬어져 있다. 아래받침돌과 윗받침돌에는 연꽃잎을 서로 대칭되게 돌려 새겼다. 이 대좌가 사각형으로 거대한 규모이면서도 유연한 느낌을 주는 것은 율동적이면서 팽창감이 느껴지는 연꽃잎의 묘사 때문이다.","a":"여주 고달사지 석조대좌","c":"보물","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615611.jpg"},{"q":"동학농민운동의 지도자인 ○○○이 살던 집이다. 몰락한 양반 가문에서 태어난 ○○○은 조선 고종 27년(1890)에 동학에 몸을 담아, 동학 제2대 교주인 최시형으로부터 고부지방의 동학접주로 임명되었다. 그는 관리들의 횡포에 맞서 농민과 동학교도들을 조직해 동학 운동을 주도하였다. 이 옛집은 조선 고종 15년(1878)에 세워졌다. 앞면 4칸·옆면 1칸의 초가집으로 안채가 구성된 남향집이다. 동쪽부터 부엌·큰방·웃방·끝방 순서의 일(一)자 형태로 구성되어 있는데, 이는 우리나라 남부지역 민가 구조와는 다른 방향으로 되어 있는 특징을 보여준다.","a":"정읍 전봉준 유적","c":"사적","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626872.jpg"},{"q":"○○○○○은 구마라집(鳩摩羅什)이 한역한 ○○○○○을 저본으로 1422년(세종 4)에 비구 덕명(比丘 德名)이 어머니의 극락왕생을 위해 발원하여 감지에 은니로 쓴 7첩 중 ‘○○’과 ‘권7’의 2첩에 해당된다. 표지에는 보상화문(寶相華紋) 네 송이가 장식되어 있으며, 화문(花紋)은 금니로, 화경(花莖)은 주로 은니로 그려져 있다. 권수(卷首)에는 금니로 변상도를 그리고 변상도 다음에 권두 서명과 구마라집의 역자(譯者) 표시가 보인다. 서체는 사경체(寫經體)의 특징인 조맹부체(趙孟頫體)로 썼다.","a":"감지은니 묘법연화경 권3","c":"보물","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615062.jpg"},{"q":"○○○○ <○○○○>는 중국 송대(宋代) 구양수(歐陽修, 1007∼1072)가 지은 ‘추성부(秋聲賦)’를 단원 ○○○가 그림으로 그려낸 시의도(詩意圖)이다. 화면의 왼쪽에는 백문타원인(白文楕圓印)으로 기우유자(騎牛游子)라 찍혀 있으며 추성부 전문이 ○○○의 자필로 쓰여져 있는데, 끝 부분에 ‘을축년동지후삼일(乙丑年冬至後三日) 단구사(丹邱寫)’라 하였으므로 이 그림은 1805년 즉, 단원의 나이 61세에 제작된 것임을 알 수 있다. 그런데 이 해는 단원이 죽기 바로 전 해로 추정되므로 그의 마지막 기년작이자 죽음을 앞두고 그린 작품으로 믿어진다.","a":"김홍도 필 추성부도","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614794.jpg"},{"q":"1937년 건립 이 ○○는 한센병 환자들의 강제 노동으로 지어졌다. 지금은 사용되지 않는 무인 ○○이지만 건립 당시는 녹동항으로 가는 배들의 길잡이 노릇을 한 시설물로, 일제에 의한 인권 유린의 현장을 보여준다.","a":"고흥 구 소록도갱생원 등대","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668885.jpg"},{"q":"1930년 황해도 곡산군 화촌면 봉산리에서 출토되어 현재는 리움미술관에 전시되어 있는 불상으로 높이 15.5㎝이다. 하나의 커다란 광배(光背)에 본존불과 좌우보살상을 조각한 형태의 ○○○로 현존하는 같은 형식의 불상 중에서 가장 크다. 좌우의 보살상은 본존불보다 훨씬 작게 만들어 광배의 끝에 겨우 매달린 듯 보이는데, 이는 본존불을 한결 돋보이게 하는 효과를 내고 있다. 본존불의 가슴과 광배의 오른쪽 끝에 약간의 흠집이 있을 뿐, 전체적으로 보존 상태가 좋은 편이다. 본존불은 얼굴이 풍만하고 입가에 미소를 띠고 있으며, 머리에는 상투 모양의 머리(육계)가 큼직하다.","a":"금동신묘명삼존불입상","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611493.jpg"},{"q":"○○○○○는 신라 문무왕 8년(668) 의상대사(義湘大師)가 창건하였다고 전하지만, 정확한 근거자료는 없다. 『여지도서』에 따르면 “○○○는 관아의 남쪽 5리에 있으며 심홍부(沈弘孚)의 무덤을 수호하는 사찰”이라 하여 ○○심씨의 원당사찰임을 밝히고 있다. 따라서, 그 이전의 기록은 알 수 없으나 15세기 심홍부의 수호사찰로 ○○○가 지어진 것은 확인할 수 있으며 ○○○과 만세루, 추모재가 일곽을 이루는 건물임을 알 수 있다. ○○○은 근래에 수리 공사에서 발견된 상량문에 따르면 萬曆43年(1615)에 건립된 것으로 추정하고 있다.","a":"청송 보광사 극락전","c":"보물","nc":"","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2338526.jpg"},{"q":"지석묘란 선사시대 무덤형식의 하나로 고인돌이라고 부르기도 한다. ○○ 아산면 ○○○ 매산마을을 중심으로 약 1.8㎞에 이르는 야산 기슭에 440여 기의 고인돌이 무리를 지어있다. 기원전 400년∼500년 무렵 청동기시대 사람들의 집단무덤으로, 이 지역을 지배했던 족장들의 가족무덤인 듯 하다. 당시에 살았던 사람들은 낮은 야산과 농사 짓기 좋은 이 지역에 터를 잡았던 것으로 보인다. 바둑판 모양의 남방식, 탁자 모양의 북방식, 천장돌만 있는 개석식 등 우리나라에서 볼 수 있는 고인돌의 각종 형식을 갖추고 있어 고인돌의 발생과 성격을 아는데 매우 중요하다.","a":"고창 죽림리 지석묘군","c":"사적","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626943.jpg"},{"q":"세조 10년(1464) 세조의 왕사인 혜각존자 신미 등이 학열, 학조 등과 함께 임금의 만수무강을 빌고자 ○○○를 새롭게 단장하면서 지은 글로, 이 사실을 전해들은 세조가 쌀, 무명, 베와 철 등을 보내면서 쓴 글과 함께 월정사에 소장되어 전한다. 각각 한문 원문과 번역으로 되어 있는데, 신미 등이 쓴 글에는 신미, 학열, 학조 등의 수결(지금은 서명)이 있으며, 세조가 보낸 글에는 세조와 세자빈, 왕세자의 수결과 도장이 찍혀 있다. 한글로 번역된 것은 가장 오래된 필사본으로 유명하다.","a":"평창 상원사 중창권선문","c":"국보","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612135.jpg"},{"q":"강원특별자치도 춘천에서 출토된 것으로 전해지는 이 보살상은 하나의 광배(光背)에 삼존상을 배치한 형식이며, 불신(佛身), 광배, 대좌(臺座)가 함께 붙어 있는 독특한 작품이다. 본존인 보살은 머리에 관(冠)을 쓰고 있으며 얼굴은 둥근 편이다. 가슴에는 대각선으로 내의를 얇게 걸쳐 입었고, 두껍게 걸쳐 입은 겉옷은 보살상의 앞면에서 'X'자로 교차되었다가 새의 날개깃처럼 좌우로 퍼지고 있다. 치마는 발목까지 길게 늘어졌으며, 약간의 주름을 선으로 표현하였다.","a":"금동보살삼존입상","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611581.jpg"},{"q":"이 ○○○○○는 고려시대 ○○상감○○주자를 대표하는 작품으로 기형, 상감의 문양 및 유색 등 전반적 조형요소들이 빼어난 수준을 보여준다. 상감문양은 구조적으로 짜임새가 있으며 솜씨도 완성도가 높다. ○○토와 백토, 흑토의 성질이 잘 조화되어 상감한 부분이 편평하고 일정하며 발색도 밝고 우수한 편이다. 유층은 다소 두꺼운 편이나 맑고 투명하며 광택도 좋고 전체에 일정하게 씌워져 있다.","a":"청자 상감운학국화문 병형 주전자","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614851.jpg"},{"q":"조선시대 ○○○○○로 높이 41.3㎝, 입지름 19㎝, 밑지름 21.5㎝의 크기이다. 아가리 가장자리가 밖으로 말렸고, 목 부위의 경사면부터 풍만하게 벌어졌다가 서서히 좁아진 둥근 몸체의 ○○○이다. 농담(濃淡)이 들어간 검은 안료로 목과 어깨 부분에 구름무늬와 꽃잎무늬를 돌렸고 아랫부분에는 연속된 파도무늬를 장식했다. 몸체의 한 면에는 대나무를, 다른 한 면에는 매화등걸을 각각 그려 넣었다. 유약은 푸르름이 감도는 유백색으로, 전면에 고르게 발라져 은은한 광택이 난다. 이러한 ○○○의 형태는 16세기 분청사기에서 보이며, 특히 중국 명대의 ○○○와 비슷하다.","a":"백자 철화매죽문 항아리","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611616.jpg"},{"q":"○○ 낭산(狼山) 기슭에 있는 신라의 절터로 신문왕릉 옆 ·선덕여왕릉 아래에 있다. 신라 문무왕 14년(674)에 중국 당나라는 신라가 그들의 도독부(계림도독부)를 공격한다는 핑계로 50만 대군을 일으켜 신라를 공격하려 하였다. 이에 문무왕이 명랑법사에게 적을 막을 계책을 구하자, 이곳 신유림에 ○○○○를 짓고 부처의 힘을 빌리도록 하였다. 그러나 당의 침략으로 절을 완성시킬 시간이 없게 되자, 비단과 풀로 절의 모습을 갖춘 뒤 명승 12인과 더불어 밀교의 비법인 문두루비법을 썼다. 그러자 전투가 시작되기도 전에 풍랑이 크게 일어 당나라 배가 모두 가라앉았다.","a":"경주 사천왕사지","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627521.jpg"},{"q":"오랫동안 파묻혀 있었는데, 최근에 바닥을 파고 흩어진 부분을 정리하여 다시 세웠다. 높이 3.5m로, 아래받침돌에는 엎어놓은 연꽃 모양이 새겨졌고, 사잇기둥은 장고모양이며, 윗받침돌에는 솟은 연꽃모양을 새겼다. 불을 밝히는 곳인 화사석(火舍石)은 8각이며 창이 8면에 뚫렸다. 지붕돌은 아랫면에 낮고 널찍한 괴임이 있고, 8각의 끝부분에는 꽃모양을 둥글게 조각하였다.","a":"담양 개선사지 석등","c":"보물","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618748.jpg"},{"q":"○○○○○의 낮은 야산 기슭에 있는 이 석불은 전형적인 통일신라시대 불상 양식을 따르고 있다. 입불상으로 자연석을 적당히 다듬어 윗면에 두 발을 새겨 놓은 1매의 대석과, 대석에 꽂아 세울 수 있도록 한 돌에 광배를 함께 조성한 불신 등 두 개의 돌로 구성되었다. 신체에 비하여 다소 머리부분이 큰데 얼굴이 부분적으로 손상되었지만 전체적으로 후덕한 느낌을 준다.","a":"거창 농산리 석조여래입상","c":"보물","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622982.jpg"},{"q":"1933년 건립 이 건물은 풍양지소 금융조합으로 건립되었다. ○○군 내 풍양면과 도화면에서 활발한 영업 활동을 하였으며, 현재까지도 건물의 기능을 충실히 하고 있을 만큼 튼튼한 구조를 갖추고 있고, 해풍에 직접 노출되는 해안가에 있으면서도 긴 세월 동안 잘 유지되고 있다. 건물 내부에 남아 있는 금고는 당시 지방에서는 보기 드물게 일본에서 직수입된 것이라고 한다.","a":"고흥 구 풍양금융조합","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668051.jpg"},{"q":"원래 두촌면 ○○○에 있던 탑으로, 현재의 자리인 ○○군의회 앞으로 옮겨 세웠다. 탑이 서 있던 원래의 위치는 일대가 절터였을 것이나, 지금은 밭으로 변하고 주변에는 기와조각들만이 흩어져 있다. 탑은 2단의 기단(基壇)위에 3층의 탑신(塔身)을 올린 형태로, 4마리의 돌사자가 있어 4사자탑(四獅子塔)이라 부르고 있다. 아래층 기단의 각 면에는 안상(眼象)이 조각되어 있는데, 그 안에 꽃무늬조각이 장식되어 있어, 고려시대의 특징이 잘 담겨져 있다. 위층 기단에는 각 모서리에 돌사자 1마리씩을 두어 넓적한 윗돌을 받치게 하였는데, 이 탑의 가장 두드러진 특징이다.","a":"홍천 괘석리 사사자 삼층석탑","c":"보물","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616676.jpg"},{"q":"조선 22대 정조의 후궁이자 23대 순조의 생모(사친) 유비 박씨(1770~1822)의 원이다. 유비는 박준원의 딸로 1787년(정조 11) 유빈(綏嬪)으로 책봉되었고, 정조 사이에서 순조와 순선옹주를 낳았다. 아들 순조가 왕위에 오르자 왕의 생모로서 예우를 받으며 지냈다. 이후 대한제국 선포 후 1901년(광무 5) 황제(정조선황제)의 후궁이자 황제(순조숙황제)의 사친이므로 특별히 추봉해야한다는 논의로 유비로 추봉되었다. ○○○은 처음 현 서울 동대문구 휘경동에 조성되었다가 1855년(철종 6) 현 순강원 근처로 옮겼다.","a":"남양주 휘경원","c":"사적","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2020081316454900.jpg"},{"q":"1910년대 건립 이 건물은 미국 남장로교 선교사 자녀의 성경 학교로 건립되었다. 회색 벽돌을 쌓아 만든 건물로 당시 주변에 석조로 건립된 선교사 사택들과 대조된다. 집회 시설다운 정면부와 정교한 벽돌쌓기 기법 등에서 조형적 가치를 찾을 수 있으며, 미국 남장로교가 전남 해안 지역 선교를 위한 거점으로 건립한 선교 시설이라는 점에서 역사·문화적 보존 가치가 있다.","a":"구 순천선교부 외국인 어린이학교","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668922.jpg"},{"q":"북한산성과 함께 수도 한양을 지키던 조선시대의 산성이다. 신라 문무왕 13년(673)에 한산주에 주장성晝長城(일명 일장성日長城)을 쌓았다는 기록이 있는데, 현재의 ○○○○으로 보인다. 고려시대의 기록은 없으나 조선『세종실록지리지』에 일장산성이라 기록되어 있다. ○○○○이 현재의 모습으로 갖춘 것은 후금의 위협이 고조되고 이괄의 난을 겪고 난 인조 2년(1624)이다. 인조 14년(1636) 병자호란 때 왕이 이곳으로 피신하였는데, 강화가 함락되고 양식이 부족하여 인조는 세자와 함께 성문을 열고 삼전도에서 치욕적인 항복을 하였다.","a":"남한산성","c":"사적","nc":"","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625416.jpg"},{"q":"○○시 ○○○에 있는 신라시대 절터를 가리킨다. 이 유적은 보문부락의 앞들판에 있으며 멀리 서쪽에는 ○○ 낭산 일원(사적), 북쪽에는 명활성(사적)이 있다. 세워진 시기는 알 수 없으나 신라 경문왕 11년(871) 이전에 세워진 것으로 짐작하고 있다. 절터의 대부분은 넓은 논으로 이용하고 있으나, 발견되는 석재들로 미루어 당시에는 많은 건물들이 있었을 것으로 생각된다. 일제강점기에 ‘보문사(普門寺)’라 새긴 기와가 발견되어 절 이름을 확인할 수 있었다. 서쪽에 있는 당간지주(보물)와 석조(보물)를 비롯해 당시 탑 따위의 석물들이 남아 있다.","a":"경주 보문동 사지","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627965.jpg"},{"q":"○○○○○은 화성 축조(1793～1796)를 주도 했던 정조(1752～1800)가 승하한 뒤 어진을 모실 영전 건축으로 1801년 건립되었으며, 전주의 경기전과 함께 궁궐 밖에 남아있는 드문 사례로 정조 이후의 모든 왕들이 직접 방문하여 제향을 하였다는 점에서 그 위상이 더욱 높다고 할 수 있다. ○○○, ○○○, ○○○은 ○○○의 중심 건축군으로 정전인 ○○○과 직각으로 ○○○이 배치되고 ○○○으로 연결된 ㄷ자형 구성으로, 조선초기 정자각 정전에 ○○○이 별도로 있는 영전과는 달리 조선후기 변화된 새로운 형식의 영전 공간구성을 보여주고 있다.","a":"수원 화령전 운한각·복도각·이안청","c":"보물","nc":"","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2019082909263600.JPG"},{"q":"태릉은 조선 제11대 중종(재위 1506∼1544)의 세번째 왕비인 문정왕후 윤씨(1501∼1565)의 무덤이다. 본관은 파평으로 중종의 두번째 왕비인 장경왕후가 1515년 죽자 1517년에 17세의 나이로 왕비가 되었다. 중종이 있는 정릉에 묻히려 하였으나 장마철 침수로 인하여 이곳에 묻히게 되었다. 무덤은 십이지신과 구름무늬가 새겨진 12면으로 된 병풍석이 둘러져 있다. 무덤 앞에는 상석·망주석 등이 『국조오례의』에 따라 제작되었다. 무덤 아래에는 한국 전쟁시 훼손되었다가 1995년 다시 지은 정자각이 있다.","a":"서울 태릉과 강릉","c":"사적","nc":"","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624696.jpg"},{"q":"보천사는 수암사(水巖寺)라고도 전해지고 있으며, 통일신라시대 경덕왕 때 창건되었던 사찰이다. ○○은 절터의 북쪽 산기슭 계곡에 세워져 있고, 위아래 모두 8각형의 기본형을 충실히 따르고 있다. 정사각형의 바닥돌 위로 기단의 아래받침돌·가운데받침돌·윗받침돌을 올렸다. 아래받침돌은 2단으로 이루어져 있고 그 사이에 돌띠를 돌려 구분하였으며, 윗단에는 용과 구름무늬를 얕게 돋을새김하였다. 가운데받침돌도 8각으로 모서리마다 기둥 모양을 새긴 후, 면에 타원형의 조각을 두었다. 윗받침돌에는 2겹으로 16장의 연꽃잎을 조각하였다.","a":"의령 보천사지 승탑","c":"보물","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622679.jpg"},{"q":"「○○○○○」는 누각형태의 정면 11칸, 측면 1칸의 장대한 규모를 가지며, 유식을 위한 누와 향교 출입을 위한 외문의 역할을 겸하는 문루로서, 현존하는 조선시대 향교 문루 중에서 규모가 가장 큼. 특히 경사지라는 입지여건의 특징을 잘 살려 외부에서 향교 내부가 들여다보이지 않도록 향교 전면을 효과적으로 가리면서도 측면 규모를 1칸으로 하여 내부의 명륜당에서 볼 때 위압적이고 답답해 보이지 않도록 적절한 높이와 규모를 가진 건물로 평가됨.","a":"안성향교 풍화루","c":"보물","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2020122909265600.JPG"},{"q":"○○○○○는 부모가 죽은 뒤 유산을 율곡 ○○의 형제자매들이 모여 합의하여 나누면서 작성한 것이다. 내용을 살펴보면, 각종 제사와 수묘를 위한 토지와 노비를 배정하고, 나머지를 4남3녀와 서모(庶母:아버지의 첩)인 권씨에 배당한 토지와 노비 등을 구체적으로 적은 다음, 끝에 문서작성에 참여한 사람들의 이름과 수결(지금의 서명)을 표시하였다. 이 문서는 ○○의 개인사에 관한 사항뿐만 아니라 조선 전기 재산상속에 대해 알 수 있는 좋은 자료로 평가된다.","a":"이이 남매 화회문기","c":"보물","nc":"","r":"서울특별시","s":"광진구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613394.jpg"},{"q":"○○○는 ○○○과 창경궁 경계에 위치하고 있다.맨 좌측에 ○○○가 크게 자리 잡고 그 우측으로 석복헌과 수강재가 연이어져 있으며, 이들 뒤편에는 화초·석물·꽃담 굴뚝 등으로 가꾸어진 아름다운 화계와 그 위의 꽃담 너머로는 상량정·한정당·취운정이 위치해 있다. 원래 왕의 연침공간 조성을 목적으로 ○○○가 지어지고 이듬해에 빈의 처소를 위하여 석복헌을 짓고 수강재를 중수하여 오늘에 이르고 있다. 궁궐 안에 사대부주택형식으로 지은 건물로는 ○○○와 연경당뿐이다.","a":"창덕궁 낙선재","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615028.jpg"},{"q":"○○○○○는 1979년 파계사 원통전(圓通殿)의 관세음보살상을 금칠하다가 발견되었다. ○○와 함께 발견된 한자 두루마리에 적힌 발원문에 의하면, 영조 16년(건륭 5,1740) 9월 파계사 대법당을 수리하고 영조가 탱화 일천불을 희사하면서 이 곳을 왕실을 위해 기도하는 도량으로 삼고 영조의 청사상의(靑紗上衣)를 복장하여 만세유전을 빈다고 기록하고 있다. ○○는 조선시대에 왕을 비롯하여 사대부의 외출복으로 입혀졌던 옷으로 기록이나 유물은 16세기부터 보이기 시작한다. 형태는 곧은 깃에 넓은 소매(廣袖)가 달린 것으로 뒷자락이 2중구조로 된 특징이 있다.","a":"영조대왕의 도포","c":"국가민속문화유산","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633538.jpg"},{"q":"○○○는 동해안에 있는 통일신라시대의 사찰로 지금은 3층석탑 2기와 금당 및 강당 등 건물터만 남아있다. 신라 문무왕은 삼국을 통일한 후 부처의 힘을 빌어 왜구의 침입을 막고자 이곳에 절을 세웠다. 절이 다 지어지기 전에 왕이 죽자, 그 뜻을 이어받아 아들인 신문왕이 682년에 완성하였다. 문무왕은 “내가 죽으면 바다의 용이 되어 나라를 지키고자 하니 화장하여 동해에 장사지낼 것”을 유언하였는데, 그 뜻을 받들어 장사한 곳이 절 부근의 대왕암이며, 그 은혜에 감사한다는 뜻으로 절 이름을 ○○○라 하였다고 전한다.","a":"경주 감은사지","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627602.jpg"},{"q":"○○○○○는 해시계의 일종으로 검은 대리석으로 만들었으며 크기는 가로 58.9㎝, 세로 38.2㎝, 두께 16.3㎝이다. 원리는 그래프 용지에 1㎝ 간격으로 동심원과 10°간격의 방사선을 그어놓고, 그 중심에 막대를 세워 시각에 따른 그림자의 변화를 보는 형태로, 이것은 반구형을 한 해시계 앙부일구를 전개하여 평면에 옮겨 놓은 것과 똑같은 모양이다. 측면에 새겨져 있는 글을 통해 18세기 초에 제작된 것이고 구조와 평면에 그려진 시각선, 절기를 나타낸 선이 중국의 것과 같아 그것을 본 떠 관상감(觀象監)에서 새로 만든 것으로 추정된다.","a":"신법 지평일구(1985-2)","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614066.jpg"},{"q":"○○○○은 천(天)·지(地)·현(玄)·황(黃) 총통 중에서 천자총통 다음으로 큰 우리나라 고유의 대포이다. 길이 89㎝, 총구의 안지름 10.5㎝, 바깥지름 17.2㎝로 조선 명종 12년(1557)에 만들었다. 모양은 손잡이 2개가 원형 그대로 붙어 있으며, 마디가 모두 10개이고 일곱번째 마디와 여덟번째 마디가 서로 붙어 있어 화약을 넣는 약통과 격목통을 구분하고 있다. 격목통은 원기둥 모양의 나무를 박아 약통 속에 넣은 화약의 폭발력을 최대한 강하게 만드는 역할을 한다. 약통 속의 구멍은 2개이고 발사물은 화살이나 탄환을 넣어 사용한다.","a":"지자총통(1986-2)","c":"보물","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615103.jpg"},{"q":"신라 56대 마지막왕인 ○○○의 무덤이다. 927년 경애왕이 포석정에서 놀다 견훤의 습격을 받아 시해된 후 견훤에 의해 왕위에 올랐다. 전쟁으로 인해 백성이 많은 피해를 입자 군신의 반대를 무릅쓰고, 935년 평화적으로 신라를 고려에 넘겨주고 왕위를 물러난 신라 마지막 왕이다. 무덤의 높이는 약 3m, 지름 7m의 둥글게 흙을 쌓아올린 원형 봉토무덤으로 판석을 이용해 둘레돌을 돌렸다. 고려시대 왕릉에서 나타나기 시작한 담장인 곡장이 둘려져 있어 고려 왕실에서 왕의 예로서 무덤을 만들었음을 알 수 있다. 신라 왕릉 중 유일하게 경주 지역을 벗어나 경기도에 있다.","a":"연천 경순왕릉","c":"사적","nc":"","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625761.jpg"},{"q":"○○상감이란 흙으로 그릇을 빚어 반쯤 말린 뒤, 그릇 표면에 무늬나 그림을 새기고 그 자리를 백토나 자토로 메운 뒤, 유약을 발라 구워서 투명한 ○○ 유약을 통해 흰색 또는 검은색 무늬가 보이도록 한 것으로 12세기 전반에 발생하여 12세기 중엽에 전성기를 이루었다. ○○○○○은 화장품을 넣어 두었던 것으로 추정되는 그릇으로 바깥쪽의 큰 그릇인 모합(母盒)과 그 안에 들어가는 작은 그릇인 자합(子盒) 5개로 이루어져 있다.","a":"청자 상감국화모란당초문 모자합","c":"보물","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613270.jpg"},{"q":"문묘란 유교를 집대성한 공자나 여러 성현들의 위패를 모시고 제사를 드리는 사당을 말한다. 문묘는 크게 제사를 위한 건물들이 있는 대성전 구역과 학문을 갈고 닦는 건물들이 있는 명륜당 구역으로 나누어진다. 조선 태조 7년(1398)에 처음 세웠으나 정종 2년(1400)에 불에 타 없어졌고, 태종 7년(1407)에 다시 지은 것도 임진왜란 때 타버렸다. 지금 있는 건물은 임진왜란 후에 다시 지은 것이다. 대성전과 명륜당은 담장을 사이에 두고 남북으로 분리되어 있다. 대성전 서우(보물) 북쪽에는 제사 때 쓰는 도구를 보관하는 제기고와 잡다한 것을 두는 잡사가 있다.","a":"서울 문묘와 성균관","c":"사적","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624573.jpg"},{"q":"1930~40년대 건립 이곳은 1930~40년대에 국장급 이상의 고위 관료들을 위해 조성된 ○○촌으로 일제 강점기 ○○ 건축의 전형을 볼 수 있다. 이들 ○○는 형태·재료·배치가 균일하며 주위의 경관과도 조화를 잘 이루고 있다. 지금은 한국전쟁 당시 이승만 대통령이 머물렀던 충남 도지사 공관을 비롯하여 4동의 ○○와 3동의 창고가 남아 있어, ○○의 기능을 현재까지 그대로 유지하고 있다.","a":"대전 충청남도청 구 관사 1·2·5·6호와 부속창고","c":"국가등록문화유산","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667959.jpg"},{"q":"○○○○○은 줄여서 ‘금강경’이라고 부르기도 하는데, 조계종의 근본경전으로 우리나라에서는 반야심경 다음으로 많이 읽히는 불교경전이다. 이 책은 후진(後秦)의 구마라습(鳩摩羅什)이 번역한 것에 명나라의 천노(川老)가 풀이를 덧붙인 것이다. 닥종이에 찍은 목판본으로 처음에 두루마리 형식으로 만들었던 것을 다시 책의 형태로 고쳐 만들었으며, 크기는 세로 56㎝, 가로 19.1㎝이다. 책머리에 있는 글에 의하면 유향과 강인부가 우왕의 왕비에게 도움을 받아 책을 간행했음을 알 수 있다.","a":"금강반야바라밀경","c":"보물","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613762.jpg"},{"q":"고려 ○○의 전성기인 12세기경에 만들어진 ○○○○로, 높이 21.2㎝, 지름 16.3㎝이다. 향을 피우는 부분인 몸체와 사자 모양의 뚜껑으로 구성되어 있다. 몸체는 3개의 짐승모양을 한 다리가 떠받치고 있는데, 전면에 구름무늬가 가늘게 새겨져 있다. 몸체 윗면 가장자리에도 세 곳에 구름무늬를 배치하였다. 뚜껑은 대좌에 앉아있는 사자의 형상이며, 대좌에는 꽃무늬를 시문하였다. 사자의 자세는 뚜껑의 왼쪽에 치우쳐 있어 시각적인 변화에서 오는 조형효과를 노린 것으로 해석된다.","a":"청자 사자형뚜껑 향로","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611463.jpg"},{"q":"1936년 무렵 건립 이 건물은 일제 강점기 당시 쌀 수탈을 목적으로 이 지역에 만들어졌던 일본인 농장에 소속된 주택으로 전해지고 있다. 전형적인 일식 목구조 기법에 지붕부에서 한식 기법이 일부 사용된 절충적인 형태로, 일식 ○○이 국내에 도입되어 지역적 영향을 받아 변화된 모습을 보여주고 있다.","a":"김제 종신리 한·일 절충식 가옥","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668783.jpg"},{"q":"말을 타고 있는 사람의 모습을 한 높이 23.2㎝, 폭 14.7㎝, 밑 지름 9.2㎝의 인물형 토기로 삼국시대에 만들어진 것으로 추정된다. 나팔모양의 받침 위에 직사각형의 편평한 판을 설치하고, 그 위에 말을 탄 무사가 올려져 있다. 받침은 가야의 굽다리 접시(고배)와 동일한 형태로, 두 줄로 구멍이 뚫려 있다. 받침의 네 모서리에는 손으로 빚어 깎아낸 말 다리가 있다. 말 몸에는 갑옷을 매우 사실적으로 묘사하였고, 말갈기는 직선으로 다듬어져 있다. 말 등에는 갑옷을 입고 무기를 잡고 있는 무사가 앉아있다.","a":"도기 기마인물형 뿔잔","c":"국보","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612923.jpg"},{"q":"­왕실이 후원한 미술교육기관인 서화미술원에서 교육받은 대표적 신진 화가인 오일영과 이용우에 의해 1920년경 제작되어 ○○○에 부착된 벽화. 채색 화조화의 전통을 계승하고 있으며, 형상의 표현과 기술묘사에 충실한 그림","a":"창덕궁 대조전 봉황도","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667054.jpg"},{"q":"이 책은 조선 중기의 문신인 서애 유성룡(1542∼1607)이 임진왜란 때의 상황을 기록한 것이다. 징비란 미리 징계하여 후환을 경계한다는 뜻이다. 유성룡은 퇴계 이황의 문인이며, 김성일과 동문수학하였다. 명종 21년(1566) 문과에 급제하여 승문원권예문관검열, 공조좌랑, 이조좌랑 등의 벼슬을 거쳐 삼정승을 모두 지냈다. 왜적이 쳐들어올 것을 알고 장군인 권율과 이순신을 중용하도록 추천하였고, 화포 등 각종 무기의 제조, 성곽을 세울 것을 건의하고 군비확충에 노력하였다.","a":"징비록","c":"국보","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612856.jpg"},{"q":"극락보전 후불벽 앞면에 그려져 있는 아미타삼존불벽화이다. 앉은 모습의 아미타불을 중심으로 왼쪽에 관음보살이, 오른쪽에는 지장보살이 서 있는 구도를 하고 있다. 화면의 맨 위부분에는 구름을 배경으로 좌우에 각각 3인씩 6인의 나한상을 배치하고 그 위에는 작은 화불이 2구씩이 그려져 있다. 아미타극락회도 장면을 그린 이 벽화는 앞에 모셔진 아미타삼존불상과 매우 비슷한 모습을 하고 있다. 중앙의 본존불은 비교적 높은 연꽃대좌 위에 결가부좌한 모습으로 양어깨를 모두 감싼 옷을 입고 있으며 뒤로는 키모양의 광배가 표현되었다.","a":"강진 무위사 극락전 아미타여래삼존벽화","c":"국보","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612602.jpg"},{"q":"이 ○○은 옮겨 세워진 것으로 밝혀졌으며, 불을 밝히는 화사석(火舍石)을 중심으로 아래에는 높은 받침을 두고 그 위로는 지붕돌과 상륜부를 올렸다. 아래받침돌 옆면에는 안상(眼象)을 크게 새기고, 위에는 커다란 연화문과 구름문을 장식하여 신성한 느낌을 주고 있다. 가운데 기둥은 장고 모양으로 기교 있게 마련하였다. 윗받침돌은 연꽃을 화려하게 표현하여 장엄함이 연출되도록 했고, 그 위에 있는 화사석(火舍石)은 각 면에 창을 내어 부처의 진리를 상징하는 불빛이 멀리 퍼져나가도록 하였다.","a":"임실 진구사지 석등","c":"보물","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618255.jpg"},{"q":"이왕직미술품제작소에서 제작한 탕기(湯器)로 표면을 망치로 두드린 단조(鍛造)기법으로 제작하였다. 덮개와 몸체 중앙에 대한제국 황실의 문장인 오얏꽃(李花)을 음각으로 새겼고 덮개에 ‘萬壽無疆’ 문자를 양각으로 감입(嵌入)하고 연봉형 꼭지를 달아 전통을 잇고자 하는 여망에 실용성을 가미한 멋을 볼 수 있다. 이 작품은 이왕직미술품제작소의 설립취지가 유지된 1910년대 제작품으로 추정되는데 창덕궁 유물을 인수한 소장처의 특성과 기형으로 보아 황실 연회에 사용된 것으로 보이며 사용한 흔적이 온전하게 남아있어 공예사적 가치가 크다.","a":"은제이화문탕기","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667326.jpg"},{"q":"황매산의 남쪽 기슭에 있는 절터이다. 처음 지어진 연대는 정확히 모르나, 고려 현종 5년(1014)에 적연선사가 이 곳에서 83세에 입적했다는 기록이 있어, 그 이전에 세워진 것으로 추정된다. 또한 국립중앙박물관에 있는 홍각선사비의 조각 중에도 ‘○○○’라는 절의 이름이 보이는데, 홍각선사비가 886년에 세워졌다는 점에서 ○○○의 연대를 짐작할 수 있다. 발굴을 통해 조사해본 결과, 불상을 모셨던 금당·서금당·회랑터·기타 건물터가 확인되어 당시 절의 규모를 알 수 있고, 금당은 3차례에 걸쳐 다시 지어진 것으로 밝혀졌다.","a":"합천 영암사지","c":"사적","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628245.jpg"},{"q":"해발 232m의 ○○봉 정상일대를 돌로 쌓은 성으로 서낭산에 있어 서낭○○이라고도 불리운다. 대부분 무너졌으나 둘레 2.6㎞, 높이 1m 정도가 남아있다. 『삼국사기』에 의하면 신라가 낙동강을 통해 침입하는 왜구를 막기 위해 ○○에 성을 쌓았다는 기록이 있다. 이러한 기록과 성 안에서 신라 토기조각이 발견되는 점으로 보아 신라시대에 축성된 것으로 보고있다. 성의 남쪽에는 이 ○○과 규모가 비슷한 북부동○○이 있어 쌍성의 형태를 이룬다. 서낭산에는 ○○ 부부총으로 유명한 6세기경의 ○○○ 무덤들이 흩어져 있어 이 일대가 신라시대의 중요한 곳으로 여겨진다.","a":"양산 신기리 산성","c":"사적","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628202.jpg"},{"q":"해저리마을의 오른쪽 깊숙한 곳에 우거진 뒷동산을 배경으로 남향하여 있는 집으로 조선 후기의 문신 김건수가 살던 집이다. 김건수는 순조 30년(1830)에 과거에 급제한 이후 현감, 부사를 거쳐 우부승지를 지냈다. 사랑채인 명월루는 그가 지었으며 철종 1년(1850)에 수리한 바 있다. 안채는 김건수의 6대조가 이 마을에 처음 들어와서 이곳에 살던 여씨에게 샀다고 전한다. 'ㄷ'자형의 안채와 'T'자형의 사랑채가 있고, 중문채가 있었으나 현재는 없다. 안채는 남향한 중앙에 대청이 있고, 대청 양쪽에 안방과 상방이 대칭적으로 배치되어 있다.","a":"봉화 만회고택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635244.jpg"},{"q":"우리나라에서는 최초로 임금이 이름을 지어 내린 사액서원이자 사학(私學)기관이다. 조선 중종 37년(1542)에 풍기군수 주세붕(周世鵬)이 안향(安珦)을 제사하기 위해 사당을 세웠다가, 중종 38년(1543)에 유생들을 교육하면서 백운동서원이라 하였다. 명종 5년(1550)에는 풍기군수 이황의 요청에 의해 ‘○○○○’이라 사액을 받고 나라의 공인과 지원을 받게 되었다. 중종 39년(1544)에 안축(安軸)과 안보(安輔)를 제사지냈고, 인조 11년(1633)에는 주세붕을 더하여 제사지냈다.","a":"영주 소수서원","c":"사적","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627668.jpg"},{"q":"평산신씨 27세손 신한창(申漢昌;1669~1749)이 종택에서 분가하면서 건립(1739년)하였다고 하며 당시 5칸규모였으나 31세손인 치구(致龜;1777~1851)가 확장, 증축하면서 치구의 호인 서벽(棲碧)을 당호로 하였다고 한다. 평면은 정면5칸, 측면 4칸 구자형 평면에 전면부분만 양쪽으로 한 칸씩 덧붙인 날개집이다. 중문칸을 중심으로 서측에 사랑공간을 두었다. 2칸 온돌방과 1칸 마루방 3칸으로 구성되면서 서익사와는 방에서 연결될 수 있는 빈소방이 자리한다. 마루방은 뒤편 상부에 감실을 두었고 마루방과 온돌방 1칸 앞쪽에 툇마루를 두어 출입을 원활하게 하였다.","a":"서벽고택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/2513768.jpg"},{"q":"괘불이란 야외에서 큰 법회나 의식을 열 때 쓰이는 대형불화를 말하며, 이 불화는 보살 형태의 단독상을 화면 전체에 꽉 차게 그려 넣은 것이다. 보살상은 양 손으로 꽃가지를 받치고 서 있는 모습으로 상체를 크게 묘사한 반면 하체는 짧게 나타냈다. 머리에는 산(山) 모양의 화려한 장식이 달린 보관(寶冠)을 쓰고 있으며 네모진 얼굴을 하고 있다. 양쪽 어깨를 감싼 옷은 다양한 무늬로 장식되어 있고, 광배(光背)는 머리 광배와 몸광배를 구분하여 큼직하게 그렸다.","a":"법주사 괘불탱","c":"보물","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617241.jpg"},{"q":"○○○를 중심으로 사방 12곳에 세워놓은 장생표의 하나로 절의 경계를 나타내는 표시이며, 절의 동남쪽 약 4㎞지점에 서 있다. ○○○이라는 명칭은 나라의 명에 의해 건립된 장생이라는 의미로, 거친 자연석면에 글씨가 새겨져 있다. 장생은 수호신, 이정표, 경계표 등의 구실을 하고 있어 풍수지리설과 함께 민속신앙과도 깊은 관계를 맺고 있는데, 이 장생은 경계표와 보호의 구실을 한 것으로 보인다. 고려 선종 2년(1085)에 제작된 것으로, 나라의 통첩을 받아 세웠다는 내용이 이두문이 섞인 금석문으로 새겨져 있어 국가와 사찰과의 관계를 알려주는 중요한 자료이다.","a":"양산 통도사 국장생 석표","c":"보물","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622342.jpg"},{"q":"조선중기 이래 국정의 핵심 업무를 담당했던 최고 의결기관인 비변사(備邊司)에서 매일매일의 업무 내용을 기록한 책이다. 비변사의 약칭이 비국(備局)이었으므로 ‘비국등록(備局謄錄)’이라고도 한다. 임진왜란 이전의 『○○○○○』은 모두 소실되었고, 현재는 1617년(광해군 9)부터 1892년(고종 29)까지 276년간의 기록 273책이 남아 있다. 등록은 1년 1책으로 작성하는 것이 원칙이나, 사건이 많을 때에는 2책 또는 3책으로 작성하는 것도 있었다.","a":"비변사등록","c":"국보","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611613.jpg"},{"q":"「○○○○○」은 처음 건립 당시엔 이곳에서 ○○○를 믿는 지역민들이 주민 공동체로 시작하여 활동하다가 이후 ○○○ 교당으로 발전한 매운 드문 사례로 ○○○ 건축의 초기 가구구조와 공간구성 등 기본적 건축형식에서 원형의 모습을 잘 유지하고 있다.","a":"영광 원불교 신흥교당 대각전","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2017103022390000.JPG"},{"q":"○○○은 도화선에 손으로 불씨를 붙이는 휴대용 화기의 일종으로 전체 길이 75.5㎝, 지름 1.6㎝로 조선 선조 때 만들어졌다. 승자총통에서 진전된 형식으로 승자총통보다 길고 대나무와 같은 마디가 고르게 연결되어 있다. 총신은 약간 구부러져 있는데, 발사과정에서 탄환이 힘을 받아 멀리 나가도록 하기 위한 것이다. 총신이 길어 화기가 새지 않고 탄환이 명중할 수 있게 만들었으며, 화약을 넣는 약실을 약간 도톰하게 하였다. 남아 있는 기록을 통해 제작 연대와 화약의 용량, 제작자를 알 수 있으며, 보존상태 또한 완전하여 화포사 연구에 귀중한 자료로 평가된다.","a":"소총통","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614114.jpg"},{"q":"○○○○○에 놓여 있는 8각 ○○으로, 불을 밝혀두는 화사석(火舍石)을 중심으로, 아래에는 세 부분으로 이루어진 받침을 두고 위로는 지붕돌과 머리장식을 얹었다. 바닥돌과 하나로 이루어진 아래받침돌에는 여덟 장의 잎을 새긴 연꽃무늬가 조각되어 있다. 그 위에 놓인 가운데기둥에는 아무런 꾸밈이 없으며, 윗받침돌에는 각 면마다 연꽃이 새겨져 있다. 화사석에는 불빛이 퍼져 나오도록 4개의 창을 마련해 두었다. 지붕돌은 경쾌한 모습이며, 꼭대기에는 보주(寶珠:연꽃봉오리모양의 장식)가 남아 있다. 각 부분이 잘 균형을 이룬 우아한 모습의 통일신라시대 ○○이다.","a":"청도 운문사 금당 앞 석등","c":"보물","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620506.jpg"},{"q":"문수산(文殊山) 정상 가까이에 자리잡은 ○○○에 모셔져 있지만, 원래부터 이곳에 있었는지는 알 수 없다. 불상의 높이는 1.08m이며, 얼굴은 가는 눈, 꼭 다문 입, 반듯하고 넓은 신체에서 고요함과 안정감을 느낄 수 있다. 양 어깨에 걸쳐 입은 옷에는 주름이 평행 계단식으로 표현되어 다소 형식화 되었음을 알 수 있다. 무릎 사이의 부채꼴 모양으로 넓게 퍼진 주름은 다른 불상들의 U자형과는 달리 물결무늬로 특이한 형태를 취하고 있다. 이는 평행 계단식 옷주름과 함께 9세기 후반의 특징을 잘 보여 준다.","a":"봉화 축서사 석조비로자나불좌상 및 목조광배","c":"보물","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621925.jpg"},{"q":"회암사터에 서 있었던 비석으로, 고려말의 승려인 나옹(懶翁)화상을 추모하기 위하여 세운 것이다. 나옹(1320∼1376)은 1344년에 회암사로 들어가 불교에 입문하였다. 1358년 원나라에서 돌아와 왕의 부름을 사양하고 구월산과 금강산 등에서 은거하다가 회암사로 다시 돌아와 절을 크게 새로 지어올렸다. 신륵사에서 57세로 입적할 때까지 불법만을 행하였으며, 입적한 후 시호를 ‘선각’이라 하고 그 이듬해에 비를 세웠다. 비의 모습은 당나라의 형식을 닮은 복고풍으로, 비의 머릿돌을 따로 얹지 않았다.","a":"양주 회암사지 선각왕사비","c":"보물","nc":"","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615735.jpg"},{"q":"탑이 세워진 이 곳은 장각사라는 절이 있었던 곳으로 전하나 확실한 기록은 없다. 탑은 2단의 기단(基壇) 위에 7층의 탑신(塔身)을 세운 일반적인 모습으로, 흙을 다져 만든 단 주위에 돌로 테두리를 잡아 구역을 정한 후 그 위에 탑을 세웠다. 기단은 여러 장의 판돌로 이루어졌고, 탑신은 위층으로 올라갈수록 일정 비율로 줄어들고 있다. 1층 몸돌은 3개의 돌로 구성되어 있으며, 네 모서리에는 기둥 모양이 새겨져 있고 동쪽 면에는 문짝 모양의 조각도 있다. 2층 이상은 지붕돌과 몸돌을 하나의 돌로 구성한 특징이 보인다.","a":"상주 상오리 칠층석탑","c":"보물","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621475.jpg"},{"q":"조선 후기 만산 강용(1846~1934)이 1878년에 건립한 가옥으로 측면출입형 ㅁ자 형태의 본채와 서실, 별채, 대문채 등 사대부가 상류주택의 구성을 고루 갖추고 경북 북동부의 지역적 건축 특성을 잘 보여준다. 만산(晩山) 현판은 흥선대원군이 친필로 하사, 서실 처마 밑에 있는 한묵청연(翰墨淸緣) 편액은 영친왕이 8세 때 쓴 글로 왕실과의 밀접한 관계를 보여주고 있다.","a":"봉화 만산고택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635747.jpg"},{"q":"1921년에 준공한 2층 붉은 벽돌집으로 1934년에 불탄 옛 본관의 오른편에 지었다. 동관과 쌍을 이루고 있으며 설계자와 시공자 모두 알려지지 않았다. 뾰족한 아치형의 창틀과 가파른 고딕식 지붕 및 화강암과 붉은 벽돌로 엇물려 쌓은 정교한 솜씨로 보아, 우리나라 20세기 전기 건축양식의 기념비적 건물이다. 또한 3·1운동 이후 조선 소년군 창설, 6·10만세운동, 광주학생운동을 시작한 곳이기도 하다.","a":"서울 중앙고등학교 서관","c":"사적","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624925.jpg"},{"q":"○○시 금성동에 있는 웅진 백제시대 왕들의 무덤이 모여있는 곳이다. 무령왕릉을 포함한 이 일대의 고분들은 모두 7기가 전해지는데, 송산을 주산으로 뻗은 구릉 중턱의 남쪽 경사면에 위치한다. 계곡을 사이에 두고 서쪽에는 ○○○○○ 5 ·6호분이 있고 동북쪽에는 1∼4호분이 있다. 1∼6호분은 일제시대에 조사되어 고분의 구조와 형식이 밝혀졌고, 무령왕릉은 1971년 5 ·6호분의 보수공사 때 발견되었다.","a":"공주 무령왕릉과 왕릉원","c":"사적","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626455.jpg"},{"q":"○○○○○는 ○○○○○에 있는 신라 미추왕릉에서 발견된 길이 15.5㎝의 한 줄은 길고 세 줄은 짧은 ○○○○○이다. 긴 줄은 속이 빈 금 구슬에 꽃잎장식을 금실로 꼬아 연결하였고, 끝에 비취색 옥을 달았다. 작은 줄 역시 긴 줄과 같은 모양을 하고 있다. 현재의 상태가 원형인지 분명하지 않지만 신라 무덤에서 출토되는 ○○○ 가운데 가장 호화스러운 작품이다.","a":"경주 황남동 금제 드리개","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621313.jpg"},{"q":"○○○○은 코스트(Coste) 신부가 설계하였고 파리선교회의 재정지원을 얻어 건립되었다. 본래 순교자 김범우의 집이 있던 곳으로, 블랑주교가 김 가밀로라는 한국인 명의로 사들였다. 그후 1887년 한국과 프랑스사이에 통상조약이 체결된 후 1898년 완성하였다. 우리나라 최초의 벽돌로 쌓은 교회이며, 순수한 고딕식 구조로 지어졌다. 평면은 십자형이며 본당의 높이는 23m, 탑의 높이는 45m이다. 고딕양식의 장식적 요소를 배제하면서 그대로 본떴고, 공간의 고딕적 느낌은 외부보다 내부에서 더 강하게 주어졌다.","a":"서울 명동성당","c":"사적","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624813.jpg"},{"q":"갑오개혁 이후 자주독립의 의지를 다짐하기 위해 중국 사신을 영접하던 영은문(迎恩門)을 헐고 세운 기념물이다. 갑오개혁(1894∼1896)은 내정개혁과 제도개혁을 추진하였던 개혁운동이다. 그러나 외국세력의 간섭으로 성공하지 못하였고 나라의 자주독립 또한 이루지 못하였다. 이에 국민들은 민족의 독립과 자유를 위해서는 어떠한 간섭도 허용하지 않겠다는 다짐으로, 중국사신을 맞이하던 영은문을 헐고 그 자리에 ○○○을 세우게 되었다.","a":"서울 독립문","c":"사적","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624453.jpg"},{"q":"충남 ○○지방 선교를 위해 1908년 충남 결성군 구항면 공리에 본당인 수곡성당이 설립되어 초대신부 폴리(Desideratus Polly) 심응영 신부가 부임한 이래 제5대 신부인 바로(Barraux) 베드로 신부가 1934년에 ○○○ 현 본당의 부지를 매입하여 1937년에 신축 완료한 건물이다. 중앙의 종탑을 중심으로 네이브와 아일 부분 각각에 아치형의 출입구를 두고 각각의 아치위에 3개의 원형 옥스아이(oxeye) 창문을 높이 차이에 따라 차등을 두고 입면을 구성하고 있고, 포치나 종탑 부분은 입면에서 돌출되지 않은 채 하나의 평평한 입면을 구성하고 있다.","a":"서산 동문동성당","c":"국가등록문화유산","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668579.jpg"},{"q":"○○○○○은 근대기 민족 종교로 창설된 ○○○의 발상지인 영산성지에 위치하여 1936년 건립된 강당형 법당으로,종교 건축사적으로 가치가 있다.","a":"영광 원불교 영산대각전","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669045.jpg"},{"q":"○○○○는 고려말 상감청자가 쇠퇴하면서 백자와는 다른 형태, 무늬, 구도을 가지고 나타난 매우 독특한 자기이다. 그 명칭은 백토로 분장한 회청사기, 즉 ‘분청회청사기’라는 말에서 유래되었고 ‘분청’이라고도 한다. 총 높이 25.2㎝, 높이 22.6㎝, 아가리 지름 8.4㎝, 밑지름 10.2㎝의 이 병은 두께가 비교적 얇으며, 바로 선 듯이 밖으로 약간 벌어진 아가리를 가지고 있다. 아가리 아래부터 굽 윗부분까지 몸통 전체에 백상감된 2줄의 선을 이용하여 문양을 3부분으로 나누었다. 윗부분에는 변형된 연꽃잎을 흑·백상감하고, 그 안에 점을 찍어 채웠다.","a":"분청사기 상감모란당초문 유개항아리","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614448.jpg"},{"q":"한국 천주교의 성지인 ○○○과 주변에 있었던 양화나루터를 가리킨다. ○○○은 봉우리가 누에의 머리를 닮았다고 하여 붙여진 이름이다. 1966년 천주교에서 ○○○을 중심으로 성당과 기념관을 세웠고 주변 지역을 공원으로 꾸몄다. 성당과 기념관 안에는 이벽, 이가환, 정약용 등 천주교와 관련된 조선시대 후기 학자들의 유물을 전시하고 있으며, 광장 안에는 김대건, 남종삼의 동상과 사적비가 있다. ○○○ 주변에 있었던 양화나루터는 ○○○이 사적으로 지정된 뒤 추가로 지정된 유적이다.","a":"서울 양화나루와 잠두봉 유적","c":"사적","nc":"","r":"서울특별시","s":"마포구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625008.jpg"},{"q":"이 시설물은 한국전쟁 당시 북한군과 공비 침투에 대비하여 건립한 것으로, 초소와 망대 역할을 하였다. 무장 경찰관이 이곳에서 근무하면서 비상시에는 종을 울려 위험을 알렸다. 원형 ○○는 2층으로 되어 있는데 각층에는 밖을 내다볼 수 있는 창이 사방으로 나 있다. 바닥에 네모지게 구멍을 내어 사다리를 놓고 2층을 오르내렸다. 빨치산과 공비 토벌이라는 근대화 과정의 혼란스러움을 엿볼 수 있는 시설물이다.","a":"태백경찰서 망루","c":"국가등록문화유산","nc":"","r":"강원특별자치도","s":"태백시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668429.jpg"},{"q":"절에서 의식을 행하거나 불단 위에 올려놓고 향을 피우는데 사용하는 공양구이다. 특히 밥 그릇 모양의 몸체 아래 나팔형으로 벌어져 원반형의 받침을 지닌 것을 ○○이라 하였다. ○○○○○은 높이 33㎝, 입지름 30㎝, 받침대 지름 24.7㎝로서 전면에 굵고 가는 은·금실을 이용하여 연꽃무늬, 덩굴무늬, 봉황, 구름무늬로 가득차게 ○○○하였다. 몸통 중앙 네 곳에 원을 두르고 그 주위에 꽃무늬가 있다. 현재 원 안에 범자를 찍은 둥근 주석판을 4개의 못으로 고정시켰는데, 이것은 나중에 보수한 것이다.","a":"통도사 청동 은입사 향완(1963)","c":"보물","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622496.jpg"},{"q":"○○○는 통일신라 경문왕 7년(867)에 도의선사가 처음 세웠지만 대부분의 건물이 허물어져 고려 중기 보조국사가 제자들에게 당부하여 다시 지었다. 지금의 절은 조선 광해군 14년(1622)에 다시 고쳐 세운 것이다. 그 중 스님들이 생활하던 ○○○은 대웅전 뒤 한층 높은 곳에 있다. 앞면 3칸·옆면 2칸 규모로, 왼쪽 2칸이 툇마루를 갖춘 온돌방이고 오른쪽 1칸은 부엌이다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕이며, 기둥 위에서 지붕 처마를 받치고 장식을 겸하는 간결한 구조가 기둥 위에만 있다.","a":"순천 송광사 하사당","c":"보물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618954.jpg"},{"q":"「○○○○○」는 영조가 51살 때인 1744년(영조 20) 7월에 사친 숙빈최씨의 소령묘의 묘갈문을 짓기 위해 쓴 초안 원고이다. 이 원고에는 어머니 조상의 이름과 추증 연월, 어머니가 궁에 들어간 나이 등이 비어 있는데, 현재 숙빈최씨의 무덤 소령원(昭寧園)에 세워진 묘갈문에는 모두 채워져 있으며 내용도 일부 추가되었다.","a":"영조어필 - 숙빈최씨소령묘갈문원고","c":"보물","nc":"","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616172.jpg"},{"q":"1931년 건립 이 건물은 단군왕검의 영정을 봉안한 사당으로, 3·1운동 당시 ○○에서 만세를 주도했던 신태윤(1885~1961)이 후학들의 민족의식을 고취시키기 위해 건립하였다. 일제 치하에서도 개천절에 국민들이 이곳에 모여 제사를 지내고 나라의 독립을 기원하였다고 한다. 건물은 정면 3간 측면 2간의 맞배지붕이며, 익공은 연꽃과 봉오리가 초각되었고 보머리는 봉황 머리 모양으로 화려하게 장식되어 있다.","a":"곡성 단군전","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668963.jpg"},{"q":"이 불경은 대승불교가 일어나기 전의 상좌부(上座部)에서 갈라져 나온 설일체유부(說一切有部)의 사상을 알 수 있는 대표적인 논장(論藏)인 육족론(六足論) 가운데 하나로, 설일체유부의 논장에 통달한 세우존자가 저술한 것을 당나라의 승려인 현장이 한역한 것이다. 이 판본은 해인사 고려대장경 판과 비교해 보면 우선 판식이 동일하다. 그러나 ○○○은 판수제이고 책의 장수 표시가 ‘장(丈)’으로 되어 있는데, 해인사본에는 판미제에 장수 표시가 ‘장(張)’으로 되어 있다. 그리고 책 끝에 있는 간행기록이 ○○○에는 없는데 해인사본에는 있다.","a":"초조본 아비달마계신족론 권하","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614775.jpg"},{"q":"멀리 동해바다가 내다보이는 진전사터 안의 작은 언덕 위에 서 있는 탑으로, 진전사를 창건한 도의선사의 묘탑으로 추정된다. 도의는 선덕왕 5년(784)에 당에서 유학하고 헌덕왕 13년(821)에 귀국하여 선종을 펼치려 하였으나, 당시는 교종만을 중요시하던 때라 두각을 나타내지 못하고 이 절로 들어와 수도하다가 입적하였다. 이 탑은 일반적인 다른 탑과는 달리 8각형의 탑신(塔身)을 하고 있으면서도, 그 아랫부분이 석탑에서와 같은 2단의 4각 기단(基壇)을 하고 있어 보는 이의 호기심을 자아낸다.","a":"양양 진전사지 도의선사탑","c":"보물","nc":"","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616527.jpg"},{"q":"1940년대 초반에 우리나라에서 제작된 것으로 추정되는 ○○○으로 일제강점기 우편 마크 위에 광복 이후 우리나라의 우편 마크를 덧칠한 흔적이 있어 ○○○○ 과도기의 체신행정을 보여주고 있다.","a":"광복전후기 우체통","c":"국가등록문화유산","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668625.jpg"},{"q":"조선시대의 수도인 한양과 동남지방을 연결하는 주요통로로 사용되던 ○○로 ○○○○○라고도 한다. 이 ○○는 정종과 태종의 잦은 행차 때문에 세종 2년(1420) 5월에 처음 만들어지기 시작했으나 태종이 죽자 왕의 행차가 거의 없어 완성되지 못하였다. 그 후 이 길을 자주 이용하는 백성들 때문에 다시 만들 필요성이 제기되어 성종 6년(1475)에 다시 공사를 시작하여 성종 14년(1483)에 완성했다. 마치 평평한 평지를 걷는 것과 같다하여 ‘제반교(濟盤橋)’라고도 불렀다.","a":"서울 살곶이 다리","c":"보물","nc":"","r":"서울특별시","s":"성동구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615002.jpg"},{"q":"○○○ 선생은 대한제국이 멸망하자 6형제의 재산을 모두 처분하여 서간도에 신흥무관학교를 설립하였고 대한민국 임시정부를 수립하여 활동한 독립운동가이며 해방 후 대한민국 정부에서 부통령을 역임한 인물로, 이곳은 선생의 애국정신을 기릴 수 있는 역사적·교육적 가치가 큰 곳이다.","a":"서울 이시영 묘소","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667524.jpg"},{"q":"○○○○○은 ○○○○○ 동남쪽 구릉에 위치한 탑이다. 이 탑은 주인공의 존명과 건립년대를 기록하고 있는 조선시대 초기의 탑이라는 점에서 주목된다. 탑의 형태는 팔각원당형의 고려 탑을 계승하고 있으나 탑신이 구형(球形)인 점이 크게 다르다. 팔각 중대석 두 면에 걸쳐 ＇正德九年 甲戌五月 日立(정덕구년 갑술오월 일립)＇그리고 ＇學祖燈谷 和尙塔(학조등곡 화상탑)＇이란 명문이 있어 조선 중종9년(1514)의 건립임을 알게 한다.","a":"보은 법주사 복천암 학조화상탑","c":"보물","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617376.jpg"},{"q":"○○○○○ 입구에 있는 남녀 한 쌍의 돌장승이다. 사찰 앞에 세우는 사찰장승은 경내의 부정을 금하고 잡귀의 출입을 막는 수호신의 기능을 지닌다. ○○○은 대부분 무서운 듯하면서도 인자함을 지닌 모습으로 표현되며 절의 경계를 나타내기도 한다. ○○○○○은 사찰에서 500m쯤 떨어진 밭 가운데 마주보고 서 있는데 왼쪽은 남자, 오른쪽은 여자의 모습이다. 남장승은 높이 270㎝, 둘레가 192㎝에 달하는 거대한 체구로 크고 둥근 눈에 뭉툭한 코, 송곳니가 삐져나와 있지만 인자한 할아버지의 얼굴이다.","a":"나주 운흥사 석장승","c":"국가민속문화유산","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634569.jpg"},{"q":"물시계는 물의 증가량 또는 감소량으로 시간을 측정하는 장치로서, 삼국시대부터 나라의 표준 시계로 사용하였다. 조선 세종 16년(1434) 장영실에 의해 정해진 시간에 종과 징·북이 저절로 울리도록 한 물시계가 처음 제작되었으나, 오래 사용되지는 못하였고, 중종 31년(1536)에 다시 제작한 ○○○의 일부가 현재 남아 있다. 물시계의 원리를 보면, 맨 위에 있는 큰 물그릇에 넉넉히 물을 부어주면 그 물이 아래의 작은 그릇을 거쳐, 제일 아래쪽 길고 높은 물받이 통에 흘러든다.","a":"창경궁 자격루 누기","c":"국보","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611777.jpg"},{"q":"○○○불을 주존으로 하고 그 옆에 관음보살과 지장보살이 있는 ○○○○○로 가로 51㎝, 세로 110㎝ 크기의 불교그림이다. ○○○○○란 중생을 보살펴 극락으로 인도하는 부처인 ○○○불을 주존으로 하여 보통 관음보살과 세지보살이 협시되는데, 이 그림에서는 지장보살이 세지보살을 대신하고 있는 점이 매우 특이하다. ○○○불은 화면 아래에 극락왕생한 사람을 바라보며 빛을 비추고 있고 오른쪽에 있는 지장보살은 오른손에 구슬을 들고 서 있다.","a":"아미타삼존도","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611692.jpg"},{"q":"○○○○○경은 줄여서 ‘○○○’이라고 부르기도 하며, 부처와 중생이 둘이 아니라 하나라는 것을 중심사상으로 하고 있다. 화엄종의 근본경전으로 법화경과 함께 한국 불교사상 확립에 중요한 영향을 끼친 경전이다. ○○○○○은 해탈의 세계에 들어가기 위한 보현보살의 실천과 염원을 담고 있으며, ○○○ 중에서도 판각이 제일 성행하였던 부분이다. 당나라 반야(般若)가 한문으로 번역한『○○○』정원본 40권 가운데 마지막 권으로 징관(澄觀)이 풀이한 책이다.","a":"대방광불화엄경보현행원품별행소","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614602.jpg"},{"q":"○○○○은 3동의 건물이 ㅁ자형 구조를 갖춘 목조 기와집으로 화가 ○○ 선생이 살던 곳이다. 그는 1929년부터 서화협회 전람회에 만추 등을 출품하였고 중년 이후 온화하고 유연한 필치로 산수화와 화조화를 그려 전통적 화풍을 실현하는데 노력한 화가이다. 이 집에는 ○○ 선생을 기억하는 이들의 발길이 끊이지 않고 있다.","a":"서울 계동 배렴 가옥","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1666940.jpg"},{"q":"○○○은 대한제국 1대 황제 고종이 거처하던 생활공간(침전)이다. 광무 1년(1897)에 지었는데 광무 8년(1904) 수리공사 중 불에 타, 지금 있는 건물은 그해 12월에 다시 지은 건물이다. 이곳은 고종이 순종에게 황위를 물려준 뒤 1919년 1월 21일 세상을 떠난 곳이다. 규모는 앞면 9칸·옆면 4칸이며 서쪽 뒤로 4칸을 덧붙여 평면이 ㄱ자형이다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕인데 위쪽에 여러 가지 조각을 장식해 놓고 있다. 더욱이 지붕 모서리 부분에 장식기와를 나열한 점은 침전 건축에서 잘 사용하지 않는 특이한 구성이다.","a":"덕수궁 함녕전","c":"보물","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614039.jpg"},{"q":"이 비는 1989년 마을주민이 밭갈이를 하던 중 발견하였으며, 재산분배를 확인하는 증명서의 성격을 지니고 있다. 형태는 네모난 자연석으로 밑부분이 넓고 위가 줄어드는 모습이며, 앞면과 뒷면, 그리고 윗면의 3면에 글자를 새겼다. 비문은 거의 닳지 않아 눈으로 읽을 수 있을 정도로 보존상태가 좋다. 글자는 총 231자이고 서체는 해서체로 보이나, 예서체의 기풍이 많이 남아 있어 비문의 형태와 글씨체면에서 충주 고구려비(국보), 울진 봉평리 ○○○와 매우 비슷하다.","a":"포항 냉수리 신라비","c":"국보","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612917.jpg"},{"q":"이 건물은 1926년에 경성부청사로 건립된 관공서 건물로, 광복 후 1946년부터 서울○○○로 사용되었다가, 현재 서울도서관으로 사용되고 있다. 일제 강점기 당시 일본이 우리나라를 강점하기 위한 목적으로 지었던 건물로, 일본이 자행했던 한국 침탈의 역사를 증언하고 있다. 지하 1층 지상 6층(옥탑 2개층 포함)의 철근콘크리트조 건물로 일본인이 설계하였으며, 광복 후 서울○○○로서 사용되면서 한강의 기적을 이룬 한국의 현대사가 함께 담겨있는 역사의 현장이다.","a":"구 서울특별시청사","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1666889.jpg"},{"q":"이 차는 일본에서 제작하고 조선총독부 철도국 경성공장에서 조립한 승객용 ○○로 1955년 ○○○○○으로 개조되어 이승만 ○○○부터 박정희 ○○○까지 이용하였다. ○○ 안에 각종 시설‧설비가 갖추어져 있고 화려한 의장이 돋보이는 등 전직 ○○○ 관련 유물로 상징적 가치가 높다.","a":"대통령 전용 객차","c":"국가등록문화유산","nc":"","r":"경기도","s":"의왕시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668152.jpg"},{"q":"○○○는 신라 경덕왕 23년(764)에 처음 세워진 후, 고려 광종 이후 역대 왕들의 보호를 받아 큰 절로 성장하였다. ○○○에는 석조 문화유산들이 많이 남아 있는데, 모두 고달이라는 석공이 만들었다고 전한다. 고달은 가족들이 굶어 죽는 줄도 모르고 절을 이루는 데에 혼을 바쳤다고 하는데, 절을 다 이루고 나서는 스스로 머리를 깎고 스님이 되었으며, 훗날 도를 이루어 큰스님이 되니, ○○○라 불렀다는 전설이 있다. 절터 안에는 깔끔한 모양과 세련된 조각수법의 ○○○○부도(국보)를 비롯하여 훌륭한 문화유산들이 많이 남아 있다.","a":"여주 고달사지","c":"사적","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625900.jpg"},{"q":"○○○ 대웅전 앞에는 동서로 쌍탑이 서 있다. 그 중에 동쪽에 서 있는 것이 이 탑으로 크기는 서로 비슷하지만 서탑이 조각과 장식이 화려한 반면, 동탑은 아무런 장식없이 단정하다. 탑은 1단의 기단(基壇)위에 5층의 탑신(塔身)을 올린 형태로, 서탑의 기단이 2단인 것과는 조금 다른 모습이다. 기단의 각 면에는 모서리와 가운데에 기둥 모양을 조각하였다. 탑신부는 1층 몸돌이 높이에 비해 넓어 안정감이 있다. 또한 각 층 몸돌 너비의 줄어드는 정도에 비해 높이의 줄어드는 정도가 적어서 늘씬해 보인다.","a":"구례 화엄사 동 오층석탑","c":"보물","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618774.jpg"},{"q":"1936년 일제강점기에 지어진 관공서 건물로, 벽돌구조에 우진각지붕 형식을 가지고 있다. 구례면○○○로 사용되다 1963년 구례면이 ○○○으로 승격되면서 ○○○○○로 사용하기 시작하였다. 이 건물은 정면 중앙에 페디먼트를 가진 맞배지붕을 중심으로 좌우대칭 형태의 전형적인 일제강점기 관공서 건물 모습을 보여주고 있다.","a":"구례읍사무소","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668912.jpg"},{"q":"정조의 어진(御眞) 즉 초상화를 모셨던 곳이다. 조선시대에는 왕의 어진을 모신 건물이 전국 여러 곳에 있었지만 지금은 전주 경기전과 개성 목청전 및 창덕궁 선원전 그리고 ○○○만이 남아있다. ○○○은 정조 승하 이듬해인 1801년(순조원년)에 세워졌는데 이때 현륭원 재실에 모시고 있던 정조 어진과 창덕궁 주합루에 있던 어진을 함께 봉안하였다. 현재 ○○○에 모셔져 있는 어진은 1953년 정조어진이 소실된 이후에 새로 만든 표준영정이다. 1804년(순조4) 순조가 처음 화성에 와서 융릉과 건릉에서 제를 올리고 ○○○에서 술잔을 올리는 작헌례를 치렀다.","a":"수원 화령전","c":"사적","nc":"","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625448.jpg"},{"q":"○○○○○는 미국 남장로교 선교사 레이놀즈 목사가 1900년대 건립한 근대 교육 시설로, 호남과 제주도 지역 기독교 선교에 크게 공헌하였다. 강당은 리차드슨 여사의 기증을 받아 1936년에 강당 겸 체육관 용도로 건립한 장방형 평면의 벽돌조 박공지붕 2층 건물로, 박공면에 3개의 아치형태가 연속된 출입구가 있다. ○○ 건물은 1928년 3층 벽돌조로 건립하였으나, 1982년 화재로 소실되고 현재는 가운데 정면 ○○만 남아 있다. 이 지역 선교 역사를 간직한 건축물로 평가받고 있다.","a":"전주 신흥고등학교 강당과 본관 포치","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668709.jpg"},{"q":"○○○은 구 ○○시청 앞 도로인 중앙로와 수산업의 중심지인 해망동을 연결하기 위해 1926년 건립한 반원형 터널(높이 4.5m 길이 131m)로서 근대 도시 ○○의 모습을 보여주는 대표적인 토목 구조물이다. 일제강점기에는 ○○신사와 신사광장(현 서초등학교), 공회당, 도립○○의료원, 안국사(현 흥천사) 등이 인근에 있어서 사람들의 통행이 빈번한 교통의 요충지였으며, 한국전쟁 중에는 ○○ 주둔 북한군 지휘본부가 터널 안에 자리하여 연합군 공군기의 공격을 받았던 현대사의 중요한 역사의 현장이다.","a":"군산 해망굴","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668740.jpg"},{"q":"1926년에 콘크리트 옹벽 위에 지어진 일식 목조구조 건물로, 일제강점기 근대산업유산 중 현재까지 확인된 농업 관련 ○○○○○으로는 유일한 건물이며, 농업사 측면에서 가치가 매우 높고 대형 목구조 시스템의 희소성 등을 감안할 때 건축적으로도 가치가 높은 건물이다.","a":"서울 구 양천수리조합 배수펌프장","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"강서구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667150.jpg"},{"q":"남암산 아래에 있는 청송사 절터에 있는 ○○○○이다. 이 탑은 2단의 기단(基壇) 위에 3층의 탑신을 세운 모습이다. 기단은 각 모서리와 중앙에 기둥을 새기고, 마감돌 위에 다른 돌로 2단의 모난 괴임돌을 끼워서 각각 윗돌을 받치도록 하였다. 탑신(塔身)은 몸돌과 지붕돌이 각각 하나의 돌로 되어 있다. 1층 몸돌이 특히 길고 크며, 2층 몸돌은 급격히 줄어들었고, 각 몸돌 모서리에는 기둥모양이 새겨져 있다. 지붕돌 밑면에는 5단의 받침이 있고, 추녀가 두꺼워 지붕 네 귀퉁이의 치켜올림이 약하며 처마는 수평으로 길이가 짧다.","a":"울주 청송사지 삼층석탑","c":"보물","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615565.jpg"},{"q":"1954년 건립 이 건물은 ○○대학교의 ○○으로 건립되었으며, 지금은 ○○○○○ 체육관으로 사용되고 있다. 창호의 상인방과 하인방은 흰색으로 의장 처리되었고, 지붕은 박공지붕 양쪽 끝 부분이 약간 꺾인 맨사드 형태로 구성되었으며, 돌출된 현관부는 반원형 쌍아치로 장식되어 정면성이 강조되었다.","a":"청주 대성여자중학교 강당","c":"국가등록문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668522.jpg"},{"q":"조선 세조 3년(1457) 8월 10일에 왕이 충청남도 ○○에 있는 ○○○와 개천사에 내린 교지이다. 이것은 두 사찰의 잡역을 경감하라는 내용이며, 체제와 형식에 있어서 예천 용문사교지(보물), 능성 쌍봉사교지(보물)와 같으며, 대상 사찰명과 발급일자가 다를 뿐이다. 단, 쌍봉사에 발급한 교지와는 날짜까지도 같다. 이 문서는 국왕이 직접 내린 것으로 조선 전기 사패교지의 형식을 알려주는 자료이며, 세조 때의 불교정책을 살필 수 있는 자료로 평가된다.","a":"천안 광덕사 감역교지","c":"보물","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618013.jpg"},{"q":"흑칠 바탕에 금가루를 사용하여 그린 흑탱화로, 「화엄경(華嚴經)」의 칠처구회(七處九會)의 내용을 그린 변상도로, 「80화엄경」의 복잡한 내용을 천상을 의미하는 상단과 지상을 의미하는 중·하단의 3단으로 나누어 간단하게 묘사하고 있다. 하단에는 새롭게 천수관음(千手觀音)과 준제관음(准提觀音) 및 업경대(業鏡臺)를 배치하여 도상의 변화를 보여주고 있다.","a":"통도사 화엄탱","c":"보물","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622958.jpg"},{"q":"○○○○○은 풍산 유씨의 동족마을로 빼어난 자연경관과 민속·유교 전통을 잘 유지하고 있는 조선시대 양반촌이다. 그 중 ○○○○○은 양진당(보물)과 함께 하회 북촌을 대표하는 규모가 큰 집으로 북촌의 중심에 자리잡고 있다. 경상도 도사를 지낸 유도성이 철종 13년(1862)에 지었고 지금 있는 건물은 그 뒤 여러 차례 보수한 것이다. 크게 안채, 사랑채, 별당채, 대문간채, 사당으로 구성되어 있는데 대문을 들어서 앞에 보이는 건물이 'ㅁ'자형 몸채이며 오른쪽에 있는 건물이 별당채이다. 사당은 별당채를 지나 안쪽에 별도로 담장을 둘러 지어 놓았다.","a":"안동 하회마을 화경당 고택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635018.jpg"},{"q":"○○시 도계읍 ○○○는 ○○ 신리와 더불어 화전(火田)이 성행했던 마을로 ○○시에서 가장 깊은 산골마을에 속하며, 이 집은 동서로 길게 뻗은 계곡의 서측 산등성이 아래에 위치하고 있다. 현 소유주의 11대조가 병자호란(1636)때 이곳으로 피난와서 지은 것이라 한다. ○○○은 볏짚이나 기와를 얻기 어려운 강원특별자치도 산간지대에서 소나무 널쭉을 이용하여 지붕을 이은 집이다. 크기는 가로 30㎝, 길이 50㎝, 두께는 5㎝ 정도이며, 조금씩 겹쳐지게 덮고 바람에 날리지 않도록 군데군데 나무나 돌을 얹어둔다.","a":"삼척 대이리 너와집","c":"국가민속문화유산","nc":"","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633826.jpg"},{"q":"신라 17대 ○○○의 무덤이다. ○○○은 김씨 왕으로는 두 번째로 왕위에 올랐으며 이후 김씨 성에 의한 독점적 왕위계승을 이루었다. 마립간이란 왕 명칭을 처음 사용하였고, 중국 전진(前秦)과의 외교관계를 통해 선진문물을 수입하였다. 백제와 왜의 연합세력이 침입하자 고구려 광개토대왕에 도움을 요청하여 위기를 모면하였으며, 국력이 비약적으로 발전한 시기이다. 높이 5.3m, 지름 22m의 둥글게 흙을 쌓은 원형 봉토무덤이다. 밑둘레에는 자연석을 이용하여 둘레석을 돌렸다. 무덤 주변을 사각형으로 둘러싸고 있는 담장터 흔적이 있어 일찍부터 특별히 보호된 것으로 보인다.","a":"경주 내물왕릉","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627815.jpg"},{"q":"4각에 가까운 원추형의 바위 표면에 불상을 조각한 독특한 형태의 작품이다. 바위 꼭대기에는 동자상(童子像)이 있었다고 하는데 지금은 없어졌다. 동쪽면에는 좌상 1구가 있고, 북쪽면에도 좌상 1구가 합장하고 있다. 남쪽면에는 표현수법이 비슷한 4구의 입상이 있으며, 서쪽면에는 원래 2구의 불상이 있었는데 일제시대에 광부들이 1구를 떼어갔다고 전해진다. 이들 불상은 모두 세부표현이 거의 같다. 민머리 위에 높게 솟은 상투 모양의 머리(육계)를 가지고 있으며 얼굴은 길쭉하다.","a":"나주 철천리 마애칠불상","c":"보물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619142.jpg"},{"q":"홍각선사의 공로를 기리기 위한 탑비이다. 선림원터에 있으며, 통일신라 정강왕 원년(886)에 세워진 것으로 추정된다. 탑비는 일반적으로 비받침인 거북머리의 귀부(龜趺)와 비몸, 비머리돌로 구성되는데 이 비는 비받침 위에 바로 비머리가 올려져있다. 비문이 새겨지는 비몸은 파편만 남아 국립춘천박물관에 소장되어 있으며 귀부와 이수만 남아 있던 것을 2008년에 비신을 새로 복원하여 현재의 모습을 되찾게 되었다. 비받침의 거북은 목을 곧추세운 용의 머리모양으로 바뀌어있고, 등에는 6각형의 무늬가 있다.","a":"양양 선림원지 홍각선사탑비","c":"보물","nc":"","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616585.jpg"},{"q":"전라남도 ○○군 ○○○의 미륵전에 모셔져 있는 석조불상이다. 이 불상은 몸체와 광배(光背)가 하나의 돌로 조각되어 있어서 마치 바위에 직접 불상을 새긴 마애불과 같은 기법이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며 정수리에는 상투 모양의 머리(육계)를 큼직하게 표현하고 있다. 얼굴은 타원형이며 도드라진 눈덩이, 넓적한 코, 두터운 입술은 강건하면서도 미소를 잃지 않는 모습이다. 넓은 어깨, 평평한 가슴, 단순한 몸의 굴곡 등은 생동감이 없는 경직된 모습이다.","a":"영암 도갑사 석조여래좌상","c":"보물","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618737.jpg"},{"q":"○○○에 있는 이 탑비는 고려시대 중기의 승려 원응국사(1051∼1144)의 행적을 기록하고 있다. 원응국사는 일찍 출가하여 송나라에 가서 화엄의 뜻을 전하고 천태교관(天台敎觀)을 배워 귀국하였다. 1109년 선사(禪師)가 되었고, 인종 22년(1144) ○○○에서 93세로 입적하였다. 비는 비받침, 비몸, 머릿돌의 세 부분으로 이루어지는데, 받침돌과 머릿돌이 없어진 상태이다. 다만 세 쪽으로 잘린 비몸만 복원되어 있다. 비의 앞면에는 그의 행적이 새겨져 있으며 뒷면에는 제자들의 이름이 새겨져 있다.","a":"청도 운문사 원응국사비","c":"보물","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620741.jpg"},{"q":"○○○에 세워져 있는 탑으로, 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 기단은 각 면의 모서리와 가운데에 기둥 모양을 하나씩 본떠 새겼고, 탑신에서도 역시 몸돌의 모서리마다 기둥 모양의 조각을 두었다. 지붕돌은 밑면의 받침수가 층마다 4단이며, 빗물을 받는 낙수면은 경사를 약하게 두었고, 네 귀퉁이에서 약간씩 치켜 올려진 상태이다. 꼭대기에는 머리장식으로 노반, 복발, 앙화, 보륜, 보개(寶蓋:지붕모양의 장식) 등이 올려져 있으며, 머리장식부의 무게중심을 지탱하기 위한 찰주가 뾰족하게 꽂혀 있다.","a":"제천 신륵사 삼층석탑","c":"보물","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617249.jpg"},{"q":"○○○○○ 금제여래좌상(국보)과 함께 ○○ 황복사지 삼층석탑(국보)에 안치된 사리함 속에서 발견된 불상이다. 전체 높이 14㎝의 순금으로 만든 불상이며 대좌(臺座)와 광배(光背)를 모두 갖추고 있다. 민머리 위에는 상투 모양의 머리(육계)가 큼직하게 솟아 있고, 갸름한 얼굴은 양감이 있고 자비롭다. 눈은 정면을 바라보고 있으며, 콧날은 날카롭고 입가에는 미소가 번져 있다. 약간 좁은 어깨에는 두껍게 표현된 옷을 걸치고 있는데, 앞면에는 U자형의 옷주름을 새기고 있다.","a":"경주 구황동 금제여래입상","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611487.jpg"},{"q":"현재의 소유자 여경구의 장인인 이덕승의 8대조가 지었다고 전하는 집이다. 1800년대에 지은 것으로 추정되는데 이 마을에서 가장 높은 곳에 산을 뒤로 하고 있어 주변경관이 매우 아름답다. 안채와 사랑채·문간채·행랑채·사당채가 연결되지 않고 각각 떨어져 배치된 것이 특징이다. 안채는 집안 깊숙히 'ㄱ'자형으로 자리잡았고 안마당을 중심으로 광채가 'ㄴ'자로 배치되어 튼 'ㅁ'자형 배치를 보이고 있다. '一'자형 사랑채·대문채·사당채가 있으며, 사랑채 앞에는 헛간채가 있었으나 지금은 헐리고 없다.","a":"남양주 동관댁","c":"국가민속문화유산","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633741.jpg"},{"q":"조선 성종 때부터 연산군 때까지 문신 ○○ 선생의 종손가에 소장된 고문서와 전적이다. 총 9종 14점이다. ○○는 1480년 문과에 급제하여 승정원주서, 공조정랑 등을 거쳐 승정원 도승지, 충청도관찰사 등의 벼슬을 지냈다. 성종 13년(1482) 연산군의 생모인 폐비 윤씨가 사약을 받을 때 사약을 받들고 갔다는 이유로 벼슬을 빼앗겼으나, 임무에 따랐을 뿐이라는 이유로 사형을 면하고 귀양을 떠났다. 그러나 1505년 6월 다시 그 문제가 불거져나오자 결국 사약을 받고 죽었다. 성품이 검소하고 단아하였으며, 맡은 직무에 최선을 다하였다.","a":"권주 종가 문적","c":"보물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621928.jpg"},{"q":"공주시 ○○○릉에서 출토된 백제 때 귀고리 2쌍으로 길이는 11.8㎝, 8.8㎝이다. 왕비의 귀고리로, 굵은 고리를 중심으로 작은 장식들을 연결하여 만들었다. 한 쌍은 복잡한 형식으로 길고 짧은 2줄의 장식이 달려 있고, 다른 한 쌍은 1줄로만 되어있다. 앞의 귀고리 중 긴 가닥은 금 철사를 꼬아서 만든 사슬에 둥근 장식을 많이 연결하였으며, 맨 밑에는 작은 고리를 연결하여 8개의 둥근 장식을 달고 그 아래 탄환 모양의 장식을 달았다. 짧은 줄의 수식은 다른 한 쌍의 것과 거의 같은 수법이나 탄환 장식은 달지 않고, 잎사귀 모양의 장식과 담록색의 둥근 옥을 달았다.","a":"무령왕비 금귀걸이","c":"국보","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612278.jpg"},{"q":"아름다운 자연환경과 대나무 숲으로 둘러싸인 마을 깊숙한 곳에 자리잡고 있는 집으로 1900년대 초에 지은 마을지주의 집이다. 안채는 1908년에 지었고 사랑채도 당시에 지었다고 생각되며, 곳간채는 이보다 늦게 지어졌다. 대문채와 헛간채는 지은지가 얼마되지 않았다. 집의 가장 안쪽에 안채가 있고 맞은편에 사랑채가 있다. 안마당 맞은 편에 비스듬이 대문간이 있으며 동쪽에 헛간채가 있다. 바깥마당에는 사랑채로 통하는 대나무 문이 있고 사랑마당과 대문간은 담으로 경계하고 있다.","a":"보성 이용우 고택","c":"국가민속문화유산","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634666.jpg"},{"q":"달마산 기슭에 자리잡은 ○○○는 우리 나라 육지 가장 남쪽에 있는 절이다. ○○○ 사적비에 따르면 통일신라 경덕왕 8년(749)에 처음 지었다고 한다. 그 뒤 임진왜란으로 불탄 것을 조선 선조 31년(1598)에 다시 지었고, 영조 30년(1754)에 수리하였다고 한다. 석가모니 불상을 모시고 있는 ○○○은 앞면 3칸·옆면 3칸 규모의 건물로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 주춧돌은 앞면 4개와 옆면 2개를 특이하게 연꽃무늬에 자라, 게 따위를 조각한 돌을 사용하였으며 나머지는 자연석을 썼다.","a":"해남 미황사 대웅전","c":"보물","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619459.jpg"},{"q":"경상남도 거창군 북상면에 있는 ○○○ 영인정씨의 무덤에서 편병·접시·대접·잔·묘지(墓誌) 등 조선백자 10점이 ○○되었다. ○○○ 영인정씨는 조선 세조 때 언양 현감을 지낸 김윤(金潤)의 어머니로 ○○○은 출신지역이고 영인은 4품 벼슬 관리의 부인에게 주는 칭호를 말한다. 편병은 높이 21.7㎝, 밑지름 7.7㎝로 몸통이 둥글고 앞뒤로 납작한 모양이다. 아가리는 밖으로 살짝 벌어졌고, 굽이 좁고 높아 특이하다. 몸통에는 흑색 상감으로 모란과 덩굴무늬를 그려 넣었다.","a":"진양군 영인정씨묘 출토 유물","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611625.jpg"},{"q":"○○○의 서쪽에 있는 ○○ 2기로, ○○○로 들어가는 입구에서 조금 떨어진 곳에 나란히 세워져 있다. 하나는, 전체적으로 8각의 평면을 이루고 있으며, 네모반듯한 바닥돌 위로 3단의 기단을 세우고 그 위에 탑신과 지붕돌을 얹은 모습이다. 기단은 아래받침돌에는 2겹의 연꽃무늬를 새기고, 두껍고 넓은 가운데받침돌은 모서리마다 구슬을 꿰어놓은 듯한 기둥을 조각해 놓아 독특한 모습이다. 윗받침돌은 아래받침돌과 그 크기와 넓이가 비슷하며, 8장의 연꽃잎을 새겨두었다. 탑신의 몸돌에는 한쪽 면에 문짝 모양을 새기고 그 안에 자물쇠와 문고리 2개를 본떠 조각해 두었다.","a":"장흥 보림사 서 승탑","c":"보물","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618874.jpg"},{"q":"○○시 ○○○과 입석동 구릉 서남면에 있는 수십기의 크고 작은 무덤들이다. 무덤의 지름은 15∼20m, 높이 4∼7m 정도가 보통이며, 내부구조는 냇돌 또는 깬돌로 4벽을 쌓고, 판판하고 넓적한 돌로 뚜껑을 덮은 직사각형의 돌방이 있으며, 그 위에 자갈을 얹고 흙을 덮었다. 껴묻거리(부장품)로 금제 혹은 금동제 장신구와 철제무기 무늬를 새긴 토기 등 많은 출토물이 있다. 이 무덤들은 대개 5세기 전후경 삼국시대에 축조된 것으로 판단되며, 이 지역 일대를 지배하고 있던 토착 지배세력의 집단무덤으로 추측한다.","a":"대구 불로동 고분군","c":"사적","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625153.jpg"},{"q":"○○○○○는 조선시대 만들어진 높이 25.0㎝ 아가리 지름 5.3㎝ 밑지름 7.7㎝의 병으로 청화○○운룡문병(보물)과 한 쌍으로 발견되었다. 아가리는 밖으로 약간 벌어지고 몸체 아래쪽이 풍만하며, 목이 조금 길어 날렵하면서도 단아한 모양을 보이는 병으로, 궁중의 연례에 사용된 술병으로 보인다. 몸통 전면에 구름 속에서 3개의 발톱을 세우고 수염을 나부끼면서 여의주를 잡으려는 용을 그렸다. 이런 유형의 그림은 중국 명나라 전기 청화○○의 용무늬에서 따 온 것으로, 조선 중기 이후에 나타나는 표현과는 달리 매우 사실적이다.","a":"백자 청화운룡문 병(1984-1)","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613916.jpg"},{"q":"2단의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 형태이다. 아래층 기단에는 12지신상(十二支神像)을 한 면에 3구씩 새겼다. 위층 기단은 4면의 모서리와 가운데에 기둥 모양의 조각을 두고, 기둥으로 나누어진 각 면마다 8부중상(八部衆像)을 조각해 두었다. 8부중상은 통일신라 중기 이후 석탑에 등장하는데, 단순히 탑의 장식에만 목적을 둔 것이 아니라 탑을 부처님의 세계인 수미산으로 나타내려는 신앙의 한 표현이기도 하다. 탑신의 1층 몸돌에는 각 면마다 사천왕상(四天王像)을 도드라지게 새겼다.","a":"영양 현리 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621275.jpg"},{"q":"종묘와 함께 토지의 신과 곡식의 신에게 제사를 지내던 곳이다. 조선을 세운 태조가 한양에 수도를 정하고, 궁궐과 종묘를 지을 때 함께 만들었다. 토지의 신에게 제사 지내는 국사단은 동쪽에, 곡식의 신에게 제사 지내는 국직단은 서쪽에 배치하였으며, 신좌는 각각 북쪽에 모셨다. 제사는 2월과 8월 그리고 동지와 섣달 그믐에 지냈다. 나라에 큰 일이 있을 때나 가뭄에 비를 기원하는 기우제 그리고 풍년을 비는 기곡제들을 이 곳에서 지냈다.","a":"사직단","c":"사적","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624547.jpg"},{"q":"○○○○○ 무사전에 봉안되어 있는 지장보살삼존상을 비롯한 시왕·권속○○은 1648년(인조 26) 수조각승 인균(印均)을 비롯한 12명의 조각승들이 참여하여 조성한 작품이다. 지장보살상은 동그란 얼굴에 살이 적당히 올랐으며, 부푼 눈두덩 사이로 짧게 치켜 올린 눈이 인상적이다. 단정한 신체에 표현된 옷 주름은 강직한 직선과 부드러운 곡선을 잘 조화시켜 신체의 굴곡과 양감을 잘 살려내었다. 시왕과 권속상은 그들이 지니고 있는 개성적인 특징과 역할을 다양한 표현력과 연출력으로 생동감 있게 묘사하였다.","a":"여수 흥국사 목조지장보살삼존상·시왕상 일괄 및 복장유물","c":"보물","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620000.jpg"},{"q":"인도 무착보살이 지은 글을 당나라 현장이 번역하여 천자문의 순서대로 20권을 수록한 책으로, 고려대장경 가운데 처음 만든 본의 하나이다. 『○○○○○』은 줄여서 『현양론』이라고 하며, 또는 『광포중의론』이라고도 하는데 법상종의 논(論) 가운데 하나로 『유가사지론』에서 중요한 내용을 드러내기 위해 쓰여진 것이다. 20권 가운데 제12권이며, 전체 11품 가운데 섭정의품(攝淨義品) 제이지팔(第二之八)로 후반부에 해당하며, 처음 새긴 본이다. 크기는 가로 45.8㎝, 세로 28.6㎝이고, 종이질은 닥나무종이이다.","a":"초조본 현양성교론 권12","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611899.jpg"},{"q":"○○○○○은 일찍이 신라 ·통일신라시대 가마가 집단적으로 남아 있는 것으로 전해지는 곳이었는데, 1994년 지표조사와 1995년 시굴조사에서 여러 종류의 가마와 고분이 집단으로 남아 있음이 확인되었다. 이곳은 국내 발굴사상 최대규모의 토기·숯과 관련된 생산유적으로 토기가마와 관련된 채토장, 공방지, 건물지, 생산도구 등이 두루 확인되어 전체 생산공정 복원과 나아가 한국 고대사에 있어서 요업기술발달사를 이해하는 데에 중요한 자료를 제공한다.","a":"경주 손곡동과 물천리 유적","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627980.jpg"},{"q":"이 ○○○○○은 전형적인 ○○의 형태와 다양한 문양소재를 갖춘 대표적인 예라 할 수 있는데, 특히 어깨부분에 귀면(鬼面)을 붙여 장식효과를 높인 점이 눈에 띤다. 넓은 몸통을 크게 삼분하여 상단, 중단, 하단으로 구분하고 상단 어깨부분과 하단에는 서로 마주보는 연판문을 새겨 넣고, 중단의 평평한 면에는 능화형(菱花形)으로 화창(畵窓)을 새긴 후 그 안에 버드나무와 여러 마리의 새를 그려 넣었다. 중단의 둥근 측면에는 각각 세 줄기의 대나무와 가지가 Y자형으로 갈라진 활짝 핀 매화 한줄기를 새겨 넣었다.","a":"청자 상감유로매죽문 편병","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614786.jpg"},{"q":"해발 195m의 동산의 꼭대기 부근에 만들어진 돌로 쌓은 ○○이다. 지금은 성곽과 성벽 모두 파괴되고 허물어진 상태로 남아있다. 언제 성이 만들어졌는지 정확한 연대는 알 수 없으나, 신라 때 낙동강을 따라 수도 경주로 침입하려는 일본인을 막기 위해서 처음 쌓은 것으로 여겨진다. ○○의 시가지를 발 밑에 두고 멀리 낙동강까지 한눈에 바라볼 수 있는 좋은 곳에 자리잡고 있다. 비록 무너진 상태로 남아있지만 성이 만들어진 당시 성의 규모와 구조를 아는데 중요한 자료가 되는 곳이다. 성의 북동쪽에는 이 ○○과 비슷한 신기리○○이 있어 쌍성의 형태를 이루고 있다.","a":"양산 북부동 산성","c":"사적","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628204.jpg"},{"q":"1단의 기단(基壇) 위에 3층의 탑신(塔身)을 갖춘 고려시대의 일반적인 3층석탑으로, 원래는 ○○초등학교 뒤에 있던 것을 현재의 ○○미술관(당시 ○○군청('56~'86),이후 ○○읍사무소('86~'07)로 사용되던 부지)으로 옮겨 놓았다. 보수를 하여 보존상태는 양호하나 이미 지붕돌은 깨어졌다. 널찍한 돌 2장이 놓여 있고 그 위로 기단과 탑신부가 있는 상태이다. 기단 가운뎃돌의 각 모서리에 기둥모양을 새겨두었으며 가운데에도 기둥조각을 두었다. 기단을 마감하는 맨 윗돌은 윗면에 약간의 경사가 있다.","a":"홍천 희망리 삼층석탑","c":"보물","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616272.jpg"},{"q":"이흥사(利興寺)의 옛터에 남아있는 3층 석탑이다. 이흥사의 창건시기와 규모는 알 수 없으나 조선 후기인 18세기경까지 그 맥을 이어왔던 것으로 알려져 있다. 석탑은 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습으로 꼭대기에는 머리장식을 받치던 받침돌만 남아있다. 탑신의 몸돌과 지붕돌은 각각 다른 돌로 조성되었으며, 지붕돌은 두텁고 낙수면은 경사가 급하다. 1995년 탑을 해체, 보수할 때 땅 속에 묻혀있던 아래층 기단이 지상으로 드러나면서 본래의 모습을 찾게 되었다.","a":"영광 신천리 삼층석탑","c":"보물","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619207.jpg"},{"q":"○○○○○은『三國史記』,『世宗實錄』에서 매초성(買肖城)의 기사를 근거로 매초성(買肖城)으로 비정(比定) 되기도 하며, 『新增東國輿地勝覽』,『萬機要覽』,『京畿誌』,『京畿邑誌』,『輿圖備志』,『大東地志』등에서 ○○ 대모성산(大母城山), ○○○○의 기록이 확인된다. 임진강과 한강 유역을 연결하는 길목에 자리한 ○○○○은 주변의 산성 중 주 교통로에 위치하여 단지 방어만을 목적으로 축조된 것이 아니라, 행정치소로서의 역할을 담당했던 복합적 성격의 유적으로, ○○지역의 전술적 요충지 또는 치소로서의 중요성을 확인할 수 있다.","a":"양주 대모산성","c":"사적","nc":"","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626068.jpg"},{"q":"『○○○○○』 상·하 2첩은 선조연간의 명필 석봉(石峯) ○○가 절친했던 간이당(簡易堂) 최립(崔岦, 1539~1612)의 시문 21편을 단정한 해서로 필사한 것이다. 하첩 뒤쪽에는 이백(李白)의 오언시 한 수를 초서로 쓴 ○○이 더 있다. 장황은 근대의 것으로 “석봉○○선행해서첩(石峯韓濩先生楷書帖)”이란 제첨(題僉)은 서화상(書畵商) 원충희(元忠喜)가 썼다. ○○의 해서 ○○으로는 호성공신(扈聖功臣)과 선무공신(宣武功臣)의 교서(敎書)를 쓴 것 등이 전하고 있는데 이들 ○○은 승문원(承文院) 사자관(寫字官)으로 입신했던 ○○의 독특한 서풍을 잘 보여준다.","a":"한호 필적 - 석봉한호해서첩","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614483.jpg"},{"q":"○○○○○은 1960년대 한국 모더니즘 성당건축의 사례로서, 고딕 양식을 현대적으로 해석한 종탑, 거대한 성당 내부를 기둥 없이 구성한 철근 콘크리트구조, 절판구조의 캔틸레버 캐노피에 의한 정면 주출입구 디자인 등 1960년대 초기 성당 건축으로서 기술적 가치를 지니고 있음.","a":"대전 대흥동성당","c":"국가등록문화유산","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2126369.jpg"},{"q":"○○○○은 역사유적이 많이 남아 있는 전통있는 마을로 오래 된 토담과 돌담이 공존하고 있다. 양반 가옥 주위는 높은 토담이, 서민들이 거주하는 민가에는 나지막한 돌담이 남아있어 전통사회의 신분에 따른 담의 구조와 재료, 형식의 차이를 확인할 수 있다. ○○에 사용한 돌은 인근 남사천에서 쉽게 얻을 수 있는 강돌을 사용하였다.","a":"산청 남사마을 옛 담장","c":"국가등록문화유산","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669508.jpg"},{"q":"나주는 삼국시대 때부터 농업이 발달한 지역으로, 농업이 산업의 근간을 이루던 전근대 사회 동안 풍요를 누리던 지역이었고, 고려왕조부터 조선왕조까지 약 1,000년 동안 목(牧)으로서의 지위를 유지한 전라도의 대표적 큰 읍치이었으며, 현존하는 관아 건물과 ○○ 건물들이 그에 상당한 권위를 보여주고 있어 상당한 가치가 있다. 나주 관아는 신증동국여지승람, 금성읍지, 여지도, ○○○지도를 비롯한 고지도 등에서 위치와 건물 구성을 비교적 자세히 알 수 있으며.","a":"나주목 관아와 향교","c":"사적","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627400.jpg"},{"q":"조선 전기의 문신인 ○○○의 무덤에서 출토된 유물들이다. ○○○은 성주이씨(星州李氏) 조년(兆年 :1269~1343)의 9대손으로 명종 때 병조좌랑, 사헌부 지평, 호조참의, 승정원 도승지, 형조참판(종2품) 등 고위 관직을 두루 역임한 인물이다. 이 유물들은 2000년 4월 서울시 노원구 중계동 성주이씨 도정공파 종회 문중의 선산에서 묘 이장 중에 발견된 것으로 직령 4점, 답호 6점, 철릭 4점, 액주름 1점, 적삼 2점, 바지류 6점, 그리고 명정 1점 등 총 7종 24점이다.","a":"이언충 묘 출토복식","c":"국가민속문화유산","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633468.jpg"},{"q":"○○○○ 법당 앞에 세워져 있는 탑으로, 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 기단은 그 구조가 특이해서 보통 4각의 돌을 이용하는데 비해 여기에서는 8각 모양의 돌로 높게 2단을 쌓았다. 아래층 기단의 8면에는 안상(眼象)이 조각되어 있다. 이 기단의 맨 윗돌에는 윗층 기단을 괴기 위한 높직한 8각의 괴임돌이 놓여져 있는데, 이곳에는 연꽃무늬의 조각이 새겨져 있다. 윗층 기단은 매우 높으나 각 면에 꾸밈이 없다. 다만, 기단의 맨윗돌 아랫면에 다소 두툼한 느낌의 연꽃무늬를 조각하여 둘러 놓았다.","a":"철원 도피안사 삼층석탑","c":"보물","nc":"","r":"강원특별자치도","s":"철원군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616497.jpg"},{"q":"『○○○○』는『월인천강지곡』과『석보상절』을 합하여 세조 5년(1459)에 편찬한 불교대장경이다. 석보는 석가모니불의 년보 즉 그의 일대기라는 뜻이다. 조선 세종 28년(1446) 소헌왕후 심씨가 죽자 세종은 그의 명복을 빌기 위해 아들인 수양대군(후의 세조)에게 명하여 불교서적을 참고하여 한글로 번역하여 편찬한 것이 곧『석보상절』이다. 세종 29년(1447) 세종은『석보상절』을 읽고 각각 2구절에 따라 찬가를 지었는데 이것이 곧『월인천강지곡』이다.『○○○○』는 완질이 현재 전하지 않으므로 전권의 수량은 확인할 수 없다.","a":"월인석보 권1~2","c":"보물","nc":"","r":"서울특별시","s":"마포구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613778.jpg"},{"q":"○○○○○은 2003년 충남역사문화원 문화재센터에서 발굴조사를 실시한 결과, 청동기시대부터 마한 · 백제 · 조선시대에 이르는 360여기의 다양한 유구가 조사되었으며, 500여점에 이르는 다양한 유물이 출토되었다. 청동기시대에는 생활유적과 분묘유적이 광범위하게 자리잡고 있었으며, 마한시대에는 분묘만이 집중적으로 조영되다가 다시 백제시대에는 생활유적과 분묘유적이 자리잡고 있음이 확인되었다. 또한 조선시대에 와서 다시 생활유적과 분묘유적이 조영되고 있어 시기를 달리하면서 다양한 유구들이 확인되어 당시 사람들의 문화상을 파악하는데 중요한 자료를 제공하고 있다.","a":"서천 봉선리 유적","c":"사적","nc":"","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626747.jpg"},{"q":"○○○ 앞뜰의 큰 석불 앞에 놓여있는 4각 ○○으로, 불을 밝혀두는 화사석(火舍石)이 중심이 되어, 아래에는 3단의 받침돌을 쌓고, 위로는 지붕돌과 머리장식을 얹었다. 평면이 정사각형으로 이루어진 전형적인 고려식으로, 아래받침돌과 윗받침돌에 새겨진 굵직한 연꽃무늬가 두터움을 드러내고 있다. 가운데받침은 각이없는 굵고 둥그런 기둥으로 세웠는데, 위아래 양끝에는 두줄기의 띠를 두르고, 중간에는 세줄기의 띠를 둘렀다. 특히 중간의 세 줄기 중에서 가장 굵게 두른 가운데 띠에는 8송이의 꽃을 조각하여 곱게 장식하였다.","a":"논산 관촉사 석등","c":"보물","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617643.jpg"},{"q":"조선 후기 화가인 단원 ○○○가 그린 도석인물화이다. 도석인물화란 불교나 도교에 관계된 초자연적인 인물상을 표현한 그림이다. 이 그림은 원래는 8폭의 연결된 ○○그림이었으나 지금은 8폭이 3개의 족자로 분리되어 있다. 이 그림은 모두 연결한 상태에서 가로 575.8㎝, 세로 132.8㎝의 크기이며, 그것이 분리된 3개의 족자는 가로 48.8㎝, 세로 28㎝ 내외이다. 종이 바탕에 먹을 주로 사용하고 청색, 갈색, 주홍색 등을 곁들여 채색하였다.","a":"김홍도 필 군선도 병풍","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611590.jpg"},{"q":"○○○○○은 조선 초기의 ○○○○ 병으로 높이 20.4㎝, 아가리 지름 5.2㎝, 밑지름 8㎝이다. 회색의 바탕흙 위에 백토로 분장을 하여 무늬를 그리고, 그 외의 배경을 긁어낸 뒤, 긁어낸 부분에 다시 철채를 입혀서 어두운 녹색의 배경과 흰 무늬와의 대조가 선명하게 잘 어울리고 있다. 무늬는 변형된 모란무늬이며, 격식에 얽매이지 않는 자유스럽고 활달한 감각을 엿볼 수 있다. 병의 목 주변에는 변형된 연판무늬를 둘렀다. 유약은 투명한 회청색이며 일부 연한 갈색을 띤 곳이 있다. 표면이 매끈하지 않아도 생김새와 도안 의장법에서 친근하고 구수한 멋을 나타내고 있다.","a":"분청사기 박지철채화문 병","c":"보물","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613248.jpg"},{"q":"○○는 선조 5년(1572)에 안상이 편찬한 거문고 악보로, 목판본으로 출판된 악보 가운데 가장 오래된 것이다. 이 책의 머리글에는 안상이 1561년 장악원의 첨정으로 근무하면서 악공을 시험하는 책에 가락 쓰는 법과 술대 쓰는 법이 없는 것을 안타깝게 여기고 이를 보완하기 위해 악사 홍선종에게 합자보를 개수하게 하고 악공 허억봉에게 적보를, 악공 이두금에게 장구보를 만들게 하여 이 악보를 편찬하였다는 내용이 실려있다.","a":"금보","c":"보물","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613240.jpg"},{"q":"○○○는 고구려 소수림왕 11년(381) 아도화상이 세웠다고 전하지만 고려 중기까지의 역사는 확실히 알 수 없다. 조선 선조 38년(1605)과 광해군 6년(1614)에 큰 불이 일어나 절이 모두 타버려, 그 이듬해 다시 짓기 시작하여 광해군 13년(1621)에 원래의 모습을 되찾았다고 한다. 석가여래삼존불을 모시고 있는 ○○○은 광해군 13년(1621)에 지은 것으로 알려져 있다. 규모는 앞면 3칸·옆면 3칸이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위한 장식구조가 기둥 위뿐만 아니라 기둥 사이에도 있는 다포 양식이다.","a":"강화 전등사 대웅전","c":"보물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615360.jpg"},{"q":"○○○은 ○○○의 중심 건물로 임금님이 하례(賀禮)를 받거나 국가 행사를 거행하던 곳이고 ○○○은 ○○○의 정문이다. 광무 6년(1902)에 지었으나 1904년 불에 타 버려 지금 있는 건물은 1906년에 다시 지은 것들이다. ○○○의 규모는 앞면 5칸·옆면 4칸이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 짜은 구조가 기둥 위와 기둥 사이에도 있는 다포 양식이다. 밖으로 뻗쳐 나온 공포 부재의 형태가 가늘고 약해 보이며 곡선이 큰데 이것은 조선 후기 수법의 특징을 보이는 것이다.","a":"덕수궁 중화전 및 중화문","c":"보물","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614030.jpg"},{"q":"봉서산 기슭에 있는 통일신라시대의 절터이다. ○○○는 밀교의 후계자들인 안혜·낭융 들과 김유신·김의원·김술종 들이 뜻을 모아 국가의 평화를 기원하기 위하여 세웠다고 한다. 절터에는 금당이 있던 자리와 2기의 3층석탑과 석등 그리고 부도가 남아 있다. 탑은 동쪽과 서쪽에 있는데 규모와 형태가 거의 같으며 일제시대에 복원된 것이다. 탑에는 12지신상과 사천왕상을 새겨놓았는데, 그 수준이 매우 높아 통일신라시대 조각의 우수성을 알 수 있게 해준다. 두 석탑 사이에는 석등이 있고 4기의 부도가 동쪽과 서쪽 계곡에 나누어져 있으며 모두 고려시대 이후 것으로 보인다.","a":"경주 원원사지","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627659.jpg"},{"q":"경주시 황남동 미추왕릉 지구에 있는 삼국시대 신라 무덤인 ○○○○에서 발견된 ○○이다. 신라 ○○을 대표하는 것으로 높이 27.5㎝, 아래로 늘어뜨린 드리개(수식) 길이는 13∼30.3㎝이다. 이마에 닿는 머리띠 앞쪽에는 山자형을 연속해서 3단으로 쌓아올린 장식을 3곳에 두었고, 뒤쪽 양끝에는 사슴뿔 모양의 장식을 2곳에 세웠다. 푸른 빛을 내는 굽은 옥을 山자형에는 16개, 사슴뿔 모양에는 9개, 머리띠 부분에 11개를 달았다. 또한 원형의 금장식을 균형있게 배치시켜 ○○의 화려함을 더하였다.","a":"황남대총 북분 금관","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612865.jpg"},{"q":"○○○○○은 위가 넓고 아래가 좁은 길쭉한 형태의 점판암제(粘板巖製)로, 한 면에 5줄 74글자의 글씨가 새겨져 있다. 비석의 첫머리에 ‘임신(壬申)’이라는 간지(干支)가 새겨져 있고, 또한 그 내용 중에 충성을 서약하는 글귀가 자주 보이고 있어 ‘임신서기명석(壬申誓記銘石)’이라 호칭하고 있다. 비문의 내용은 다음과 같다. “임신년 6월 16일에 두 사람이 함께 맹세하여 기록한다. 하느님 앞에 맹세한다. 지금으로부터 3년 이후에 충도(忠道)를 지키고 허물이 없기를 맹세한다. 만일 이 서약을 어기면 하느님께 큰 죄를 지는 것이라고 맹세한다.","a":"임신서기석","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622199.jpg"},{"q":"○○○○은 월성 손씨와 여강 이씨의 동족마을로, 넓은 안강평야에 오랜 전통을 지닌 여러 집들을 잘 보존하고 있는 곳이다. 이 정자는 여강이씨 문중에서 세운 것으로 조선 명종 15년(1560)경에 처음 지었다고 한다. 지금 있는 정자는 철종 때에 행랑채를 빼고 화재로 모두 타 버려 1917년 원래 모습을 살려 다시 지은 것이다. 건물 구성은 크게 따로 담장을 둘러 세운 정자와 담장 밖에 있는 행랑채로 구분된다. 정자는 'ㄱ'자형 평면을 가지고 있으며 ㄱ자로 꺾이는 부분에 대청을 마련하였다. 대청 양 옆으로는 각각 방을 두었고, 왼쪽 방에는 누마루를 만들었다.","a":"경주 양동마을 심수정","c":"국가민속문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634988.jpg"},{"q":"원래 부석사 동쪽 산 너머 절터에 있었던 것을 옮겨온 것으로서 양식상 동일한 조각가에 의하여 만들어진 것으로 추정된다. 동쪽의 여래상은 얼굴이 타원형이며, 약간의 미소를 머금은 흔적이 있다. 두 손은 없어졌으나 두 팔이 가슴쪽으로 올라가 있어 왼손 검지를 오른손으로 감싸 쥔 손모양을 취하고 있는 비로자나불의 모습을 형상화한 것으로 보인다. 양 어깨를 감싸고 있는 옷에는 당시 유행하던 얇게 빚은 듯한 촘촘한 평행의 옷주름이 표현되었다. 대좌(臺座)의 가운데 부분은 8각인데 각 면에는 공양보살상을 조각하였다.","a":"영주 북지리 석조여래좌상(1963-1)","c":"보물","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2020031017444400.jpg"},{"q":"전라남도 ○○군 율어면 거의 전체를 병풍처럼 둘러 감싸고 있는 존제산의 북쪽 기슭에 새겨져 있다. 거대한 화강암의 바위에 한쪽 면만을 도드라지게 새긴 마애불(磨崖佛)이다. 이곳은 고려시대에 세워진 존제사(尊帝寺)의 절터라고 전해오고 있는데 다른 유물은 발견되지 않고 기와조각만이 흩어져 있을 뿐이다. 민머리의 중앙에는 상투 모양의 머리(육계)가 있고, 둥글고 원만한 얼굴을 하고 있으나 코와 입부분이 파손되었다. 둥글고 탄탄한 어깨는 전체적으로 안정감과 자비스러움을 풍기고 있다.","a":"보성 유신리 마애여래좌상","c":"보물","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619432.jpg"},{"q":"고려대학교 도서관 만송문고(晩松文庫)에 소장되어 있는 『○○○○○』권1·2<만송 貴 369B1>와 권7·8<만송 貴 369B4> 각 1책은 1447년 초간본으로 서울대규장각한국학연구원 소장 『○○○○○』<가람 古貴 811.51-G995y> 및 기왕에 보물로 지정된 보물 ○○○○○ 권3·4(역사박물관 소장)과 보물 ○○○○○ 권8·9·10(계명대 소장)과 같은 판본이다. 권1 권수의 서문 1~3장은 떨어져 나갔고 권2의 44~46장은 일부 훼손되어 45장은 3행만 있고 4~9행은 떨어져 나갔다.","a":"용비어천가 권1~2, 7~8","c":"보물","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614864.jpg"},{"q":"1910년 건립 이 건물은 일본이 주권을 빼앗은 1910년에 일본이 세운 관공서 건물이다. 붉은 벽돌을 쌓아 만든 2층 건물로 창문과 출입구 등 건물의 외관상 중요한 부분에 흰색 페인트를 칠했으며, 수직성을 강조한 단순한 형태이다. 일제 강점기에 일본이 우리 국민을 억압하고 민족 운동가들에게 잔인한 고문을 행했던 곳으로, 당시 일제의 만행을 증언하고 있다.","a":"구 나주경찰서","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668840.jpg"},{"q":"이 ○○○은 의장이 화려하고 정교한 면에서 법당 내에 모셔둔 사리탑의 일종으로 추측된다. 지금까지 알려진 ○○○은 대개 높이가 20∼30㎝ 정도이고, 50㎝가 넘는 것이 극히 드문데, 이 탑은 현재 높이만도 155㎝로 규모가 큰 편이다. 더구나 현재 남아있는 탑신은 5층이지만 원래는 7층 정도였을 것으로 보이고, 머리장식의 일부가 사라진 것으로 보아 원래 높이는 지금보다도 더 높았을 듯하다. 2층의 기단(基壇) 위에 5층의 탑신(塔身)을 세우고 꼭대기에 머리장식을 꾸민 탑으로, 석탑의 일반형을 그대로 따르고 있다.","a":"금동탑","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611679.jpg"},{"q":"○○○은 정조 때 대사헌, 대제학을 거쳐 판중추부사까지 오른 관리이자 제자백가에 두루 달통한 학자로 유명하다. 이 <○○○○○>은 현재 족자 반달축 뒷면에 “醇庵吳文靖公六十五歲眞像 李命基寫”라는 종이 제첨이 붙어 있는데, 비록 ○○○ 사후에 쓰여진 것이지만 당시 ○○화를 잘 그렸던 화원 이명기가 ○○○의 나이 65세 때의 모습을 그린 것으로 생각된다. 이전의 산뜻한 선염법을 사용하던 것과는 달리 세세한 붓질의 반복을 통해 얼굴의 형태와 명암을 자세히 표현하였다.","a":"오재순 초상","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614879.jpg"},{"q":"고려시대 만들어진 ○○○○으로 높이 27.7㎝, 아가리 지름 5.3㎝, 밑 지름 10.6㎝이다. 작고 나지막한 아가리가 달린 고려시대의 전형적인 ○○으로, 팽배하게 벌어진 어깨가 부드럽게 흘러내린 균형 잡힌 모습을 보이고 있다. 무늬는 가는 선만으로 새겼는데, 어깨 위에는 꽃봉오리 띠를 둘러 공간을 나누고, 그 안에 연꽃 덩굴무늬를 넣었다. 몸통 전면 4곳에 연꽃 가지를 큼직하게 새겼는데, 연꽃·연잎·연줄기·연밥으로 구성된 화려하고 사실적인 연꽃무늬이다. 밑동에는 겹 연꽃무늬와 번개무늬 띠가 있다. 유약은 밝고 투명하면서 차분한 느낌을 주는 비색을 고르게 칠했다.","a":"청자 음각‘효문’명 연화문 매병","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611842.jpg"},{"q":"1913년 무렵 건립 이 건물은 ○○ 지역에서 선교 활동을 한 미국 남장로교 ○○○○○의 사택으로 건립되었으며, 지금은 매산여고의 어학실로 사용되고 있다. 화강석으로 외벽을 쌓고 한식 기와를 얹은 한·양 절충식의 형태와 건물의 폭과 높이를 거의 1:1로 구성한 것은 ○○ 및 광주 지역의 ○○○ 주택 건축에서 나타나는 특징이다. 1900년대 초 ○○ 지역에서 활동한 ○○○들의 역사와 주거 형태를 살펴볼 수 있는 건축물로 평가받고 있다.","a":"순천 구 선교사 프레스턴 가옥","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668926.jpg"},{"q":"조선시대 만들어진 두 면이 납작한 높이 20.5㎝, 아가리 지름 5.0㎝, 밑지름 8.3㎝인 ○○이다. 이 병은 물레로 둥글게 만든 다음 앞·뒤를 두들겨 평평하게 만든 것으로, 몸통이 풍만하며 비교적 두껍게 백토를 발랐다. 문양을 보면 아가리 주위에는 연꽃무늬로 띠를 둘렀고, 몸통의 앞·뒤 평평한 면에는 연꽃을 표현하였고, 좌우에는 풀을 새겨 넣었다. 엷은 녹색의 유약이 전면에 고르게 잘 녹아들어 투명하며, 굽이 높고 밖으로 약간 벌어져 안정감을 준다. 조선시대 작품으로 풍부한 양감과 문양이 잘 어울리는 중요한 자료이다.","a":"분청사기 음각연화문 편병","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614717.jpg"},{"q":"○○○○ <○○○○○>은 조선 후기의 화가인 ○○○가 그린 그림책 형태의 풍속화 25점이다. 단원 ○○○는 신선그림이나 초상화, 산수화 등 다양한 주제로 그림을 그렸지만, 풍속화가로 더 유명하다. 풍속화는 종이에 먹과 옅은 채색을 하여 그렸는데, 각 장의 크기는 가로 22.4㎝, 세로 26.6㎝ 정도이다. <씨름>, <대장간>, <글방> 등과 같이 서민사회의 일상생활 모습과 생업에 종사하는 모습이 구수하고도 익살스럽게 표현된 그림들이 실려 있다.","a":"김홍도 필 풍속도 화첩","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613405.jpg"},{"q":"전라남도 승주군 낙안면 금전산의 서쪽에 있는 절터에 삼층석탑과 함께 있다.『동국여지승람』에 ‘금전산에 금둔사(金芚寺)가 있다’고 하여 이곳으로 추정하고 있다. 지붕 모양의 보개(寶蓋)와 대좌(臺座)를 갖춘 이 불상은 직사각형의 평평한 돌 한쪽면에 불상을 조각하여 마치 거대한 비석의 형태를 하고 있는 것처럼 보인다. 민머리의 정수리 부분에는 낮은 상투 모양의 머리(육계)가 솟아있고 얼굴은 원만한 형태이다. 신체는 우아하게 굴곡이 있어 부피감이 느껴지며 단아해 보인다. 양 어깨에 걸쳐 입은 옷에는 평행의 옷주름이 형식적으로 새겨져 있다.","a":"순천 금둔사지 석조불비상","c":"보물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619452.jpg"},{"q":"○○○○○는 전체 1권으로 구성되어 있으며 본문에 부분적으로 얼룩이 져 있으나 인쇄상태는 매우 양호하다. 책 표지의 우측에는 ‘○○○’ 라고 쓰여 있고 책의 좌측 중앙에 ‘양촌시(陽村集)’이라고 쓰여 있으며 우측 서뇌(書腦)에 ‘단구장(丹丘藏)’이라고 쓰여 있다.","a":"권근 응제시주(1991)","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614529.jpg"},{"q":"○○○ 법당에 모셔져 있는 목불좌상으로 1978년 불상 몸에 다시 금칠을 할 때 발견된 기록을 통해 고려 공민왕 11년(1362)을 하한으로 아미타불상이 조성되었음이 밝혀졌다. 얼굴은 단아하고 엄숙한 표정이며 무게있는 몸은 단정하고 앞으로 약간 숙여져 있다. 양 어깨를 감싸 흘러내린 옷은 가슴에서 매는 띠매듭이 사라지고, 3줄의 옷주름이 묘사되어 특징적이다. 전체적으로 고려 후기를 대표할 만한 뛰어난 작품이다.","a":"화성 봉림사 목조아미타여래좌상","c":"보물","nc":"","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615901.jpg"},{"q":"○○○ 당시의 공경사대부 및 72명의 제자들과 문답한 것 중 『논어』에 편입된 것을 제외하고 여러 서적을 모아 기록한 것에 원나라 왕광모가 각 장별로 제목을 달고 자세하게 풀이한 것을 붙인 것으로 박은이 강릉감영에서 간행하였다. 박은(1370∼1422)은 조선이 건국된 후 태조 7년(1398)의 제1차 왕자의 난과 정종 2년(1400) 제2차 왕자의 난 때 이방원을 도와 공을 세운 인물이다.","a":"신간표제공자가어구해","c":"보물","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616013.jpg"},{"q":"ㅇ 5세기 후반에서 6세기 전반에 조성된 삼국 시대 ○○○인 유곡리 및 ○○○○○은 연비산(鳶飛山)에서 서쪽으로 내려오는 완만한 구릉의 능선을 따라 40기의 봉토분(封土墳)이 분포하고 있다. ㅇ 1989년과 2013년 두 차례에 발굴조사를 한 결과, 6기의 봉토분에서 수혈식 석곽묘(구덩식 돌덧널무덤)와 횡혈식 석실묘(굴식 돌방무덤)이 확인되었다. 이중 32호분은 직경 21m 크기의 타원형 봉토가 온전히 남아있다.","a":"남원 유곡리와 두락리 고분군","c":"사적","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2018121914390700.jpg"},{"q":"안국사터에 세워져 있는 탑이다. 안국사는 창건된 해가 분명하지 않고, 다만 절 안에서 발견된 유물들을 통해 고려시대에 창건되었을 것으로 보고 있다. 이후 조선시대에 폐사되었던 것을, 1929년 승려 임용준이 주지가 되어 다시 일으켜 세웠으나 곧 다시 폐사되어 현재는 터만 남아있다. 절터에는 이 탑 외에도 ○○○○○ 석조여래삼존입상(보물)이 보존되어 있다. 탑은 아래부분인 기단부(基壇部)가 다른 탑들에 비해 간단하고, 2층 이상의 탑몸돌이 없어진 채 지붕돌만 포개져 있어 다소 엉성해 보인다.","a":"당진 안국사지 석탑","c":"보물","nc":"","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617465.jpg"},{"q":"근재 이전(1486∼1531) 선생의 덕을 추모하기 위하여 선조 24년(1591)에 손자인 이호가 지은 집으로 선생의 인품과 깨끗하던 지조를 기려서 재사에 ‘모선루’란 현판을 달았다. 마을 골 안으로 접어드는 길목의 오른쪽 높은 곳에 누마루를 앞면으로 하고 있으며, 건물 아래쪽에는 개울이 흐르고 뒷쪽에는 소나무가 우거진 좋은 자리에 위치하고 있다. 튼 'ㅁ'자 건물로 대문간채는 왼쪽부터 대문간, 마구간, 뒤주방으로 되어 있으며, 문을 들어서면 사각형의 안마당에 이른다.","a":"안동 예안이씨 근재재사","c":"국가민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635423.jpg"},{"q":"선도산 정상 가까이의 큰 암벽에 높이 7m나 되는 거구의 아미타여래입상을 본존불로 하여, 왼쪽에 관음보살상을, 오른쪽에 대세지보살상을 조각한 7세기 중엽의 삼존불상(三尊佛像)이다. 서방 극락세계를 다스린다는 의미를 지닌 아미타여래입상은 손상을 많이 입고 있는데, 머리는 완전히 없어졌고 얼굴도 눈있는 부분까지 파손되었다. 그러나 남아있는 뺨, 턱, 쫑긋한 입의 표현은 부처의 자비와 의지를 실감나게 보여주고 있다. 넓은 어깨로부터 내려오는 웅장한 체구는 신체의 굴곡을 표현하지 않고 있어 원통형으로 보이지만, 여기에는 범할 수 없는 힘과 위엄이 넘치고 있다.","a":"경주 서악동 마애여래삼존입상","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620126.jpg"},{"q":"○○○○○은 조선 성종20년(1489)에 편찬 간행한 의서로서 8권8책이다. 우리나라의 구급방서(救急方書)로서는 가장 완비된 책으로 질병을 중풍·두통 등 127종으로 나누고 그 치료방문을 모아 엮은 것이다. 이 ○○○○○은 을해자본(乙亥字本) 번각본(翻刻本)으로 설월당(雪月堂) 김부륜(金富倫, 1531～1598)의 소장인이 찍힌 점 등으로 미루어 보아 16세기 간본임을 알 수 있다. 전하는 것이 매우 희귀한 언해본(諺解本) 의약서(醫藥書)로서 한의학(漢醫學)은 물론 우리 국어연구에 매우 중요한 자료이다.","a":"구급간이방 권6(2006)","c":"보물","nc":"","r":"서울특별시","s":"강서구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614721.jpg"},{"q":"○○○의 정상을 둘러싼 길이 620ｍ의 백제 성이다. 경사가 가파르고 서쪽은 임진강, 남쪽은 한강·동쪽은 농경지·북쪽은 산으로 이어진다. 성벽은 서쪽 부근이 잘 남아있다. 성벽 쌓기 수법을 보면 밖으로는 위로 올라가면서 돌을 안으로 들여 쌓고, 성벽 내부는 돌로 채웠다. 이러한 성곽의 형태는 백제 성곽 연구에 매우 중요한 자료가 된다. 광개토대왕릉비와 『삼국사기』백제본기에 나오는 관미성이 이 바로 ○○○○이라는 주장이 있으며, 김정호의 『대동여지도』에는 이곳을 관미성이라 기록해 더욱 주목 받고 있다.","a":"파주 오두산성","c":"사적","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625824.jpg"},{"q":"여수시 영취산에 있는 ○○○는 고려 명종 25년(1195)에 보조국사 지눌이 창건한 사찰로, 나라가 번성하면 이 절도 함께 번창할 것이라는 흥국의 염원을 담고 있어 ○○○라고 전한다. 나한은 아라한이라고도 하는데 수행을 거쳐 깨달은 성자를 말하는데 ○○○○○는 응진당(應眞堂)에 보관되어 있다. 중앙의 영산회상탱은 없어지고, 지금은 ○○○ 여섯 폭만이 남아 있다.","a":"흥국사 십육나한도","c":"보물","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619768.jpg"},{"q":"전북특별자치도 ○○에 있는 무덤으로, 남북으로 2기의 무덤이 나란히 자리잡고 있어 ○○이라고 부른다. 무덤 안의 구조는 백제 후기 굴식돌방무덤(횡혈식석실묘)이며, 무덤의 봉분과 돌방의 크기가 큰 북쪽의 것을 대왕묘라 하고, 남쪽의 작은 것을 소왕묘라고 부른다. 크기는 약간 차이가 있지만 2기 모두 원형의 봉토무덤으로 흙을 높이 쌓아 만든 봉분 이외에 별다른 장식이 없다. 1916년 조사할 당시 무덤은 이미 도굴이 되어 유물이 남아 있지 않았다. 다행히 대왕묘 안에서 나무로 만든 관이 일부 발견되어 원래의 모습대로 복원 할 수 있었다.","a":"익산 쌍릉","c":"사적","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626787.jpg"},{"q":"○○○○○은 흙을 채우지 않고 돌만 사용하여 줄맞춤 없이 쌓은 돌담과 흙다짐에 돌을 박은 형식인 토석담이 섞여 있다. ○○○○은 삼한 시대부터 마을이 형성되었으며, 예부터 바다로 나가는 뱃길이 있어 중국‧일본과 교류하던 중심지로 역사를 자랑하는 곳이다. 가옥의 벽체, 하천 제방과 옛 돌담이 잘 조화되어 우리의 전통 마을경관을 잘 연출하고 있다. 마을 주민들이 스스로 세대를 이어가며 만들고 덧붙여 우리 민족의 미적 감각이 고스란히 담겨 있는 문화유산이다.","a":"영암 죽정마을 옛 담장","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669033.jpg"},{"q":"○○○에 있는 증각대사의 탑비이다. 증각대사는 일명 홍척국사 ·남한조사로 불리며, 통일신라 헌강왕 때에 당나라에 들어갔다가 흥덕왕 1년(826)에 귀국한 뒤 구산선문의 하나인 ○○○파를 일으켜 세운 고승이다. 비는 비몸돌이 없어진 채 현재 거북받침돌과 머릿돌만이 남아있다. 받침돌은 용의 머리를 형상화 하지않고 거북의 머리를 그대로 충실히 따랐다. 머릿돌은 경주의 ‘태종무열왕릉비’계열에 속하는 우수한 조각을 보여주는데, 앞면 중앙에 ‘응료탑비(凝蓼塔碑)’라는 비명칭을 새겨 두었다.","a":"남원 실상사 증각대사탑비","c":"보물","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618201.jpg"},{"q":"○○○○○는 1939년 ○○덕산공립심상소학교 교장 ○○로 건축된 목조건축물로, 외관을 비늘판 붙임으로 하는 등 일본식 주거건축의 특징을 잘 갖추고 있으며, 근대 시기 ○○지역에 건립된 교육관련 시설 가운데 현존하는 몇 안 되는 ○○ 건물로 가치가 있다.","a":"대구 삼덕초등학교 구 관사","c":"국가등록문화유산","nc":"","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2135809.jpg"},{"q":"임진왜란(1592) 때 왜군과 싸우다가 장렬히 전사한 700명의 병사들을 위한 무덤과 사당이다. 조헌(1544∼1592)은 의병장으로, 문과에 급제한 후 호조좌랑, 예조좌랑, 감찰을 거쳐 보은현감으로 나갔으나, 여러 번 재등용되었는데 사직하고 임진왜란이 일어나자 옥천에서 1,700여 명의 의병을 일으켜 영규대사와 합세하여 청주를 탈환하였다. 이어 ○○에서 왜군을 막기 위해 남은 군사 700명과 함께 ○○전투에서 장렬히 싸우다 전사하였다. 시호는 문열(文烈)이다.","a":"금산 칠백의총","c":"사적","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626513.jpg"},{"q":"경상북도 ○○시 ○○○ 남쪽 ○○의 정상에 병풍처럼 둘러 쳐진 암벽을 배경으로 만들어진 좌불상이다. ○○을 ‘갓바위’라고 부르기도 하는데, 그것은 이 불상의 머리에 마치 갓을 쓴 듯한 넓적한 돌이 올려져 있어서 유래한 것이다. 민머리 위에는 상투 모양의 머리(육계)가 뚜렷하다. 얼굴은 둥글고 풍만하며 탄력이 있지만, 눈꼬리가 약간 치켜 올라가 있다. 귀는 어깨까지 길게 내려오고 굵고 짧은 목에는 3줄의 주름인 삼도(三道)가 표시되어 있다. 다소 올라간 어깨는 넓고 반듯해서 당당하고 건장하지만 가슴은 평판적이고 신체의 형태는 둔중해진 듯하다.","a":"경산 팔공산 관봉 석조여래좌상","c":"보물","nc":"","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620933.jpg"},{"q":"이 건물은 한국전쟁 당시 모슬포에 육군 제1훈련소가 정식으로 설치되면서 훈련 장병들의 정신력을 강화하기 위해 훈련소장인 장도영 장군의 지시로 1952년에 건립된 교회이다. 제주도산 현무암을 사용하여 벽체를 쌓고 목조 트러스 위에 함석지붕을 씌운 형태로 민간 건축 기술자의 참여 없이 공병대에 의해 건축될 수밖에 없었던 한국전쟁 당시의 상황을 엿볼 수 있다. 고된 훈련 또는 전쟁터로 떠나기 전에 수많은 병사들의 기도가 이루어졌던 역사적 장소이다.","a":"남제주 강병대교회","c":"국가등록문화유산","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669551.jpg"},{"q":"○○○선생은 3·1운동 발발 직후 유림계를 대표하여 파리장서를 갖고 상해로 건너가 파리강화회의에 송부하고 대한민국 임시의정원 구성에 참여, 제2차 유림단사건 등에 관계하였다. 해방 후 친일유림들을 청산하여 유학의 기틀을 바로 세우고 성균관대학을 설립한 종교지도자이자 교육가로 활동한 인물로, 이곳은 선생의 애국정신을 기릴 수 있는 역사적·교육적 가치가 큰 곳이다.","a":"서울 김창숙 묘소","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667539.jpg"},{"q":"○○○은 우리나라 독립운동사에 매우 특이한 인물이다. 한말의 의병장들은 양반유림들이 대부분인데, ‘담살이’ 즉 ‘머슴’으로 있다가 일제에 의해 국권이 침탈당하자, 평민으로서 대표적인 ‘의병장’이 되었기 때문이다. 이 ○○은 ○○○ 의병가의 거주지일뿐만 아니라, 그의 의병부대의 운량관으로 군수물자를 제공하였던 ○○○의 ○○이기 때문에 역사적 가치가 있다.","a":"보성 안규홍·박제현 가옥","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2017121110225900.JPG"},{"q":"「○○○○」는 고려 인종 때 현유(賢儒)의 위패를 봉안, 배향하고 지방민의 교육과 교화를 위하여 창건되었으나, 조선 세종 때에 현 위치인 교동으로 옮긴 후 18세기까지 대성전에서 제향기능만 유지하다가, 1725년에 ○○○을 상량하고 1728년에 완공하여 향교로서의 면모를 갖춤. ○○○○○은 1725년 중건된 후 여러 차례의 수리가 이루어졌으나 누각형식을 수용한 독특한 평면을 잘 유지하고 있으며, 공(工)자형의 독특한 지붕형태와 가구형식은 유래가 드문 건물이라는 점에서 역사적, 학술적으로 가치가 큼.","a":"산청 단성향교 명륜당","c":"보물","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2020122909312800.jpg"},{"q":"○○○○은 산마루를 둘러 쌓은 통일신라시대의 테뫼식 산성으로 둘레는 1,250m이며, 그 중 약 300m 구간에 성의 흔적이 남아있다. 한우물은 '큰 우물' 또는 '하늘 못(天井)'이라는 뜻으로 ○○○○ 안에 있는 2기의 연못 중 하나이다. 발굴조사에서 연못 2개 ·건물지 4개가 확인되었고 많은 유물들이 출토되었다. 조선시대의 한우물은 동서 22m, 남북 12m, 깊이 1.2m이고 그 아래의 신라시대 석출지도 확인되었다. 다른 우물지에서는 ‘잉벌내력지내미(仍伐內力只內未)’라는 글이 있는 청동숟가락이 나왔다.","a":"서울 호암산성","c":"사적","nc":"","r":"서울특별시","s":"금천구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1624971.jpg"},{"q":"1945년 무렵 건립 이 시설물은 중국 본토 공략을 위해 1935년 무렵 ○○○에 594,000㎡ 규모로 조성한 비행장을 1945년 무렵에 1,320,000㎡으로 확장하면서 만든 일본 해군 비행장의 부속 시설이다. 콘크리트 구조체를 만들고 위쪽에 돌무더기를 쌓아 동산처럼 만든 다음 나무 등으로 가려 숨겨 조성하였다. 일본이 ○○도를 군사 기지화하였던 침략의 증거물이다.","a":"제주 모슬포 알뜨르비행장 일제 지하벙커","c":"국가등록문화유산","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669589.jpg"},{"q":"이 문서는 고려 희종 원년(1205)에 진사시에 급제한 ○○○에게 내린 교지이다. 크기는 가로 93.5㎝, 세로 45.2㎝로 황색 마지 두루마리에 쓰여져 있다. ○○○는 울진부원군 문성공 장말익(張末翼)의 8세손으로 추밀원부사, 전리판서 등을 역임하였으며 고려 개국공신 장정필의 12세손이다. 조선시대 과거에 급제한 사람들에게 내린 ○○, 백패(白牌)와 같은 성격의 교지이다. 앞부분이 없어져 완전한 내용을 파악할 수 없으나, 고시에 관여했던 사람의 관직과 성이 기록되어 있다.","a":"장양수 홍패","c":"국보","nc":"","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612857.jpg"},{"q":"홍척국사의 사리를 모신 탑으로, 팔각의 평면을 기본으로 삼고 있는 전형적인 팔각원당형 탑이다. 홍척은 통일신라 후기의 승려로 시호는 ‘증각’이다. 탑은 기단(基壇)은 팔각형의 석재를 여러층 쌓은 뒤 연꽃이 피어있는 모양의 돌을 올렸다. 각 면의 조각들은 닳아 없어져 거의 형체를 알아보기가 힘들고 윗받침돌의 연꽃잎만이 뚜렷하다. 탑신은 몸돌과 지붕돌로 구성되었는데 낮은 편이다. 몸돌은 기둥 모양을 새겨 모서리를 정하고 각 면에 아치형의 문(門)을 새겼다. 그곳에 문을 지키고 있는 사천왕상(四天王像)을 돋을새김하였다. 지붕돌에는 목조건축의 처마선이 잘 묘사되어 있다.","a":"남원 실상사 증각대사탑","c":"보물","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618194.jpg"},{"q":"○○○은 고종 22년(1882)에 식년문과에 급제하여 사간원 정언, 사헌부 지평 등 양사의 청직을 역임하였으며 통례원(국가의 의례를 주관하는 부서)의 좌·우통례(정3품)를 지낸 인물이다. ○○○○○ 6종 41점(관모 및 두식류 10점, 관복류 11점, 장신구류 8점, 신발류 5점, 보관용구류 5점, 기타물품류 2점)은 착용자가 확실한 구한말 관직자의 일괄유물로 종류가 다양하고 상태 또한 양호하여 당시의 복식제도는 물론 생활상을 파악할 수 있는 귀중한 자료로 평가된다.","a":"장영직 유품","c":"국가민속문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1633427.jpg"},{"q":"괘불이란 절에서 큰 법회나 의식을 행하기 위해 법당 앞뜰에 걸어놓고 예배를 드리는 대형 불교그림을 말하는데 ○○○○○은 중앙에 석가불과 좌우에 보살상을 배치한 석가삼존도 형식이다. 중앙의 본존불은 왼손을 무릎 위에 놓고 오른손을 내려서 땅을 가리키는 항마촉지인을 하고 있다. 본존불 좌우에 연꽃가지를 들고 서 있는 두 보살은 거의 비슷한 형태인데, 왼쪽의 문수보살은 보관에 조그만 부처가 묘사되어 있는 것이 오른쪽 보살과 다르다.","a":"도림사 괘불탱","c":"보물","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619801.jpg"},{"q":"신라 경덕왕 13년(754) 황룡사 승려 ‘연기조사’의 발원으로 건립된 화엄종 사찰로 ‘도선국사’가 도참설에 의해 중창하였고, 조선시대 ‘벽암각성’의 중창이후 선·교 양종 총림 대도량의 역할을 하였다. 대웅전과 누문을 잇는 중심축과 각황전과 석등을 연결하는 동서축이 직각을 이루고 있는 독특한 가람배치를 갖추고 있으며, 경내에는 국보 ‘○○○각황전’을 비롯하여 국보 4점, 보물 8점 등 중요 문화유산이 있어 역사적·학술적으로 가치가 크다.","a":"구례 화엄사","c":"사적","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627435.jpg"},{"q":"조선 선조에서부터 인조 때까지의 문신이었던 ○○의 종손가에 소장된 고문서와 책들로 총 10종 62점이다. ○○은 김성일과 정구의 문인이었으며, 임진왜란이 터지자 의병을 모아 활동하였고, 선조 29년(1596)에 도체찰사였던 이원익의 막하로 들어가 활약하였다. 선조 36년(1599)에는 사마시에, 2년 후에는 문과에 급제하여 호조좌랑, 사헌부감찰, 대구판관 등의 벼슬을 지냈다. 그가 죽은 후 이조참판에 증직되었다.","a":"조정 종가 문적(1989)","c":"보물","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621958.jpg"},{"q":"○○○에 있는 정진대사 긍양의 사리탑으로, 경내에서 벗어나 사찰 입구 북쪽 산중턱 가까이 자리하고 있어 경승지를 택해 조성하였음을 알 수 있다. 정진대사(878∼956)는 통일신라 효공왕 원년(897)에 개초사에서 수도한 후, 효공왕 3년(899)에 당에 다녀왔다가 경애왕 원년(924)에 귀속하여, 백암사를 거쳐 ○○○에 와서 이 절을 크게 번영시켰다. 각 부분이 8각을 이루고 있는 이 탑은 탑신(塔身)을 받치는 기단(基壇) 곳곳에 꽃무늬조각과 구름·용·연꽃무늬 등의 불교 세계를 상징하는 각종 장식을 화려하게 두었다.","a":"문경 봉암사 정진대사탑","c":"보물","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620432.jpg"},{"q":"마을 중심부에 위치한 이 가옥은 안채, 중 사랑채, 큰 고방채, 작은 고방채, 큰 사랑채, 사당, 대문채 등 7동으로 이루어져 있으며 서남향으로 자리한 대문채를 들어서면 좌측 편에 남향한 큰 사랑채가, 우측으로 별곽(別廓)을 이루어 사당이 위치하고 대문채와 마주 보고 있는 중 사랑채가 안채와 2동의 고방채와 더불어 튼 ＇ㅁ＇자의 몸채를 이루고 서북향으로 배치되어 있다.","a":"청도 운림고택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635603.jpg"},{"q":"광배와 상이 하나의 돌에 조각된 거의 완전한 형태의 보살상으로, 원래는 시내의 절터에 있던 것을 현재의 위치로 옮겼다고 한다. 굵은 목에 넓고 둥근 어깨는 힘차고 당당한 모습이며, 이러한 경향은 굵은 팔, 다리 및 투박한 손발 등 신체의 각 부분에까지 공통적으로 드러나 전체적으로 박력있는 남성의 체구를 연상시킨다. 넓적한 사각형의 얼굴, 특히 두꺼운 입술의 표현은 ○○ 가흥동 마애여래삼존상 및 여래좌상(보물), ○○ 석교리 ○○○○○ 등과 유사한 것으로 지역적인 공통성으로 이해할 수 있다.","a":"영주 영주동 석조여래입상","c":"보물","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620107.jpg"},{"q":"○○○는 신라에 불교가 처음 전해질 당시 전설에 나오는 아도(阿度)화상과 관련이 있는 절이다. 아도가 불교를 전파하기 위하여 서라벌에 갔다 돌아오는 길에 한겨울인데도 복숭아꽃과 오얏꽃이 만발하여 그곳에 절을 짓고 ○○○라 하였다 한다. 정확하게 언제 세워졌는지 알 수 없으나 신라 최초의 절이라고 전한다. 이 ○○은 대웅전 앞뜰에 있으며, 전체적으로 5개층을 이루고 있는데, 맨 아래층은 탑을 받치는 역할을 하는 기단(基壇)으로 여겨진다. 위의 2개 층은 탑의 중심부분인 탑신부(塔身部)이다.","a":"구미 도리사 석탑","c":"보물","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621039.jpg"},{"q":"경북 ○○시에 있는 신라 시대의 고분군. 본래 사적 ○○노동리고분군(慶州路東里古墳群), 사적 ○○노서리고분군(慶州路西里古墳群), 사적 ○○황남리고분군(慶州皇南里古墳群), 사적 ○○황오리고분군(慶州皇吾里古墳群), 사적 ○○인왕리고분군(慶州仁旺里古墳群)으로 분리되어 있었으나, 2011년 7월 28일 국가유산청이 역사성과 특성을 고려하여 ○○ 평야 한복판에 서로 인접해 있는 신라 시대의 고분군을 통합하여 재지정하였다.","a":"경주 대릉원 일원","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2020042413105800.JPG"},{"q":"공주시 ○○○릉에서 출토된 백제의 금으로 만든 왕관(王冠) 꾸미개(장식) 한쌍이다. 높이는 각각 30.7㎝, 29.2㎝이고, 너비는 각각 14㎝, 13.6㎝이다. 1971년 ○○○릉이 발견·조사되었을 때, 왕의 널(관) 안쪽 머리 부근에서 포개진 상태로 발견되었다. 금판을 뚫어서 덩굴 무늬를 장식했으며, 밑으로는 줄기가 있는데 아래위로 2~3개의 작은 구멍이 있어 무엇인가에 부착할 수 있도록 해 놓았다. 좌우로 벌어진 줄기 중간에는 꽃 무늬를 배치하였으며, 줄기가 길게 연장되면서 마치 불꽃이 타오르는 듯한 모양새를 보여준다.","a":"무령왕 금제 관식","c":"국보","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612272.jpg"},{"q":"신라 혜공왕 9년(733)에 법조가 영남사의 부속암자로 창건하였다고 전해지는 ○○○의 대웅전에 모셔진 높이 0.97m의 불상이다. 네모진 얼굴에 가는 눈과 입, 넓적한 코, 짧은 목 등이 다소 평판적으로 표현되기는 했으나 단정한 인상을 풍긴다. 어깨는 넓고 둥근 편으로 가슴이 다소 움츠러들어 보인다. 양 어깨에 걸쳐 입은 옷은 너무 두꺼워서 옷주름과 신체의 굴곡을 나타내지 못하고 있다. 부처의 몸에서 나오는 빛을 형상화한 광배(光背)는 2줄의 볼록한 선으로 머리광배와 몸광배를 구분하고, 그 안에 덩굴무늬와 연꽃무늬를 새겨 넣었다.","a":"밀양 무봉사 석조여래좌상","c":"보물","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622727.jpg"},{"q":"○○란 도자기, 기와, 그릇을 굽던 가마터를 말한다. 월출산 남서쪽의 남송정마을로 들어가는 우측 구릉에 있다. 이 곳에서 2기의 가마터가 발굴되었는데, 가마는 길이 4.7m, 폭 2.3m의 반지하식으로 아래부분은 넓고 위로 갈수록 좁아지는 모양을 하고 있다. 회흑색 토기 조각을 비롯해 다양한 용도와 모양의 자기들이 발견되었다. 대체로 10세기 전반을 중심으로 하는 시기에 제작활동을 하였던 것으로 보인다. ○○○○○는 통일신라시대에서 고려시대로 옮겨가는 전환기의 가마터이다.","a":"영암 구림리 요지","c":"사적","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627154.jpg"},{"q":"○○○○는 사찰 입구에 세워두는 것으로, 절에서는 행사나 의식이 있을 때 당이라는 깃발을 달아두는데, 깃발을 걸어두는 길쭉한 장대를 당간이라 하며, 당간을 양쪽에서 지탱해 주는 두 돌기둥을 ○○○○라 한다. 이 ○○○○는 지금은 세검정초등학교가 들어서 있는 장의사의 옛터에 동서로 마주 서 있다. 장의사는 백제와의 싸움으로 황산(지금의 논산으로 추정)에서 전사한 신라의 장수 장춘랑과 파랑(罷郞)의 명복을 빌기 위해 신라 무열왕 6년(659)에 세웠다고 전한다.","a":"서울 장의사지 당간지주","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613220.jpg"},{"q":"경상북도 안동 지방에서 의병활동을 전개한 ○○○○○이 사용하던 칼이다. ○○○은 1962년 건국훈장 독립장이 추서된 인물로 이 칼은 후손이 1985.1.24.독립기념관에 기증하였다. 칼에 “三寅劍”, 칼집에 “倡義劍”이라 각인되어 있으며 나무칼집은 후대에 제작된 것으로 추정된다. ○○○은 1896년 2월 유시연과 함께 영양·안동 지방의 의병을 모아 청량산에서 기병하였고 봉화와 영주를 점령하여 군수가 바치는 군기(軍器)로 무장하고 안동으로 진군하였으며 청송·의성·영덕·영해를 순방하며 의병 봉기를 촉구하였다.","a":"의병장 김도현 칼","c":"국가등록문화유산","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668641.jpg"},{"q":"갈항사(葛項寺) 터에 있는 높이 1.22m의 불상으로 군데군데 파손이 심한 상태이다. 둥근 얼굴에 신비스런 미소를 띠고 있으며 눈·코·입의 표현이 사실적이다. 가슴이 당당하고 허리가 잘록하며, 왼쪽 어깨를 감싼 옷은 굴곡있는 신체에 밀착되어 부드러운 옷주름 선을 나타내고 있다. 오른손은 손바닥을 무릎에 대고 아래를 가리키고 있지만, 오른 손목과 손등 뿐이며 왼손도 일부 깨졌다. 불상이 만들어진 시기는 갈항사 3층석탑의 건립 연대인 경덕왕 15년(758) 무렵일 것으로 추정된다.","a":"김천 갈항사지 석조여래좌상","c":"보물","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620646.jpg"},{"q":"○○○○은 유물·유적의 보고(寶庫)라고 할 수 있는데, 여기에 가면 삼국시대부터 통일신라 후기까지의 불상들을 모두 만나볼 수 있다. 그 중에 하나인 높이 1.4m의 마애보살상은 칠불암(七佛庵) 위에 곧바로 선 남쪽바위에 새겨져 있다. 마치 구름 위에 앉아 있는 것처럼 보이는데 머리에 삼면보관(三面寶冠)을 쓰고 있어서 보살상임을 알 수 있다. 얼굴은 풍만하고, 지그시 감은 두 눈은 깊은 생각에 잠긴 모습으로 구름 위의 세계에서 중생을 살펴보고 있는 듯하다. 오른손에는 꽃을 잡고 있으며, 왼손은 가슴까지 들어 올려서 설법하는 모양을 표현하고 있다.","a":"경주 남산 신선암 마애보살반가상","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620517.jpg"},{"q":"이 항아리는 전체가 검은 색조를 띠고 있으며 정확한 용도는 알 수 없으나, 감로준(甘露樽)이라는 이름이 전하고 있는 점으로 보아 사찰의 불교 용기였다고 추측된다. 높이 55㎝, 구경의 지름 19.5㎝, 몸지름 31㎝로 뚜껑 모서리 부분은 둥글게 표현하였고 위로 6장의 연꽃잎과 十자형으로 된 불꽃 모양의 화려한 손잡이가 위로 돌출되어 달려있다. 어깨는 넓고 밑에 굽이 달린 항아리로 몸체의 좌우에는 손잡이 구실을 하는 굵은 고리가 달려 있다. 높이 33.5cm의 몸체 위로 납작한 뚜껑이 덮히고 중간에 특이한 뉴(鈕)가 장식된 점이 주목된다.","a":"청도 운문사 동호","c":"보물","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620594.jpg"},{"q":"『○○○○○』은 19세기 전반의 전예 명필 기원 ○○○가 칠언ㆍ오언ㆍ사언대구를 다양한 ○○풍으로 쓴 것이다. 동한시대(東漢時代)의 ○○비로 유명한 <예기비(禮器碑)>ㆍ<을영비(乙瑛碑)>ㆍ<사신비(史晨碑)>ㆍ<장천비(張遷碑)>ㆍ<조전비(曺全碑)>ㆍ<하승비(夏承碑)>의 다양한 필의가 보이고 있어 ○○○가 한예(漢隸)의 대부분을 넓게 배웠음을 보여주는 수작(秀作)이다. 또 고문(古文) 풍으로 쓴 전서도 함께 실려 있다. 기년작은 아니지만 무르익은 필치를 느낄 수 있다.","a":"유한지 예서 기원첩","c":"보물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1623010.jpg"},{"q":"괘불이란 절에서 큰 법회나 의식을 행하기 위해 법당 앞 뜰에 걸어놓고 예배를 드리는 대형 불교그림인데, 이 괘불은 ○○○○을 중심으로 하여 12대 보살, 10대 제자 등 여러 무리들이 그려진 그림이다. ‘원만보신○○○○’이란 명칭이 머리광배에 기록되어 있으며 신체에 비해 두 손을 크게 강조하여 ○○○○이 주존임을 뚜렷이 나타내주고 있다. 보관과 가슴에 달린 장식, 옷의 문양, 매듭 등이 화려함을 보여준다. 이 불화는 신원사 ○○○○○과 같은 그림인데, 십이대보살, 십대제자, 사천왕상 등이 ○○○○ 주위를 에워싸고 있어 조금 더 복잡해진 모습이다.","a":"수덕사 노사나불 괘불탱","c":"보물","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618035.jpg"},{"q":"지리산 서쪽 기슭에 자리잡고 있는 조선시대 후기의 집으로 연당 박동식(蓮堂 朴東式, 1753~1830)이 세웠다고 한다. 산골짜기에 자리잡고 있으나, 주변에 넓은 들이 있어서 그리 척박하지는 않다. 집은 트인 ㅁ자형으로 경사진 곳에 사랑채와 중문채의 높이를 서로 다르게 하여 배치하였다. 솟을대문이 우뚝 선 대문채는 서쪽칸에 마루를 깔았고, 동쪽에는 방 2칸과 마루 1칸이 있다. 대문간채의 동쪽에는 연당이 있고, 북쪽에는 4칸의 행랑채가 있다. 행랑채의 북쪽, 높이 쌓은 대 위에 사랑채가 있다.","a":"남원 몽심재 고택","c":"국가민속문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634539.jpg"},{"q":"화엄종의 주불인 비로자나불을 대신하여 ○○○○이 영취산에서 설법하는 장면인 영산회상을 그린 괘불이다. 괘불이란 절에서 큰 법회나 의식을 행하기 위해 법당 앞뜰에 걸어놓고 예배를 드리는 대형 불교그림이다. 전체 1,082.6×650.6㎝, 화면 951×611.3㎝크기의 이 괘불은 ○○○○이 단독으로 중생을 설법하는 모습으로, ○○○○을 중심으로 좌우에는 10대보살과 10대제자, 사천왕 등이 그려져 있다. 단독으로 그려진 ○○○○은 화면을 가득 채우고 있으며, 손은 신체에 비해 큰 편으로 손바닥을 들어올려 설법하는 모습의 손 모양을 하고 있다.","a":"신원사 노사나불 괘불탱","c":"국보","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612317.jpg"},{"q":"전라남도 ○○군 ○○○ 영산강 구릉에서 발견된 ○○○시대의 무덤 유적에서 출토된 유물이다. 출토된 ○○○ 유물 중 세형동검(청동검) 3점·청동팔령두 2점·청동쌍령구 2점·청동손칼(청동삭구) 1점·청동도끼(청동공부) 1점·잔무늬거울(청동세문경) 2점이 국보로 지정되었다. 세형동검은 양 끝에 날이 서 있으며, 그 중 1점은 칼날 부분이 손상되어 있다. 동검 중앙에 굵게 나온 등대의 모습이 칼마다 다른 것이 특징이며, 한국에서 출토되는 동검으로는 시대가 늦은 편이다. 청동팔령구는 8각형의 별모양으로 생겼으며, 각 모서리에 방울이 달려 있다.","a":"화순 대곡리 청동기 일괄","c":"국보","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612004.jpg"},{"q":"패총은 조개껍질과 생활 쓰레기가 함께 버려져 쌓여 있는 곳으로, ‘조개더미’라고도 하며 당시 생활모습을 알 수 있는 장소이다. 봉황대 언덕 근처에 서로 시기가 다른 회현리 조개더미와 다양한 무덤유적이 있다. 회현리 조개더미에서 출토된 유물로는 토기, 뼈·뿔도구, 석기, 가락바퀴(방추차), 불탄쌀(탄화미), 중국 화폐인 화천, 동물뼈 들이 나왔다. 토기는 적갈색이나 회청색을 띠며, 사슴뿔이나 뼈를 가공해 만든 칼자루가 많다. 불탄쌀은 고대의 쌀과 농경 연구에 큰 도움을 주는 중요한 자료이다.","a":"김해 봉황동 유적","c":"사적","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628116.jpg"},{"q":"「○○○○」는 조선시대 향교의 기능에 따른 건물과 배치구성, 지방행정체계에 대한 설위형식이 지역별로 시기적 변화양상이 있었음을 밝힐 중요한 건축사적 특성을 가진 건물임. ○○․○○는 건축 연혁이 명확하고 조선중기에 중창된 뒤 위치의 변경이 없으며, 대체적으로 당시의 구조양식 등 원형을 잘 간직하고 있음. 특히 정형화되고 엄격한 배치구성이 돋보이며, 문묘 다음으로 큰 규모이며, 경사 지형을 고려한 탁월한 입면구성을 갖추고 있음.","a":"상주향교 대성전‧동무‧서무","c":"보물","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2020122910360900.jpg"},{"q":"○○○에 모셔져 있는 나무로 만든 관음보살좌상으로, 머리에는 화염보주로 호화롭게 꾸민 보관을 쓰고 있는데, 관의 가운데에는 작은 부처가 새겨져 있고, 배 부분에는 복갑(腹甲)같은 둥근 꽃장식 판을 두르고 있어서 전반적으로 장식성이 두드러져 보인다. 네모꼴에 가까운 얼굴은 근엄한 표정을 짓고 있으며, 오른손은 가슴에 올리고 왼손은 배에 두었으며 엄지와 중지를 맞댄 손모양을 하고 있는데, 마치 실제 인물의 부드러운 손을 대하듯 곡선적이고 사실적으로 표현되어 생동감이 넘쳐난다.","a":"보은 법주사 목조관음보살좌상","c":"보물","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617286.jpg"},{"q":"○○은 큰 돌을 세워 놓은 것으로 선돌이라고도 하며, 고인돌이 있는 지역에서 자주 볼 수 있다. ○○○에서 선돌을 세운 주위로 석축을 네모난 형태로 둘러 쌓아 놓았고, 선돌 앞에서 제사의식을 지낸 것으로 짐작된다. 선돌 주위에는 고인돌이 여러 기 남아있다. 주변지역은 주택이 많이 들어서 있으나, 유적 보존을 위해 선돌 지역을 발굴조사하여 정비하였다. 고인돌과 선돌의 관계 및 서로의 기능적 성격을 통해 고대 문화 연구에 좋은 자료가 되는 유적이다.","a":"대구 진천동 입석","c":"사적","nc":"","r":"대구광역시","s":"달서구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625162.jpg"},{"q":"ㅇ 가마구조 : 계단식 칸 가마(12칸) ㅇ 가마길이 : 전체 길이 27m (너비 2~3m) ㅇ 가마경사 : 22 ~ 25˚ ㅇ 1949년 초축된 칠기가마를 1962년 개축한 12칸 계단식 칸가마로서, 벽체 및 천정을 벽돌(봉통부는 망생이)로 축조하였으며 외부는 점토를 발라 마감하였다. ㅇ 길이가 약 27m로 길고 칸수가 12칸으로 많은 것이 특징인데 내벽 폭이 1번 칸은 1.65m, 12번 칸은 3m로 뒤로 올라갈수록 넓어지는 구조이며, 아궁이에서 굴뚝을 바라보아 오른쪽으로 각 칸마다 출입구 1개, 불보기 창이 1개씩 설치되어 있다.","a":"이천 수광리 오름가마","c":"국가등록문화유산","nc":"","r":"경기도","s":"이천시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2016022417043500.JPG"},{"q":"1939년 건립 이 건물은 1937년에 충북 도청 본관이 건립됨에 따라 인접 지역에 지어진 도지사 ○○이다. 중복도를 기준으로 건물 전면은 양식으로 후면은 일식으로 구성하고 외부 접견실과 주 생활 공간을 구분하였다. 접객 공간의 외부에는 서양식 창호가 설치되었고, 생활 공간에는 다다미, 미닫이 창호가 설치되었다. 지붕은 각각 처마 높이가 다른 모임지붕 형태로 되어 있다.","a":"청주 충청북도지사 구 관사","c":"국가등록문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668528.jpg"},{"q":"이 건물은 대구 지역 부호인 서병국의 주택으로 건립되었다. 전체적으로 중앙 현관을 중심으로 좌우 대칭형이며, 현관의 포치(porch)는 반원형 아치로 장식해 정면성을 강조하였다. 붉은 벽돌을 쌓아 벽체를 만들고 건물 외벽 네 모서리, 외벽 상부, 창호 상‧ 하인방 등에 흰색 화강석을 사용하여 화려하게 꾸몄다. 대구 지역의 대표적인 근대 건축물로 현재 ○○○○○ 사무실로 쓰고 있다.","a":"대구화교협회","c":"국가등록문화유산","nc":"","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667795.jpg"},{"q":"조선시대 ○○○과 ○○○ 비(妃) 유씨, 그리고 궁중의 정5품 ○○이 입었던 의복 4점이다. 1965년 해인사 장경판고(藏經板庫)를 수리할 때 남쪽 지붕 아래 구멍에서 건물 완공에 대한 기록과 ○○의 이름이 적힌 명단이 이 의복들과 함께 발견되었다. 이때 발견된 의류는 담청색 직령 1점, 백삼 1점, 홍삼 1점, 자주저고리 1점 등 4점이다. 이 의복들은 재봉질 못지 않은 정교한 바느질 솜씨를 보여주고 있는데, 당시 세련되었던 바느질법의 한 단면을 보여 주고 있으며, 조선 중기의 의복 습관을 잘 나타내고 있어 복식 연구에 중요한 자료가 되고 있다.","a":"광해군 내외 및 상궁 옷","c":"국가민속문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635752.jpg"},{"q":"조선 후기의 성리학자이자 문신인 ○○의 ○○이다. 이 ○○ 상은 심의(深衣)를 입고 정자관(程子冠)을 쓴 뒤 두 손을 공수(拱手)한 채 정면을 바라보고 있는 반신상인데, 눈부시게 수려한 용모를 실로 뛰어난 화법으로 묘사하고 있을 뿐만 아니라, 화면 상부에 경산(京山) 이한진(李漢鎭, 1732 ~ 1815)과 기원(綺園) 유한지(兪漢芝, 1760 ~ 1834) 등 당대 명필들의 미려한 찬문(贊文)이 조화롭게 어우러져 있어 조선 후기 연거복(燕居服) ○○화의 가장 아름다운 걸작 가운데 하나로 일컬어진다.","a":"이채 초상","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614871.jpg"},{"q":"이 비석은 묵재(黙齋) 이문건(李文楗)이 부친인 ○○○의 묘를 모친인 고령(高靈) 신씨(申氏)의 묘와 합장하면서 1536년에 묘 앞에 세운 묘비이다. 이 묘비에는 앞면과 뒷면에 각각 묘주의 이름과 그 일대기가 새겨져 있고, 왼쪽과 오른쪽에도 한글과 한문으로 경계문이 새겨져 있다. 이 비석의 특징적 가치는 비석 왼쪽 면에 쓰여진 한글 경고문인데, 우리나라 비문으로서는 한글로 쓰인 최초의 묘비문으로 알려져 있어 그 역사적 가치가 높으며 국어사에 중요한 자료가 된다. 이 ‘○○○○’는 국어생활사에서 다음과 같은 중요한 가치를 지닌다.","a":"서울 이윤탁 한글영비","c":"보물","nc":"","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614890.jpg"},{"q":"진공대사의 사리를 모셔놓은 탑과, 그 옆에 놓여있는 돌로 만든 함이다. 본래는 강원특별자치도 ○○의 흥법사터에 있었으나 1931년 경복궁으로 옮겨 왔으며 현재는 국립중앙박물관 경내에 있다. 진공대사는 통일신라말 ·고려초에 활약한 승려로, 당나라에 유학하고 돌아와 신라 신덕왕의 스승이 되었으며, 특히 고려 태조의 두터운 존경을 받았다. 탑은 전체가 8각으로 이루어진 기본적인 형태로, 기단(基壇)의 아래와 윗받침돌에는 연꽃을 새겼다. 북모양을 하고 있는 가운데받침돌 표면에는 웅장한 구름과 함께 뒤엉켜 있는 용의 몸체를 생동감있게 조각하였다.","a":"원주 흥법사지 진공대사탑 및 석관","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613319.jpg"},{"q":"통일신라시대 만들어진 높이 36.8㎝, 밑지름 21.5㎝의 ○○이 박힌 ○○제 ○○ 한 쌍이다. 전체적인 형태는 6장의 꽃잎 모양을 한 받침이 기둥 줄기를 사이에 두고 아래위로 놓여 있다. 아래 받침에는 꽃 모양의 고리로 고정시킨 6개의 짐승 모양의 다리가 받치고 있다. 윗받침의 중앙에는 짧은 줄기가 솟고 그 위에 이중의 꽃잎으로 이루어진 반원 모양의 받침이 있으며, 위쪽으로는 원통형의 초꽂이가 있다. 받침대 표면에는 양각과 음각의 수법으로 조각을 하였고 곳곳에 ○○을 박아 ○○하였는데, 지금은 많이 없어지고 도금이 벗겨진 곳도 있다.","a":"금동 수정 장식 촛대","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611632.jpg"},{"q":"현존하는 김애립(金愛立)의 작품 가운데 가장 뒤늦은 시기인 1698년에 제작된 작품이지만, 그의 작품 중에서 가장 뛰어난 역량을 보여주는 대표작으로 평가된다. 종신의 전체적인 외형은 상부가 좁고 아래로 가면서 점차 넓게 벌어져 여수 흥국사 ○○과 유사하며, 용뉴는 쌍룡(雙龍)으로 구성되었다. 연곽대와 연곽대 사이에는 4구의 보살입상이 유려한 모습으로 부조되었고, 종신 한쪽에는 왕실의 안녕을 기원하는 전패(殿牌)가 마련되었다.","a":"고흥 능가사 동종","c":"보물","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619993.jpg"},{"q":"비봉산 정상(높이 431m)에서 서남쪽으로 뻗어 내려온 구릉의 경사면에 있는 무덤이다. 무덤의 외형은 둥글고 내부는 널방(현실)과 그 방에서 입구를 연결하는 널길(연도)로 이루어진 굴식돌방무덤(횡혈식석실분)이다. 널방은 4각형으로, 크기는 동·서 약 3.5m, 남·북 약 2m, 높이 약 2m이다. 벽에서 천장으로 갈수록 좁아지며 천장은 2장의 돌이 나란히 덮혀 있다. 천장을 제외한 모든 벽면에는 채색화가 그려져 있다.","a":"영주 순흥 벽화 고분","c":"사적","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627889.jpg"},{"q":"○○○○○는 원형철근을 약 20cm 내외 간격으로 배치하여 약 90cm 두께의 철근콘크리트 벽체를 형성하였고, 총구의 크기 및 모양은 수평으로 긴형과 정방형 등 다양하며 총구의 형상은 바깥쪽에 비하여 안쪽이 크고 넓다. 남북 간의 대립과 갈등이 첨예화되던 1948년경 남북 대치국면에서 발생할 수 있는 만일의 사태에 대비하여 남측에서 구축한 시설물로 6·25 전쟁당시 교전 흔적이 남아 있는 등 역사적 가치가 높다.","a":"포천 방어벙커","c":"국가등록문화유산","nc":"","r":"경기도","s":"포천시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2135550.jpg"},{"q":"세브란스병원에서 에비슨이 한국인 조수 박서양의 도움을 받아 수술하는 장면을 담은 ○○○○○으로 대한제국기 당시의 수술실, 수술도구, 수술인력, 수술복장 등을 보여주는 희귀한 사진의 원판○○이라는 점에서 사료적 가치가 크다. 에비슨(O. R. Avison, 1860-1956)은 캐나다 토론토 의대를 졸업한 북장로교 선교의사로 1893년 7월부터 제중원에서 진료를 시작하여, 제중원을 세브란스병원과 세브란스의학전문 학교로 확대 개편하는 등 우리나라에 근대서양의학이 도입·보급되는 데 중요한 기틀을 마련한 인물이다.","a":"에비슨의 수술장면 유리건판 필름","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667303.jpg"},{"q":"○○○○○은 줄여서 ‘법화경’이라고 부르기도 한다. '법화경'은 부처가 되는 길이 누구에게나 열려 있음을 기본사상으로 하는 우리나라 천태종의 근본경전이다. 또한 '법화경'은 화엄경과 함께 우리나라 불교사상의 확립에 가장 크게 영향을 끼쳤으며, 삼국시대이래 가장 많이 유통된 불교경전이다. 이 책은 후진의 구마라습(鳩摩羅什)이 번역한 것을 고려 충숙왕 17년(1330)에 이신기가 옮겨 쓴 것이다. 병풍처럼 펼쳐서 볼 수 있는 형태로 되어 있으며, 접었을 때의 크기는 세로 28.3㎝, 가로 10.1㎝이다.","a":"감지은니 묘법연화경","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611794.jpg"},{"q":"○○○○○수다라요의경은 줄여서 ‘○○○○○경’또는 ‘원각경’이라고 부르기도 한다. 이 경전은 훌륭한 이론과 실천을 말하고 있어 널리 유포되어 불교 수행의 길잡이가 되었다. 우리나라에서는 고려의 지눌이 깊이 신봉하여 ‘요의경’이라 한 뒤 널리 읽혀진 경전이다. 이 책은 당나라의 불타다라(佛陀多羅)가 한문으로 번역한 ○○○○○수다라요의경을 당나라 종밀(宗密)이 알기 쉽게 풀이하여 주석(註釋)을 붙인 것이다. 책 첫머리에는 당나라 배휴(裴休)가 쓴 서문(序文)이 있다.","a":"대방광원각약소주경 권상(1991)","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614491.jpg"},{"q":"1912년 건립 이 건물은 일제강점기 당시 해군 진해기지에 건립된 ○○ 건물로, 최근까지 의료원 본관으로 사용되었다. ‘ㄷ’자형 평면을 기본 구조로 하여 전면 돌출부에 박공 형태의 페디먼트를 화강석으로 구성하였고, 쌍으로 된 창의 가운데 위쪽에 장식을 넣었다. 현관부는 사각 기둥 및 화강석과 붉은 벽돌이 혼용된 아치로 장식하였고, 붉은 벽돌을 이용하여 벽체를 정교하게 쌓는 등 짜임새 있는 입면을 구성하였다.","a":"구 진해요항부 병원","c":"국가등록문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669413.jpg"},{"q":"자연암벽에 신체를 선으로 새기고 머리는 따로 올려놓은 전체 높이 12.38m의 거구의 불상이다. 이러한 형식의 불상은 고려시대에 많이 만들어졌는데, 파주 용미리 마애이불입상(보물)도 이와 거의 같은 수법을 보여준다. 머리의 뒷부분은 거의 파손되었으나 앞부분은 온전하게 남아 있다. 머리에는 상투 모양의 머리(육계)가 높이 솟아 있고, 얼굴에는 자비로운 미소가 흐르고 있어 거구의 불상임에도 전체적인 형태는 자연스럽다. 머리와 얼굴 특히 입에는 주홍색이 남아 있어서 원래는 채색되었음이 분명하다.","a":"안동 이천동 마애여래입상","c":"보물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620217.jpg"},{"q":"1921년에 건립되어 캐나다장로교회 한국선교사들의 사택으로 활용된 건물로 한국기독교장로회의 역사를 잘 말해주는 건물이다. 이 시기 주거건축이 많이 남아있지 않아 희소가치가 높고, 유신시절 민주화 인사들의 중요한 활동 근거지이기도 하다. 내부는 칸막이 등 변형이 이루어졌지만, 그 원형이 잘 보존된 근대건축물이다.","a":"서울 한국기독교장로회총회 선교교육원","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1666981.jpg"},{"q":"○○○○○는 조선 태조 이성계가 그의 후궁에게서 난 딸을 뒤에 ○○○○로 봉하고 집을 하사한다는 내용의 분재기(分財記)이다. 8행으로 되어 있으며, 원문이 끝난 후 간격을 크게 비워 두고 ‘태상왕’이라 적었으며, 그 아래에 태조의 수결(지금의 서명)이 있다. 내용은 모두 이두문(吏讀文)으로 되어 있는데 집터, 집의 방향, 집을 짓는데 쓰이는 재목, 가옥의 배치, 건물의 칸수 등을 구체적으로 적고, 끝에는 자손이 영원히 거주할 것을 밝혀 두고 있다. 조선조 최초의 가옥급여문서로 조선 전기 가옥과 토지 등 재산에 대한 법제도 연구의 귀중한 자료로 평가된다.","a":"숙신옹주 가옥허여문기","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613395.jpg"},{"q":"‘○○○○○’은 일본식 가옥에 서양의 주거 공간(응접실 등)이 절충된 형식으로 1936년 최초 건립된 이후, 한국전쟁 기간 중인 1952년에 소아과 전문병원으로 개원하여 1980년대까지 계속해서 사용되었던 곳으로 오늘날 지역민들의 기억 속에 당시의 흔적이 온전히 남아 있는 등 지역의 근대문화유산적 측면에서 가치가 높다.","a":"군산 구 십자의원","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2019090513430800.jpg"},{"q":"원(元)편으로 중국 고대 반고씨부터 고신씨까지 그리고 당나라 천복 1년(901)에서 송(宋)나라 상흥 2년(1279)까지의 사적을 기록한 역사서이다. 이 책은 원나라 1361년에 중국에서 발간된 적이 있고, 그후 60년만에 우리나라에서 찍어냈다. 이 책의 크기는 가로 18.3㎝, 세로 29.2㎝이다. 판본은 권말에 있는 변계량의 주자발(鑄字跋)에 의하면, 세종 2년(1420) 11월에 공조참찬 이천에게 명하여 새로운 활자를 만들어서 인쇄한 경자자본으로서 세종 4년(1422)에 간행된 것이며, 서, 목록, 서례는 계미자이다.","a":"통감속편","c":"국보","nc":"","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612932.jpg"},{"q":"○○○시 대정읍성 동문자리 안쪽에 자리잡은 추사○○○는 조선 후기의 문신이자 서화가였던 추사 ○○○가 유배생활을 하던 곳이다. ○○○는 영조의 사위였던 김한신(金漢藎)의 증손으로, 조선 순조 19년(1819) 문과에 급제하여 성균관 대사성·이조참판 등의 벼슬을 지냈다. 그러다 조선 헌종 6년(1840) 55세 되던 해에 동지부사로 임명되어 중국행을 앞두고 안동김씨 세력과의 권력 싸움에서 밀려나 제주도로 유배되었다. 유배 초기에 포도청의 부장인 송계순의 집에 머물다가 몇 년 뒤 현재의 ○○○로 지정된 강도순의 집으로 이사하였다.","a":"서귀포 김정희 유배지","c":"사적","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628624.jpg"},{"q":"지례리 천곡의 서북쪽에서 뻗어내린 산세에 의지하여 반변천이 바라보이는 곳에 동남향으로 자리잡은 조선 후기의 주택이다. 조선 숙종 때 대사성을 지낸 지촌의 셋째 아들 김원중이 천곡에 분가할 때 지은 것이다. 안채는 1700년대에 지은 것으로 보이며, 사랑채는 1920년에 크게 고쳐지은 것이다. 임하댐 건설로 인하여 1990년 지금의 위치로 옮겨지었다. 안채와 사랑채·대문간채 등이 튼 'ㅁ'자모양을 이루고 있다. 안채 오른쪽에 방앗간채가 있고 사랑마당 왼쪽 한켠에는 외양간을 두었으며, 담밖 뒷쪽 낮은 언덕에 사당을 마련하였다.","a":"안동 오류헌 고택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635486.jpg"},{"q":"보물 ○○○○○은 1663년(현종 4)에 제작된 마애불로서, 경북 ○○○ 옥석대(백운대라고도 함)에 위치해 있다. 제작시기와 주관자에 대해서는 풍계 명찰(楓溪 明察, 1640-1708)의 문집『풍계집(楓溪集)』에 수록된 「환적당대사행장(幻寂堂大師行狀)」을 통해 확인된다. 명찰은 17세기 승려 환적당 의천(幻寂堂 義天)의 제자로 이 책에 환적당이 주관해 마애불을 조성한 사실이 기록되어 있다. 환적당 의천은 1630년 경북 선산에서 태어나 11세에 출가하여 88세 되던 1690년에 해인사 백련암에서 입적했다.","a":"문경 봉암사 마애미륵여래좌상","c":"보물","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2021010617453300.jpg"},{"q":"고려시대 만들어진 ○○○○로 높이 9.3㎝, 아가리 지름 16.1㎝, 밑지름 6.1㎝ 이다. 바닥면 근처에서 거의 수평으로 퍼졌다가 다시 비스듬히 벌어져 올라간 넓적한 ○○로, 안바닥이 평평하며 두께가 얇아 청동제 ○○ 같이 날렵하게 생겼다. 아가리 끝의 여섯 군데에 조금씩 홈을 내어 여섯 잎의 꽃과 같은 모양을 하고 있다. 이것은 고려 초기의 특징적인 꽃무늬 ○○에서 퇴화된 것으로 생각된다. 그릇 내면에는 마치 비단에 무늬를 넣은 듯, 섬세하고 정교한 최상급의 양각문양들이 새겨있다.","a":"청자 양각연지어문 화형 접시","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614386.jpg"},{"q":"○○○○○의 대웅전 지역과 극락전 지역을 연결하고 있는 무지개 모양의 다리로, 규모는 폭 3m, 길이 14.3m, 다리 중앙부의 높이는 5.4m이다. 사적기에 따르면 ○○○는 신라 법흥왕 7년(서기 520년)에 아도 스님에 의해 원각사(圓覺寺)라는 이름으로 창건되었다. 이후 신라 말 도선 국사가 중수한 뒤 절의 서쪽에 봉황새 모양의 돌이 있다고 하여 서봉사(西鳳寺)라 하였으며, 고려 공민왕 7년(1358년)에는 나옹 스님이 중수하면서 다시 ○○○라 이름하였다.","a":"고성 건봉사 능파교","c":"보물","nc":"","r":"강원특별자치도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616868.jpg"},{"q":"○○ 정혜사터에 세워져 있는 탑으로, 흙으로 쌓은 1단의 기단(基壇) 위에 13층의 탑신(塔身)을 올린 모습인데, 통일신라시대에서는 그 비슷한 예를 찾아볼 수 없는 독특한 모습이다. 1층 탑몸돌이 거대한데 비해 2층부터는 몸돌과 지붕돌 모두가 급격히 작아져서 2층 이상은 마치 1층탑 위에 덧붙여진 머리장식처럼 보인다. 큰 규모로 만들어진 1층 몸돌은 네 모서리에 사각형의 돌기둥을 세웠으며, 그 안에 다시 보조기둥을 붙여 세워 문을 만들어 놓았다. 이렇듯 문을 마련해 놓은 것은 열린 공간을 추구하고자 한 의지의 표현으로 보여진다.","a":"경주 정혜사지 십삼층석탑","c":"국보","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612780.jpg"},{"q":"○○○의 마애불좌상 옆에 있던 것을 1966년 경북대학교로 옮겨다 놓은 것이다. 높이 1.6m 가량에 상반신은 깨져 없어지고, 하반신과 다른 돌로 만든 둥근 연꽃무늬 발받침대만이 남아 있지만, 우수한 조각기법으로 만들어진 작품이다. 상반신은 옷을 벗은 듯 하고 하체에 표현된 옷은 매우 얇다. 왼쪽 무릎 위에 올려 놓은 오른쪽 다리는 매우 크고 무릎을 높이 솟게 하여 강조하고 있다. 올려 놓은 다리 밑에는 3단으로 옷주름이 부드럽게 흐르는데 그 선이 분명하다. 이들 옆에는 커다란 사각형의 고리와 화려한 구슬 장식이 있다.","a":"봉화 북지리 석조반가상","c":"보물","nc":"","r":"대구광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615266.jpg"},{"q":"이 ○○○○○는 구연부가 직립하며 좁아지고 어깨가 넓고 저부가 좁아지다가 넓어져 접지면에 이르는 기형이 조선 전기의 특징을 보여준다. 몸통 전면에 활기차게 그려진 보상당초문 역시 조선전기 청화○○ 도안의 특징을 보여주고 있는데, 청화발색은 고르지 않다. 백토는 순결한 백색으로 유층은 빙렬이 없는 담청을 띠는 투명유이다. 당당한 호의 형태와 적절히 포치된 보상당초문의 표현 등이 조선전기 청화○○ 연구에 또 다른 학술적 연구의 일면을 제공하기에 충분한 작품이다.","a":"백자 청화보상당초문 항아리","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614850.jpg"},{"q":"○○광역시 광산구 ○○○ 영산강 유역 낮은 평야지대에 자리한 초기 철기시대의 늪과 못터, 토기가마터, 배수시설, 독무덤(옹관묘) 등 고대 농경문화와 생활유적이 있는 곳이다. 독무덤은 53기가 발견되었고, 그 안에서 토기와 철기류 유물이 출토되었다. 이 지역 독무덤은 영산강 유역 삼국시대 독무덤 계보가 선사시대까지 올라가는 것을 보여주는 것으로 그 가치가 크다. 늪과 못터에서 토기, 목제, 석기 등의 유물이 나왔는데, 특히 빗, 괭이, 나무 뚜껑과 같은 목제유물들은 당시 생활모습을 알려 준다는 점에서 가치가 크다.","a":"광주 신창동 유적","c":"사적","nc":"","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625348.jpg"},{"q":"○○○은 조선시대 역대 임금의 초상을 봉안하고 제사를 지내는 건물로 궁궐 밖으로는 종묘를 두었고, 궁 안에는 ○○○을 두었다고 한다. 원래 춘휘전이란 건물로 조선 효종 7년(1656) 경덕궁의 경화당을 옮겨지은 것으로, 숙종 21년(1695)에 ○○○으로 이름을 바꾸었다. 이곳에는 숙종·영조·정조·순조·익종·헌종의 초상을 모시고 있다. 1921년 ○○○ 후원 서북쪽에 ○○○을 새로 지어 왕의 초상을 옮긴 뒤부터 구○○○으로 불리게 되었다. 새로 지은 ○○○에 옮긴 왕의 초상은 1950년 한국전쟁 당시 화재로 소실되어 아쉬움을 더 한다.","a":"창덕궁 선원전","c":"보물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614020.jpg"},{"q":"조선 후기 중국의 요동 지방에서 북경 근처의 계(薊) 지역에 이르기까지의 성책(城柵), 장성(長城) 등의 상황을 그린 ○○○○이다. 1706년(숙종 32)에 이이명(李頤命, 1658~1722)이 제작하여 왕에게 올린 것으로, ○○○○의 백미로 꼽힌다.","a":"요계관방지도","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614914.jpg"},{"q":"○○○○○는 ○○나성과 ○○○○○고분군 사이에 위치한 백제시대 절터유적으로, 1992년부터 2000년까지 6차례에 걸친 발굴조사 결과 중문, 목탑, 금당, 강당이 남북 일직선상에 배치된 이른바 일탑일금당(一塔一金堂)의 전형적인 백제 가람형식을 하고 있는 것으로 밝혀졌다. 특히 1993년 이 절터 내의 공방(工房)으로 생각되는 건물터에서 '백제금동대향로'가 출토되어 백제의 높은 금속공예기술 수준과 예술 역량을 널리 알리는 계기가 되었다.","a":"부여 능산리 사지","c":"사적","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626720.jpg"},{"q":"2개의 돌을 이어서 조각한 석불로 충청남도 ○○군 수암산 중턱에 위치하고 있다. 머리에는 두건같은 관(冠)을 쓰고 있고, 그 위에 6각으로 된 갓 모양의 넙적한 돌을 올려 놓았다. 어깨의 윤곽은 아래로 내려가면서 조금씩 넓어지지만 양감이 전혀없이 밋밋하여 마치 돌기둥 같다. 왼손은 몸에 붙인채 아래로 내리고 있고, 오른손은 가슴까지 올려 돌지팡이같은 것을 잡고 있는데 양 발 사이까지 길게 내려오고 있다.","a":"예산 삽교읍 석조보살입상","c":"보물","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617781.jpg"},{"q":"○○○○○은 중창기록과 건축양식으로 볼 때, 조선 현종 7년(1666)에 일향화상에 의해 건립되고 영조 47년(1773)에 중수가 완료되어 현재에 이르고 있는 것으로 판단된다. 정면3칸, 측면3칸 규모의 다포계 팔작지붕 건물로 기단은 지형을 고려하여 전면은 2단으로 높게 형성하고 배면과 측면은 1단으로 구성하였다. 기둥은 4면의 우주를 평주보다 크게 사용하였고, 전면과 후면 그리고 측면의 순서로 기둥 크기를 달리하여 정면성을 강조하고 있으며, 네 모서리에는 팔각형 초석 위에 팔각형 활주를 세워 구조적 안정을 꾀하고 있다.","a":"남해 용문사 대웅전","c":"보물","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2338501.jpg"},{"q":"직지사 비로전 앞에 세워져 있는 3층 석탑이다. 1974년 대웅전 앞 3층석탑 2기(보물 ○○○○○ 동ㆍ서 ○○○○)와 함께 경상북도 ○○ 웅창마을 북방 금강가의 옛 도천사터에서 옮겨온 것으로, 1단의 기단(基壇)위에 3층의 탑신(塔身)을 올리고 있다. 바닥돌은 넓적하게 짜여져 있으며, 그 위로 여러 장의 석재를 조성한 2단의 높직한 괴임을 두어 기단을 받치고 있다. 기단은 몇 개의 널돌로 구성되었으며 각 면의 모서리와 가운데에 기둥 모양의 조각을 두었다. 탑신은 몸돌과 지붕돌이 각각 한 돌로 이루어져 있고, 몸돌에는 모서리마다 뚜렷한 기둥 모양의 조각이 있다.","a":"문경 도천사지 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621260.jpg"},{"q":"이 건물은 일제강점기에 일본인 상업지역에 들어선 우동집으로, ○○에서는 처음으로 생긴 대형 일식집이었다. 건물 오른쪽으로 치우쳐 주출입구와 계단실을 설치하였고, 주 출입구 상부의 외벽에는 타일과 인조석을 교대로 사용하였으며, 상부는 삼각형의 페디먼트(pediment)로 장식하였다.","a":"전주 중앙동 구 박다옥","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668712.jpg"},{"q":"읍성이란 군이나 현의 주민을 보호하고, 군사적·행정적인 기능을 함께 하는 성을 말한다. 신라 신문왕(재위 681∼692) 때 지방 행정구역 개편에 따라 남원지역에 소경(지방도시)을 설치하였고, 691년에 쌓은 네모난 형태의 평지 읍성이다. 1597년에는 왜군의 침입에 대비하기 위해, 성을 크게 다시 쌓고 수리하여 담을 높였다. 그해 8월 조·명연합군과 왜군 사이에 전투가 벌어져 왜군에게 크게 패했고, 이때 싸우다 죽은 군인과 주민들의 무덤이 만인의총이다. 1894년 동학농민전쟁 때 많이 허물어져 약간의 성터 모습만 남아있다.","a":"남원읍성","c":"사적","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626884.jpg"},{"q":"○○○은 1동, 1층 규모로 건축면적 122.4㎡, 철로길이 좌·우 각각 150m이다. 경주,포항 사이는 1918년 10월 31일 개통되었고, 1935년 12월 16일 ○○, 울산, 경주 사이가 개통되었다. 동해남부선은 동해안의 해산물과 연선(沿線) 지방의 자원 수송을 목적으로 부설한 것이다. ○○○은 1934년 12월 16일 역원무배치 간이역으로 영업을 시작하여 1941년 6월 1일 보통역으로 승격(역사 신축 준공한 때로 판단)되었다. 그리고 1976년 7월 화물업무가 중단되었다.","a":"부산 송정역","c":"국가등록문화유산","nc":"","r":"부산광역시","s":"해운대구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667694.jpg"},{"q":"○○○○○ 밭 가운데에 있는 ○○으로, 1986년 ○○고적발굴조사단에서 발굴하여 무덤의 성격을 파악하였다. 내부는 돌방(석실)을 갖춘 굴식돌방무덤(횡혈식석실묘)으로, 도굴에 의해 피해는 입었지만 각종 토기류와 토용, 청동제십이지상이 발견되었다. 길이 12∼21㎝의 토용은 홀(笏:신하가 아침에 임금에게 문안을 올릴 때 예를 갖추기 위해 두 손에 모아쥐던 패)을 가진 문인상과 무인상 및 여인상이 있으며 일부는 붉은색 물감으로 채색되었다. 이들이 입고 있는 옷을 통해 당시 신라의 복식을 재현할 수 있게 되었다.","a":"경주 용강동 고분","c":"사적","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627899.jpg"},{"q":"고려 후기에 우리나라에서 처음으로 면화를 재배한 곳이다. 공민왕 12년(1363) 문익점은 중국 원나라에 사신으로 갔다가 돌아올 때, 밭을 지키던 노인이 말리는 것을 무릅쓰고 목화 몇 송이를 따서 그 씨앗을 붓통에 넣어가지고 왔다. 장인 정천익과 함께 시험재배를 하였는데, 처음에는 재배기술을 몰라 한 그루만을 겨우 살릴 수 있었다. 그러다가 3년간의 노력 끝에 드디어 성공하여 전국에 목화재배를 널리 퍼지게 하였다.","a":"산청 목면시배 유지","c":"사적","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628210.jpg"},{"q":"1937년 건립 이 건물은 일제 강점기 당시 소록도에 격리시킨 한센병 환자들을 관리, 감독했던 곳으로 일제의 인권 유린을 상징적으로 보여주는 건물이다. 사무 본관은 붉은색 벽돌 건물로 건립되었으나 현재 정면이 핑크색 타일로 마감되어 기본 골격만 건립 당시의 모습을 간직하고 있다. ○○은 사무 본관 뒤편으로 증축하여 복도로 연결하였으며, 기둥과 기둥 사이에는 마룻바닥 하부를 환기할 수 있도록 장방형의 환기구가 설치되어 있다.","a":"고흥 구 소록도갱생원 사무본관과 강당","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668876.jpg"},{"q":"속칭 전곡사지라고 일컫는 망제동의 서쪽 산기슭에 위치한 탑으로 낮은 단층기단 위에 7층탑신을 올린 방형 평면의 석탑이다. 이 석탑은 8매의 석재로 구성된 지대석 위에 1매의 판석형 석재로 조성한 낮은 단층기단을 놓았다. 기단은 거칠게 다듬었으며, 측면에는 아무런 조식도 없다. 측면 상단에는 갑석형의 굽을 돌렸는데, 상면은 약간 경사지게 다듬은 후 중앙에 낮은 받침을 조출해 탑신을 받고 있다. 이와같은 기단구조는 통일신라시대의 석탑에서는 볼 수 없는 특이한 형태로 운주사석탑군에서 볼 수 있어 고려시대에 시작된 기단의 한 유형임을 알 수 있다.","a":"정읍 천곡사지 칠층석탑","c":"보물","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618370.jpg"},{"q":"이 집은 ○○○ 이삼(李森)이 이인좌의 난(1728년)을 평정한 공로가 인정되어 영조 임금이 내린 하사금으로 지었다. 충남 출신의 ○○○ 선생은 범상치 않은 체력과 힘, 그리고 비범한 지략을 가지고 조선시대를 풍미했던 인물이다. 자연 경사지에 지은 집으로 동쪽을 바라보고 있는 대문채를 들어서면 조선시대 상류주택의 구성 요소인 안채와 사랑채가 ‘ㅁ’자형을 이루어 남쪽을 향하고 있다. 사당은 본채의 동쪽 위에 위치하고 있다.","a":"논산 백일헌 종택","c":"국가민속문화유산","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634452.jpg"},{"q":"고려시대 만들어진 ○○○○○로 높이 21.1㎝, 아가리 지름 6.7㎝, 밑지름 8.4㎝이다. 하늘에 오르기 직전 땅에 앉아있는 용(반룡) 모양을 새겼다고 하여 반용문주자로 불린다. 크기에 비해 아가리 지름이 넓으며, 전체적으로 안정된 형태를 이루고 있는 몸통과 손잡이가 있는 병모양의 ○○○이다. 물을 따르는 주구와 몸통은 번개무늬 띠를 2곳에 둘러 크게 3등분 되어 있다. 반용문은 몸통의 위쪽 2부분에 앞·뒤로 한 마리씩 모두 4마리가 새겨 있는데, 한마리는 아가리가 긴 삼각형의 얼굴이며, 다른 한마리는 사각형이어서 암수를 표현한 것으로 생각된다.","a":"청자 음각용문 주전자","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614715.jpg"},{"q":"○○○ 제1분화구 ○○ 능선에 일본군이 구축한 동굴형태의 진지이다. ○○○ 주변의 군사시설(비행장, 탄약고, 격납고 등) 경비와 연안으로부터 적의 상륙을 대비하기 위해 구축한 시설이다. 동굴과 출입구는 지네의 몸통 및 발과 같은 형태를 하고 있으며 폭은 1~2m 정도로 협소하고 확인된 입구는 22개이다. 태평양전쟁 말기, 수세에 몰린 일본이 ○○도를 저항기지로 삼아 구축한 일본군의 비행장 경비체계와 미군의 상륙전에 대비한 구체적 방어준비 현장을 살펴볼 수 있는 역사적 장소이다.","a":"제주 송악산 외륜 일제 동굴진지","c":"국가등록문화유산","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1669606.jpg"},{"q":"○○선생이 사용하던 사인(私印)으로 재료는 황색 옥석(玉石)이며 위쪽에 구름무늬가 새겨져 있다. 선생이 중국에서 활동하던 1940년쯤부터 1945년 11월 귀국시까지 이 ○○이 주로 사용되었으며, 중국 정부의 주요 인사에게 보낸 서한 대부분에 이 ○○이 찍혀있어 자료적 가치가 크다. < 규격(가로×세로×높이) : 18×18×50mm, 재료 : 옥석, 제작시기 : 1940년경 추정 >","a":"백범 김구 인장 金九之印","c":"국가등록문화유산","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668634.jpg"},{"q":"이 서첩은 봉래 양사언(蓬萊 楊士彦, 1517-1684)의 친필로 된 시문을 모아 엮은 것으로 허강(許강)의 ·서호별곡(西湖別曲)·을 옮겨 쓰고, 자신의 자작시와 국한문 시가를 필서하였다. 양사언은 조선 중기의 문인이자 서예가로 특히 해서와 초서에 능하여 안평대군(安平大君), 김구(金絿) , 한호(韓濩)와 함께 조선 전기 4대 서예가로 불렸다.","a":"봉래유묵","c":"보물","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614911.jpg"},{"q":"1942년 착수된 ○○ 황복사지 삼층석탑(국보) 해체수리 공사시 나온 사리함에서 ○○○○○ 금제여래입상(국보)과 함께 발견되었다. 사리함에 새겨진 글에 의하면 통일신라 성덕왕 5년(706)에 사리함 속에 순금으로 된 6치 크기의 아미타상을 넣었다고 하는데 바로 그 불상으로 추측되나, 이를 위해서는 당시의 도량형에 대한 추가적인 연구가 필요하다. 광배(光背)와 불신(佛身), 연꽃무늬 대좌(臺座)의 3부분으로 되어 있으며, 각 부분은 분리되도록 만들었다. 민머리 위에는 상투 모양의 머리(육계)가 큼직하게 솟아 있으며, 둥근 얼굴은 원만하다.","a":"경주 구황동 금제여래좌상","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611486.jpg"},{"q":"불교경전은 크게 경(經), 율(律), 론(論)으로 나누어지는데, 아비달마는 부처님의 지혜를 체계적으로 설명하고 있는 론(論)부분을 총칭하여 이르는 말이다. ○○○○○은 성불(成佛)하는 데 필요한 부처님의 지혜를 체계적으로 모아 설명하고 있는 책이라고 할 수 있다. 이 책은 고려 현종 때(재위 1011∼1031) 부처님의 힘으로 거란의 침입을 극복하고자 만든 초조대장경 가운데 하나로, 당나라의 현장(玄奘)이 번역한 ○○○○○ 16권 중 권 제12이다.","a":"초조본 아비달마식신족론 권12","c":"국보","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611883.jpg"},{"q":"­○○○ 소위가 1950년 10월 초 호남지구 진격 작전시 사용한 ○○○로 바탕에 무운장구를 염원하는 글귀와 서명, 지명이 기록되어 있어 당시 전투 경로 등을 연구할 수 있다.","a":"유관종 부대원 태극기","c":"국가등록문화유산","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668614.jpg"},{"q":"고려시대에 ○○해협을 지키던 외성의 요충지이다. 병자호란 뒤 ○○도를 보호하기 위한 방법으로 내성·외성·돈대·진보 등의 12진보를 만들었는데 그 중의 하나이다. 현종 7년(1666) 국방력 ○○를 위해 해군주둔지(수영)에 속해 있던 ○○○을 덕포로 옮겼으며, 숙종 5년(1679)에 용두돈대와 덕진돈대를 거느리고 덕진포대와 남장포대를 관할함으로써 ○○해협에서 가장 강력한 포대로 알려져 있었고, ○○ 12진보 가운데 가장 중요한 곳을 지키고 있었다.","a":"강화 덕진진","c":"사적","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625252.jpg"},{"q":"ㅇ ○○○○○은 둘레가 1,714m인 석축산성으로 ○○지역에 분포해 있는 성 중 가장 큰 규모임. 각자성석을 통해 초축시기를 추정할 수 있으며, 체성 상부의 여장까지 잔존하고 있어 축조 당시의 규모를 파악할 수 있음. 서해안에 자리한 관방유적으로 잔존유구가 잘 남아 있어 성벽 구조와 축성방법 등을 파악할 수 있기에 역사적·학술적 가치가 뛰어남","a":"태안 안흥진성","c":"사적","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2020110220232400.jpg"},{"q":"동북으로 남한산성과 이성산성이 보이는 분지에 있는 절터이며, 발굴조사시 금당터와 4곳의 건물터의 흔적이 발견되었다. 부처를 모시는 건물인 금당은 당시 매우 큰 건물이었고, 금당안에는 지름 5.1m의 8각 대좌 위에 부처를 모셨다. 유물로는 금동불상·기와·도자기·동으로 만든 불기류 등이 나왔고 ‘동사(桐寺)’라는 글씨를 새긴 기와가 나와 이 절의 이름이 동사였음을 알게 해준다. 절터에는 현재 두개의 석탑(보물)이 있다. 후삼국시대에서 고려 전기에 이르는 시기에 지어졌으며, 웅장하고 거대한 규모의 절로서 조선 전기까지 남아 있었으나 그 후에 폐사된 것으로 보인다.","a":"하남 동사지","c":"사적","nc":"","r":"경기도","s":"하남시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625829.jpg"},{"q":"순헌황귀비 엄씨가 1906년 5월 설립한 ○○○○○의 설립 초기 교사 자료인 ○○○, ○○, ○○ 3점의 유물로 교육사적 가치가 큰 유물이다. ○○○는 ‘明新女學校’라는 묵서와 함께 4괘와 태극문양을 틀을 사용하여 찍어낸 기법으로 제작한 것으로 당시로는 흔하지 않은 물감 사용 ○○○라는 점, 4괘의 배치가 특이한 점, 교육현장에서 발견된 최초의 ○○○라는 점에서 사료적 가치가 크다. ○○은 ‘明新女學校’ 글자를 양각으로 새겼고 네 가장자리는 조선시대 궁중 ○○의 일반적인 형식에 따라 액틀을 붙였으며 채색으로 화초문(花草紋)과 운두문(雲頭紋)을 장식했다.","a":"명신여학교 태극기·현판·완문","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667347.jpg"},{"q":"○○선생을 그린 ○○화이다. ○○ 선생은 1467년 이시애의 난을 평정해 적개공신에 오르고 후에 안동부사와 진주목사를 거쳤다. ○○화의 크기는 가로 105㎝, 세로 160㎝이며 비단 위에 채색하였다. 오른쪽을 바라보며 의자에 앉은 모습으로, 머리에는 사모를 쓰고 관복을 입고 있다. 갈색선으로 이목구비를 표시했고 흰색의 속옷 소매가 보인다. 왼쪽 다리부분의 안감과 녹색의 속옷이 보이며 의복선은 각지게 처리했다. 흰 가죽신을 신고 있는 모습이다. 안타깝게도 오랫동안 방치되어 떨어져나간 부분이 많지만, 그림의 색체나 윤곽 그리고 글은 비교적 뚜렷하다.","a":"손소 초상","c":"보물","nc":"","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622136.jpg"},{"q":"이 ○○는 ○○군과 나주시 경계 사이를 흐르는 ○○○을 가로지르는 다리이다. 고려 원종 14년(1273) 무안 법천사의 도승 고막대사가 도술로 이 다리를 놓았다는 전설이 있다. 총 길이 20m, 폭 3.5m, 높이 2.5m로서 5개의 교각 위에 우물마루 형식의 상판을 결구한 널다리로서 동쪽으로는 돌로 쌓은 석축도로가 7∼8m 연결되고 다시 물살을 가르기 위해 세운 최근의 콘크리트 다리가 이어지고 있다. ○○○○○는 널다리이면서도 목조가구의 결구수법인 주두의 가구법을 택한 것이 특징이다.","a":"함평 고막천 석교","c":"보물","nc":"","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619870.jpg"},{"q":"입 주위 넓은 테인 전이 달리고 향을 사르는 몸체 위에 구룡(龜龍)이 장식된 뚜껑이 있는 ○○로 총 높이 20.4㎝, ○○ 높이 10.2㎝, 입지름 10.2㎝이다. 머리를 쳐들고 앉아 있는 구룡은 거북 모양의 몸에 용의 머리를 지닌 신령스런 동물로 조각이 정교하고 생동감이 넘친다. 얼굴의 갈기와 목의 비늘 등이 가는 음각선으로 자세히 묘사되었으며, 거북 등무늬 안에 ‘王’자가 새겨져 있다. 거북이 앉아 있는 형태의 뚜껑은 몸통이 뚫려 있어, 밑짝에서 향을 피우면 몸통을 통해 벌린 입으로 향이 피어오르게 되어 있다.","a":"청자 구룡형뚜껑 향로","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614382.jpg"},{"q":"장승은 민간신앙의 한 형태로 마을이나 사찰 입구에 세워져 경계를 표시함과 동시에 잡귀의 출입을 막는 수호신 역할을 한다. ○○○ 입구에 있는 3기의 돌장승 역시 경계표시와 함께 경내의 부정을 막기 위해 세운 것으로 보여진다. 만수천의 해탈교를 건너기 전 마을쪽에 있는 돌장승이 옹호금사축귀장군(擁護金沙逐鬼將軍)이고, 해탈교를 건너자 마자 길 좌우에 2기의 돌장승이 마주보고 서 있다. 오른쪽 논두렁 가에 있는 돌장승이 상원주장군(上元周將軍)이고, 왼쪽의 괴목 아래 서 있는 돌장승이 대장군(大將軍)이다.","a":"남원 실상사 석장승","c":"국가민속문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634470.jpg"},{"q":"○○○ 무량수전 동쪽에 세워져 있는 석탑으로, 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 세운 모습이다. 기단에는 각 면의 모서리와 가운데에 기둥 모양의 조각을 두었는데, 아래층 기단은 가운데에 2개씩의 조각을 두고, 위층 기단에는 하나씩을 두었다. 탑신의 몸돌과 지붕돌은 각각 하나의 돌로 되어있는데, 몸돌은 모서리마다 기둥 모양을 조각하였으며, 지붕돌은 밑면의 받침이 5단으로 통일신라의 전형양식을 따르고 있다.","a":"영주 부석사 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620661.jpg"},{"q":"우리나라 최초의 근대식 병원인 제중원(濟衆院)의 책임을 맡았던 알렌이 발행한 우리나라 최고(最古)의 근대 서양식 ○○○이다. 1885.9.13. 알렌이 해관(海關, 옛 稅關) 직원 웰쉬(C. A. Welsch)에게 발급한 것으로 1-2주간의 요양이 필요하다는 내용이 적혀있다. 알렌(H. N.","a":"알렌의 진단서","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667289.jpg"},{"q":"○○○는 얼음을 저장하기 위해 땅을 파고 만들어둔 창고이다. 양쪽 벽을 이어주던 반원아치 형태의 홍예(虹霓)가 4군데 남아있을 뿐 천장은 완전히 무너져 불완전한 상태이다. 하지만 지금까지 남아있는 우리나라 ○○○ 가운데 경주 ○○○ 다음으로 큰 규모이고 쌓은 연대도 오래된 것이다. 동·서로 뻗은 긴 구조로, 서쪽에 문을 두었으며 계단을 따라 안으로 들어가면 경사진 바닥이 보인다. 가운데에는 물이 빠지는 길을 두고 동쪽에 구멍을 만들어, ○○○ 밖의 작은 개울로 물이 빠지도록 하였다. 환기 구멍을 뚫어 놓았던 것으로 예상되지만 현재는 어디인지 찾을 수가 없다.","a":"청도 석빙고","c":"보물","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1620774.jpg"},{"q":"본 건물은 지상 3층 철근콘크리트조, 모임기와지붕으로 경성공립공업학교의 근대 공업기술교육의 역사적 현장이다. 1916년 설립된 경성공업전문학교 부속 공업전습소를 경성공업학교로 개편하고 1938년 수업연한 5년의 공립공업학교로 개편하면서 교사를 대방동에 신축하게 되었다. 1956년 일부 수리하였다.","a":"서울공업고등학교 본관","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1666884.jpg"},{"q":"거대한 천연 암벽에 2구의 불상을 우람하게 새겼는데, 머리 위에는 돌갓을 얹어 토속적인 분위기를 느끼게 한다. 자연석을 그대로 이용한 까닭에 신체 비율이 맞지 않아 굉장히 거대한 느낌이 든다. 이런 점에서 불성(佛性)보다는 세속적인 특징이 잘 나타나는 지방화된 불상이다. 왼쪽의 둥근 갓을 쓴 원립불(圓笠佛)은 목이 원통형이고 두손은 가슴앞에서 연꽃을 쥐고 있다. 오른쪽의 4각형 갓을 쓴 방립불(方笠佛)은 합장한 손모양이 다를 뿐 신체조각은 왼쪽 불상과 같다. 지방민의 구전에 의하면, 둥근 갓의 불상은 남상(男像), 모난 갓의 불상은 여상(女像)이라 한다.","a":"파주 용미리 마애이불입상","c":"보물","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615671.jpg"},{"q":"충청북도 ○○군 한수면 동창리 월광사터에 전해오던 탑비로, 1922년 경복궁으로 옮겨 왔으며, 현재는 국립중앙박물관 경내에 있다. 통일신라 후기의 승려인 원랑선사(816∼883)의 행적을 기록한 탑비이다. 원랑선사는 문성왕 18년(856) 당나라에 유학하여 11년간 명산을 두루 돌아다니다 귀국한 뒤 월광사에 머물렀다. 68세로 입적하자 헌강왕이 ‘대보광선(大寶光禪)’이라는 탑명을 내려, 김영에게 비에 새길 글을 짓게 하였다. 글씨는 구양순체의 해서체로 순몽이 쓴 것이다. 비는 거북받침돌 위로 비몸을 세우고 머릿돌을 얹은 모습이다.","a":"제천 월광사지 원랑선사탑비","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613291.jpg"},{"q":"조선 14대 선조의 후궁이자 추존 원종이 생모(사친) 인빈 김씨(1555~1613)의 원이다. 인빈은 김한우의 딸로 1573년(선조 6) 선조의 후궁이 되어 4남(의안, 신성, 원종, 의창군) 5녀(정신, 정혜, 정숙, 정안, 정휘옹주)을 낳은 후, 1604년(선조 37) 인빈에 책봉되었다. 1623년 손자 인조가 반정으로 왕위에 오른 후 1636년(인조 14) 묘소 입구에 신도비를 세웠다. 이후 1755년(영조 31) 왕의 사친의 지위에 맞게 사당의 이름을 저경궁, 묘를 원으로 승격하여 이름을 ○○○이라 하였다.","a":"남양주 순강원","c":"사적","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/2020081317191600.jpg"},{"q":"이 석탑은 무너져 있던 것을 2000년∼2001년까지 2차례에 걸친 발굴조사를 선행한 후, 석탑 부재를 모아 2002년에 복원하였는데 노반석 아래의 부재는 남아있는 원 부재를 사용하였다. ○○○○○에 관한 문헌기록이 없어 ○○○○○이 언제 건립되었는지 확인할 만한 근거는 아직 밝혀지지 않고 있으나 탑지 주변에서 ‘용(茸)’자명을 비롯한 9점의 명문와가 출토되어 용장사(茸長寺)와의 연관성이 짐작된다. 용장사지(탑상곡 제 1사지)에는 ○○○○과 마애불좌상, 석불좌상이 전해오며, 그 일대에 여러 사찰이 있었던 것으로 보인다.","a":"경주 남산 용장계 지곡 제3사지 삼층석탑","c":"보물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2017040708555600.JPG"},{"q":"○○○○은 조선시대 만들어진 총 높이 22.5㎝, 뚜껑 높이 9.9㎝, 뚜껑 지름 17.4㎝, 아가리 지름 15.3㎝, 굽지름 9.4㎝인 조선시대 ○○○○이다. 뚜껑의 윗면 가운데에 꽃봉오리 모양의 꼭지가 달려 있고, 그 위로 두 줄의 음각선이 돌려져 있다. 뚜껑의 가장자리는 굴곡을 이루어 아래 몸체와 잘 맞도록 되어 있다. 아가리 부분은 오므라지고 두툼하게 단을 이루며 서서히 벌어져서, 몸체 아랫부분에서는 풍만하다. 밖으로 벌어진 다소 높은 굽다리와 어울려 기품 있고 수려한 멋을 풍긴다. 유약은 담청이 감도는 ○○유로 두껍게 전면을 칠했으며 은은한 광택이 흐른다.","a":"백자 반합","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613923.jpg"},{"q":"할아버지 권보의 덕을 기리기 위해 정조 16년(1792)에 권조가 지은 종가집이다. 50여 호 되는 마을 북쪽에 야산을 배경으로 자리잡고 있다. 권보는 일생동안 검소하게 살았던 사람으로 본채의 사랑채 지붕을 화려한 팔작지붕이 아닌 맞배지붕으로 한 것도 그의 소박함을 기리기 위함이다. 남향한 터에 'ㄷ'자형 안채, '一'자형 사랑채와 중문간채, '一'자형 별당, '一'자형 대문간채가 있다. 행랑채의 오른쪽 칸에 있는 문을 들어서면 넓은 앞마당을 사이에 두고 사랑채와 안채가 튼 'ㅁ'자형으로 배치되어 있다. 안채의 뒷쪽 높은 곳에는 1칸의 사당이 있다.","a":"안동 수곡고택","c":"국가민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1635356.jpg"},{"q":"○○○ 서북쪽 언덕 위에 세워져 있는 8각 ○○으로, 불을 밝혀두는 화사석(火舍石)을 중심으로 아래에는 세부분으로 이루어진 받침을 두고, 위로는 지붕돌과 머리장식을 얹은 모습이다. 받침에는 표면 전체에 꽃무늬를 가득 새겨 장식하고 있다. 화사석은 각 면에 무지개 모양의 창을 낸 후, 나머지 공간에 비천상(飛天像)과 이무기를 조각했다. 지붕돌은 두꺼우나 여덟 귀퉁이에서의 치켜올림이 경쾌하여 무거운 느낌을 덜어준다.","a":"여주 신륵사 보제존자석종 앞 석등","c":"보물","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615723.jpg"},{"q":"○○○선생은 일제강점기 중국 상해의 대한민국 임시정부, 국내에서 조선중앙일보와 조선건국 동맹 등을 결성하여 항일독립운동과 자주독립국가 건설을 위해 노력한 독립운동가이자 언론인으로 활동한 독립운동의 공적을 인정받아 대한민국장을 수여받은 인물로, 이 곳은 선생의 애국정신을 기릴 수 있는 역사적·교육적 가치가 큰 곳이다.","a":"서울 여운형 묘소","c":"국가등록문화유산","nc":"","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667591.jpg"},{"q":"1922년 무렵 건립 및 현 건물 1954년 신축 이 건물은 일제강점기에 금융 시설로 지어졌으며, 1954년 신축된 현 건물은 ○○○○으로 사용되고 있다. 전면 좌·우측 모서리와 왼쪽에 각각 부출입구를 두어 금융기관으로서의 접근성을 높인 것이 특징적이다. 상·하인방 및 처마 지붕 아래의 돌림띠의 수평적 요소와 세로로 긴 창과 굴뚝의 수직적 요소를 통해 근대적 조형성을 표현하고 있다.","a":"화순농협 동부지점","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668990.jpg"},{"q":"○○○ 극락보전 앞에 있는 탑으로, 기단(基壇)을 2단으로 마련한 후, 그 위로 여러 층의 탑신(塔身)을 세운 모습이다. 통일신라와 고려시대의 일반적인 석탑양식을 따르고 있으나 각 부분의 세부적인 조형방법은 전혀 달라서, 기단에서부터 탑신부까지 전부 한 장씩의 돌로 이루어져 있다. 바닥돌 윗면에는 연꽃을 돌려 새겼다. 아래층 기단의 네 모서리에 새겨진 기둥조각은 형식적이나, 특이하게도 물결무늬를 돋을새김해 두어 눈길을 끈다.","a":"여주 신륵사 다층석탑","c":"보물","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615691.jpg"},{"q":"○○○○○은 성황신을 섬기던 기록을 적은 ○○이다. ○○은 널빤지와 종이·비단에 글씨 또는그림을 그려 거는 것인데, 조선 명종때 제작된 원래의 ○○은 남아 있지 않고 영조때에 다시 새긴 ○○만이 남아 있다. 가로로 길쭉한 목판으로 나무 결이 그대로 살아 있으며, 위·아래 2개의 판을 이어붙여 하나로 만들었다. 가로 180㎝, 세로 54㎝ 목판에 총 73행, 1,600여자가 세로로 쓰여졌으며, 내용은 고려 충렬왕 7년(1281)부터 조선 순조 23년(1823)까지 성황신에게 작호를 부여했던 것부터 성황당을 고쳐 세웠던 것까지의 상황을 기록한 것이다.","a":"순창 성황대신 사적 현판","c":"국가민속문화유산","nc":"","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634552.jpg"},{"q":"전라도를 방어하는데 중요한 곳으로 노령산맥에 이어져 전북특별자치도 정읍과 경계를 이루고 있는 산성이다. 높이 626ｍ인 ○○○의 계곡 능선을 따라 만든 포곡식 산성으로 약 3.2㎞정도 남아 있다. ○○○○은 많은 고문헌에 기록이 남아 있으나 초축에 대하여는 확인할 수 있는 기록은 없고, 산성에 대한 최초 기록은 '고려사'와 '고려사절요'에서 확인되는데, 1256년(고종 43)에 송군비장군이 몽고군과의 전투에서 승리한 내용이 수록되어 있어 고려시대 이전부터 성이 있었던 것으로 짐작된다.","a":"장성 입암산성","c":"사적","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1627205.jpg"},{"q":"<○○○○○>는 사헌부에서 벼슬을 지낸 ○○○ 등 23명이 가졌던 계회를 토대로 제작된 계회도이다. 상단에는 전서로 쓴 표제가 있으며, 그 아래에는 계회를 하는 장면이 그려져 있고 찬시(贊詩)가 쓰여 있다. 그리고 하단에는 참가자들의 이름 및 품계, 그리고 그 부친의 관직 및 이름 등을 기록한 좌목(座目)이 있다. 이러한 체제는 조선조 초기 계회도에서 볼 수 있는 형식으로서 그 보다 후에 제작된 계회도에 비하여 그림 자체의 비중이 대단히 적으며, 참가자 부친에 대한 정보를 기재하기 위해 단을 따로 설정한 점도 이채롭다.","a":"이십삼 상대회도 및 김종한 교지","c":"보물","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1616089.jpg"},{"q":"부산시립박물관에 소장되어 있는 이 불상은 정면을 향해 가슴을 펴고 당당하게 서 있는 ○○○○상으로, 대좌(臺座)와 광배(光背)는 없어졌지만 비교적 잘 보존된 작품이다. 머리 위에는 상투 모양의 머리묶음(육계)이 높이 솟아 있으며, 이마에는 작은 구멍이 있어 예전에 관(冠)을 쓰고 있었던 것 같다. 이마의 머리카락은 사실적으로 표현하였으나 뒤에는 머리카락 표현이 없다. 풍만한 얼굴에는 반쯤 뜬 눈, 반달모양 눈썹, 오똑한 코가 새겨져 있으며, 잔잔한 미소가 번져 아름답고 자비로운 인상을 준다.","a":"금동보살입상(1979)","c":"국보","nc":"","r":"부산광역시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611958.jpg"},{"q":"○○○○○은 고려 공민왕 4년(1355)부터 조선 선조 24년(1591)까지의 고○○ 7매이다. 양이시가 고려 공민왕 4년(1355) 과거에 합격했음을 알리는 합격증서인 홍패(1355)와 그의 아들 양수생 역시 우왕 2년(1376) 문과에 급제했음을 알리는 홍패 등 2건을 주축으로 하고 있다.","a":"남원양씨 종중 문서 일괄","c":"보물","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618457.jpg"},{"q":"「○○○○○」는 효종(孝宗, 1619~1659)이 「제어옥후소천(題於屋後小泉: 거주하는 곳 뒤의 작은 샘터에서 쓰다)」이라고 말미에 부기(附記)한 어제○○○를 종이바탕에 행초(行草)로 쓴 것이다. 족자에 장황되었는데, 어필 위쪽에 붙인 황색 마름무늬 비단에는 “효묘어필진적(孝廟御筆眞蹟)”이란 제서(題書)가 쓰여 있다. ○○○○로서 어찰(御札) 등이 실린 «효종대왕어필»첩(규장각한국학연구원)을 비롯하여 몇몇 소품(小品)이 알려져 있으며, 대형 목판에 모각한 것도 전한다(보물 명안공주관련유물(明安公主關聯遺物)).","a":"효종어필 칠언시","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614949.jpg"},{"q":"○○은 선사시대 사람들이 조개를 먹고 버린 조가비와 생활 쓰레기들이 쌓여 이루어진 것으로 조개더미 유적이라고도 하는데 당시의 생활 모습을 잘 보여주는 유적이다. 바닷가에서 떨어진 얕으막한 언덕에 조개더미가 분포되어 있으나, 유적이 이루어질 당시엔 바닷가에 있었을 것으로 보인다. 유적의 층위는 위로부터 겉흙층·조가비섞임층·회색찰흙층으로 되어있다. 회색찰흙층에서는 쇠를 녹여내던 쇠부리터가 나왔는데, 이것은 우리나라 최초로 발견된 고대 제철 관계유적이다. 출토된 유물은 토기·뼈와 뿔로 만든 도구·철기·바늘·가락바퀴·독무덤(옹관묘) 등이 있다.","a":"부산 동래 패총","c":"사적","nc":"","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1625126.jpg"},{"q":"삼존목불좌상이 놓여져 있는데 이는 그 기법상 목불탱의 불보살과 똑같은 수법으로 만들어진 원각상(圓刻像)이라 하겠다. 본존상의 경우 육계가 생략되었고, 반달형의 중앙계주가 표현되었으며, 신체는 중후한 모습이지만 각 부분은 둥글게 처리되었다. 또한 통견의 불의는 그 두께가 두꺼워 신체 윤곽이 선명히 드러나지 않고 있으며 옷주름 또한 지극히 단순화되어 도식적인 느낌을 준다. 따라서 이 본존상이 목각탱과 동일한 작가에 의해 동시에 조성된 작품임이 확실하지만 목각탱에 비해 신체의 굴곡이 보다 유기적이고, 표현력도 뛰어나다.","a":"예천 용문사 목조아미타여래삼존좌상","c":"보물","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1621909.jpg"},{"q":"고려 전기의 승려인 통일대사의 행적을 기록하고 있는 비로, ○○○ 동남쪽의 보개산 계곡을 따라 1㎞쯤 떨어진 산 중턱에 자리잡고 있다. 통일대사는 고려 전기에 중국유학을 다녀온 이로, 그가 왕실에서 불교의 교리를 강의하자 각지에서 사람들이 구름처럼 몰려들었다고 한다. 대사가 입적하자 광종은 ‘통일대사’라는 시호를 내리고 당대의 문장가였던 김정언에게 비문을 짓도록 하였다. 돌로 쌓은 축대 위에 세워져 있는 비는 거북받침돌 위로 비몸을 세우고, 머릿돌을 얹은 구조이다.","a":"괴산 각연사 통일대사탑비","c":"보물","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617244.jpg"},{"q":"「○○○○○」는 1686년(숙종 12년) 건립되고 1884년(고종 21년)과 1888년(고종 25년) 중수된 정자로, 자연암반으로 형성된 동굴에 위치하여 비정형적인 틈 사이에 건물이 끼워져 있음. 또한 상부로 휜 창방(기둥머리를 좌우로 연결하는 부재)의 사용, 방 내부의 연등천장 구성, 바위 틈새를 적절하게 출입구로 활용한 점, 진입의 과정에서 경험하는 어두움과 밝음의 극적 대비 등은 정형의 건물이 대부분을 차지하는 당시의 시대에 파격적으로 시도되었던 건축 형식을 보여줌.","a":"진안 수선루","c":"보물","nc":"","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/2019122715290500.JPG"},{"q":"조선시대 만들어진 높이 16.8㎝, 입지름 6.1㎝, 밑지름 8.8㎝의 뚜껑있는 ○○ 항아리이다. 뚜껑의 손잡이는 연꽃봉오리 모양이며, 어깨는 벌어졌고 잘록한 허리의 선은 바닥에서 약간 도드라지는 듯한 느낌을 준다. 굽의 접지면 바깥둘레는 약간 경사지게 깎아내렸다. 뚜껑의 손잡이에 꽃잎 4장을 그리고 그 주위에 매화와 대나무를 그린 것이, 조선 전기 회화에서 보이는 수지법(樹枝法)과 비슷하다. 아가리 가장자리에 꼬불꼬불하게 이어진 덩굴무늬를 그리고, 몸체의 한 면에는 한 쌍의 새가 앉아있는 매화와 들국화를, 다른 한 면에는 V자형으로 뻗어나간 대나무를 그렸다.","a":"백자 청화매조죽문 유개항아리","c":"국보","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611621.jpg"},{"q":"자연을 벗삼아 쉼터로 사용하고자 지은 ○○○은 호남지방에서 으뜸가는 정자 건축이다. 통일신라 헌안왕(재위 857∼861) 때 최치원이 세웠다는 이야기가 있지만 지은 시기는 확실하게 알 수 없다. 기록에 따르면 조선 광해군 때 현감 이지굉이 다시 짓고 현종 때 현감 박숭고가 건물을 넓혔으며, 지금 크기로는 숙종 42년(1716) 현감 유근(柳近)이 넓혀 세웠다고 한다. 그 뒤에도 몇 차례 부분적으로 고쳤는데 단청은 1974년에 다시 칠한 것이다. 규모는 앞면 5칸·옆면 4칸이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다.","a":"정읍 피향정","c":"보물","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1618288.jpg"},{"q":"고려의 승려 보조국사(普照國師) 지눌(知訥)이 지은 『○○○』은 조선 세조 때의 승려 혜각존자(慧覺尊者) 신미(信眉)가 언해한 책이다. ○○○는 지눌의 법호(法號)이며, ‘○○○’은 지눌이 선종(禪宗)과 교종(敎宗)의 대립을 막고 인간의 참다운 모습을 밝히고자 하여 저술한 글이다. 본서에는 ‘○○○’ 외에도 「환산정응선사시몽산법어(皖山正凝禪師示蒙山法語)」등 4편의 법어(法語)가 함께 묶여 있다. 규장각 소장본은 1467년(세조 13) 간경도감(刊經都監)에서 목판으로 간행한 책이다.","a":"목우자수심결(언해)(1984)","c":"보물","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613875.jpg"},{"q":"○○○○으로 완전하거나 원형복원이 가능한 것은 현재까지 소수의 예만이 알려지고 있는데 이 ○○○○○은 그 중에서도 가장 회화적인 문양이 상감된 작품이다. 주제와 여백이 효과적으로 조화되고 흑백상감과 철채기법이 어울려서 색상대비가 뛰어나다. 특히, 새와 나무에서 중요한 부분은 흑백상감으로 새기고 기타 몸통·꼬리 등의 필요한 부분은 철화로 그려서 흑상감보다 명도가 낮게 나타나 기법에 따른 농담을 효과적으로 응용하였다. 장식기법이 독특하고 회화적 소재를 능숙하게 다룬 점뿐 아니라 ○○의 크기도 흔치않게 작아서 도자사적으로 매우 귀중한 자료이다.","a":"청자 상감화조문 도판","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614849.jpg"},{"q":"○○○○○은 충청남도 ○○군 규암면 ○○에 있는 옛 절터에서 출토된, 다양한 문양과 형상을 새긴 후 구워서 만든 백제 때 벽돌(전)이다. 산수문전·산수봉황문전·산수귀문전·연대귀문전·반용문전·봉황문전·와운문전·연화문전으로 8매의 벽돌이다. 이 벽돌은 정사각형에 가까우며, 한변이 29㎝내외, 두께 4㎝로, 네모서리에는 각기 홈이 파여있어 각 벽돌을 연결하여 건물의 바닥이나 벽면을 장식했으리라 추정된다. 산수문전은 상단의 상서로운 구름 아래로 3개의 봉우리로 이루어진 산이 있고, 하단에는 물이 있다.","a":"부여 외리 문양전 일괄","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1613261.jpg"},{"q":"○○읍 중앙동에 위치한 ○○이다. ○○은 민간신앙에서 신이 있다고 믿고 섬기는 것으로, ‘당’혹은 ‘신당’이라고도 한다. 중앙동을 중심으로 동·서·남 방향의 상거리·하거리·중거리에 각각 1쌍의 ○○이 있고, 마을 북쪽의 교촌리에 3기의 ○○이 있다. 이곳에서는 각 쌍의 ○○을 할아버지당, 할머니당으로 부르는데, 그 이름에 따라 외형을 구분할 수 있는 특징은 없다.","a":"고창 오거리 당산","c":"국가민속문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/imp_folklore_material/thumb/1634459.jpg"},{"q":"가야 10대 임금인 구형왕의 무덤으로 전해지고 있는 돌무덤으로, 구형왕은 구해(仇亥) 또는 양왕(讓王)이라 하는데 김유신의 증조부이다. 521년 가야의 왕이 되어 532년 신라 법흥왕에게 영토를 넘겨줄 때까지 11년간 왕으로 있었다. 이 무덤을 둘러싸고 종래에는 석탑이라는 설과 왕릉이라는 2가지 설이 있었다. 이것을 탑으로 보는 이유는 이와 비슷한 것이 안동과 의성지방에 분포하고 있는데 근거를 두고있다.","a":"산청 전 구형왕릉","c":"사적","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1628266.jpg"},{"q":"ㅇ ○○○○○는 철근콘크리트 2층 건축물로서 지붕은 철근콘크리트 평슬래브로 되어 있으며, 평면은 전체적으로 L형으로서, 도로 가각부는 원형으로 처리하였고 그 상부에 상징적인 수직 조형물을 두어 중심성을 강조하였음 ㅇ 중일전쟁 이후 국가가 식량 가격 및 유통량을 조절·관리하기 위해 설립한 ○○○○○의 ○○○○○ 건물로 일제에 의한 호남평야지역 쌀 수탈의 역사를 간직한 증거물로 가치가 있음","a":"구 조선식량영단 군산출장소","c":"국가등록문화유산","nc":"","r":"전북특별자치도","s":"군산시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/2031577.jpg"},{"q":"○○○는 지리산 남쪽 기슭에 있는 절로 통일신라시대에 지었다고 전한다. 조선시대에는 선종대본산(禪宗大本山) 큰절이었는데, 임진왜란 때 완전히 불타버린 것을 인조 때 다시 지어 오늘에 이르고 있다. 원래 ○○○터에는 3층의 장육전이 있었고 사방의 벽에 화엄경이 새겨져 있었다고 하나, 임진왜란 때 파괴되어 만여점이 넘는 조각들만 절에서 보관하고 있다. 조선 숙종 28년(1702)에 장륙전 건물을 다시 지었으며, ‘○○○’이란 이름은 임금(숙종)이 지어 현판을 내린 것이라고 한다.","a":"구례 화엄사 각황전","c":"국보","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612538.jpg"},{"q":"충청남도 ○○시 풍세면 태학산의 해선암 뒷산 기슭 큰 바위에 높이 7.1m나 되는 거대한 불상이 조각되어 있으며 마애불 윗부분의 바위에는 건물이 있었던 흔적이 남아 있다. 얼굴 부분은 도드라지게 조각하고 신체는 선을 이용하여 표현하였는데, 이는 고려 후기 마애불의 일반적인 양식으로 이 작품이 만들어진 시기를 짐작할 수 있게 해준다. 민머리 위에는 둥근 상투 모양의 머리묶음이 큼직하게 솟아 있다. 양감있는 넓적한 얼굴은 가는 눈·커다란 코·작은 입으로 인해 더욱 경직된 인상을 풍긴다.","a":"천안 삼태리 마애여래입상","c":"보물","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1617742.jpg"},{"q":"범허사라고 전하는 경상남도 ○○의 옛 절터에 무너져 있던 것을 1941년경 대구의 일본인 골동상이 구입하여 공장에 세워 놓았으나, 1947년 경복궁으로 이전되었으며 현재는 국립진주박물관에 보관되어 있다. 탑은 2단의 기단(基壇) 위에 3층의 탑신(塔身)을 올린 일반적인 모습이다. 바닥돌과 기단의 아래부분은 옮겨 세울 당시 시멘트로 보강한 탓에 원래의 구조는 알 수 없다. 기단의 네 모서리와 각 면의 가운데에는 기둥을 본떠 새겼는데, 아래층의 가운데기둥은 2개씩, 위층은 1개씩을 두었다.","a":"산청 범학리 삼층석탑","c":"국보","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1611553.jpg"},{"q":"<○○○○○>는 소속이 같은 문인들의 친목도모와 풍류를 즐기기 위한 모임을 그린 계회도이다. 비단바탕에 엷고 산뜻한 채색으로 그린 이 그림은 가로 59㎝, 세로 94㎝ 크기이다. 이 그림은 중단의 계회장면과 더불어 상단의 계회명칭 및 하단에는 참석자들의 이름·본관 등의 사항을 기록하였는데, 계회장면을 제외한 나머지 부분이 잘려나가 계회의 구체적인 내용과 참석자들은 알 수 없다. 그림은 산수를 배경으로 옥내 안에는 일곱 명의 참석자들이 원을 그리며 앉아 있고 그 오른쪽에는 여인들이 줄지어 앉아 있다.","a":"연정계회도","c":"보물","nc":"","r":"서울특별시","s":"용산구","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1614147.jpg"},{"q":"○○○에는 우리나라에서 하나밖에 없는 목탑인 팔상전(국보)과 기발한 착상과 원숙한 조각솜씨로 조각한 쌍사자 석등(국보), 한국 제일의 석연지(국보), 사천왕석등(보물), 마애여래의상(보물), 대웅전(보물), 원통전(보물), 신법천문도(보물) 등과 충청북도 유형문화유산으로 지정된 여러 문화유산이 있어 신앙유적으로서 학술적 가치가 크다.","a":"보은 법주사","c":"사적","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626395.jpg"},{"q":"○○○○는 1941년 7월 25일 영업을 개시한 1동 1층 규모의 아담한 역사다. 1974년 3월 15일 소화물 취급이 중단되었으며, 현재 여객취급업무는 하지 않고 있다. 역사는 2009년 미술관으로 개관하여 지역주민들에 문화공간의 역할을 하고 있다 벽체는 비닐판벽의 외장이었다가 후에 흙벽에 시멘트 뿔칠 마감으로 변경되었으며, 지붕은 시멘트기와로 이어져 있다.","a":"원주 구 반곡역사","c":"국가등록문화유산","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668419.jpg"},{"q":"○○○○○은 정교성과 화려함을 두루 갖춘 보관, 이국적이면서도 우아한 귀족풍의 얼굴모습, 단정하고 엄숙하면서도 안정된 신체비례, 간결하지만 탄력 넘치는 옷주름의 표현, 불신 전반에 걸쳐 정교하게 장엄된 영락 장식 등 품격 높은 고려 불교문화의 한 단면을 뚜렷이 보여준다. 이 관음보살좌상은 조성발원문이 남아있지 않지만 현존하는 작품과의 비교를 통해 13세기 전반기에 조성된 보살상으로 추정되는데, 현재 이 시기의 보살상이 거의 남아 있지 않은 점에서 그 자료적 가치는 매우 높다 하겠다. ○○○○○에서는 10종 194점에 이르는 ○○○○이 함께 발견되었다.","a":"안동 보광사 목조관음보살좌상 및 복장유물","c":"보물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1622253.jpg"},{"q":"○○ 기양리에 있는 백제 때의 절터이다. 『삼국유사』에 의하면 백제 무왕 때 왕이 왕비와 사자사(師子寺)에 가던 도중 용화산 밑의 연못에서 미륵삼존이 나타났는데, 왕비의 부탁에 따라 이 연못을 메우고 3곳에 탑, 금당, 회랑을 세웠다고 한다. 기록에 따르면 ○○○는 백제 무왕 때 지어져 조선시대에 폐사되었음을 알 수 있다. 절의 배치는 동·서로 석탑이 있고 중간에 목탑이 있으며 탑 뒤에는 부처를 모시는 금당이 각각 자리한다. 이것이 복도(회랑)로 구분되어 매우 특이한 가람배치를 하고 있다.","a":"익산 미륵사지","c":"사적","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626828.jpg"},{"q":"1936년 건립 이 건물은 ○○ 지역을 대표하는 최초의 공립학교 ○○로서, 고 육영수 여사가 여기에서 배운 것으로 알려져 있다. 교실의 천장은 목재반자로 마감하였으나, 복도는 마감을 별도로 하지 않고 지붕 골조를 그대로 노출하여 보다 풍요로운 공간을 연출하고 있다. 건립 당시의 모습이 비교적 그대로 남아 있어 우리나라 근대기의 학교 건축 양식을 잘 보여주고 있다.","a":"옥천 죽향초등학교 구 교사","c":"국가등록문화유산","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668498.jpg"},{"q":"높이 4.5m, 너비 8m의 ‘ㄱ’자 모양으로 꺾인 절벽암반에 여러 가지 모양을 새긴 바위그림이다. 바위에는 육지동물과 바다고기, 사냥하는 장면 등 총 200여점의 그림이 새겨져 있다. 육지동물은 호랑이, 멧돼지, 사슴 등이 묘사되어 있는데, 호랑이는 함정에 빠진 모습과 새끼를 밴 호랑이의 모습 등으로 표현되어 있다. 멧돼지는 교미하는 모습을 묘사하였고, 사슴은 새끼를 거느리거나 밴 모습 등으로 표현하였다. 바다고기는 작살 맞은 고래, 새끼를 배거나 데리고 다니는 고래의 모습 등으로 표현하였다.","a":"울주 대곡리 반구대 암각화","c":"국보","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/national_treasure/thumb/1612022.jpg"},{"q":"­ 마을 뒤에서 손쉽게 얻을수 있는 막돌을 사용하여 쌓은 돌담. 막돌을 메쌓기한 것, 막돌과 흙을 교대로 쌓아 올린 것 등 여러 형식이 있다. 주민들이 돌담에 애착을 가지고 보존함","a":"신안 비금도 내촌마을 옛 담장","c":"국가등록문화유산","nc":"","r":"전남광주통합특별시","s":"신안군","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1668997.jpg"},{"q":"○○○ 대웅전에 모셔져 있는 나무로 만든 삼세불좌상으로, 중앙의 석가모니불을 중심하여 왼쪽에는 약사불이 배치되고 오른쪽에는 아미타불이 자리하고 있다. 석가모니불은 주존불로서 삼불 가운데 가장 크고 건장한 신체에 무릎이 넓어 안정되어 보인다. 육계의 구분이 명확하지 않은 머리에는 정상계주와 중앙계주를 큼직하게 묘사하였으며 네모꼴의 얼굴에는 잔잔한 미소가 엿보인다. 두 귀는 길어서 어깨까지 늘어졌고, 약간 굵어진 목에는 세 개의 주름인 삼도(三道)가 뚜렷하다. 옷은 양어깨를 모두 덮고 있는 형식으로 오른팔을 드러냈으며, 옷주름은 두 다리 위로 자연스럽게 흘러내리고 있다.","a":"영광 불갑사 목조석가여래삼불좌상","c":"보물","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1619886.jpg"},{"q":"고려의 승려 제관이 천태사상을 집약하여 정리한 것으로 이론과 실천이 같이 어울려야 비로소 깨달음을 얻을 수 있다는 내용을 담고 있다. 닥종이에 찍은 목판본으로 2권의 책 중 상권 1책이며 크기는 세로 24.5㎝, 가로 16.5㎝이다. 책 끝에 있는 목암노인이 쓴 글에 의하면, 오래된 판본이 있었는데 글자가 크고 책이 무거워 휴대하기 불편하여 굉지대선사(宏之大禪師)가 수여(水如)에게 다시 쓰도록 하여 충숙왕 2년(1315)에 기복도감(祈福都監)에서 간행한 것이다.","a":"천태사교의","c":"보물","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/treasure/thumb/1615948.jpg"},{"q":"1930년 건립 이 건물은 대전전기주식회사에 소속된 발전소였으나, 2005년까지 한전 대전 ○○○ 창고 건물로 사용되다가, 현재는 전력연구원 연구시설로 사용되고 있다. 솟을지붕이 있어 환기와 채광 그리고 조형성을 함께 살리고 있으며, 2층 규모의 발전소 시설과 3층 규모의 업무 시설이 맞붙어 건립되었다. 내부 천장에는 발전 설비를 이동시킬 수 있도록 견고한 철제 빔을 설치하였고 건축적 완성도가 높은 건물이다.","a":"한국전력공사 대전보급소","c":"국가등록문화유산","nc":"","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/register/thumb/1667953.jpg"},{"q":"○○○○에 대한 최초의 기록은 효종 7년(1656)에 편찬된 『동국여지도』 이며 이책에는 ○○○○가 삼국시대의 유적임이 명시되어 있고 최초의 학술조사 기록은 1919년에 발간된 『조선고적조사보고』이다. 이 보고서에는 도면과 함께 사진을 싣고 있으며 삼국시대 성으로서의 중요성이 기술되어 있다. 그 후 1991년부터 2003년 사이 본격적인 학술조사 및 발굴조사가 이루어지게 되었다. 성의 형태는 북동쪽에서 남서 방향으로 흐르는 임진강에 접한 현무암 천연절벽의 수직단애 위에 있는 삼각형의 강안평지성(江岸平地城)이다.","a":"연천 호로고루","c":"사적","nc":"","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/history_site/thumb/1626004.jpg"}]);